"""Протей — весь проект в одном файле. Для Google Colab и Kaggle.

Это автосборка: 35 модулей пакета ultranet (8,142 строк) встроены
ниже как исходники и регистрируются в sys.modules. Импорты работают
как у обычной установки:

    from ultranet.models import GPT, GPTConfig
    from ultranet.proteus import Proteus, MatFormer

Обучение языковой модели на TinyStories:

    !pip install -q datasets
    !python proteus_colab.py --steps 200                    # проба
    !python proteus_colab.py --steps 60000 --max-hours 11   # полный прогон

Проба обязательна. Единственный критерий: стартовый loss должен быть
примерно ln(vocab_size) — для словаря 4096 это 8.3. Сильно больше —
сломана инициализация, сильно меньше — словарь не тот.

Без аргументов запускает самопроверку: обучает крошечный GPT и печатает
сводку по возможностям.

Сгенерировано tools/make_bundle.py — правьте исходники, не этот файл.
"""
from __future__ import annotations

import sys
import types
from importlib.machinery import ModuleSpec

# ═════════════════════════════════════════════════════════════════════
# Исходники пакета. Каждый модуль хранится строкой и исполняется ниже
# в собственном пространстве имён.
# ═════════════════════════════════════════════════════════════════════
_SOURCES = {}

_SOURCES['ultranet'] = '"""UltraNet — ультимативная нейросетевая библиотека на чистом NumPy.\n\nСобственный автоград, современные слои (RoPE, RMSNorm, SwiGLU, MHA с KV-кэшем),\nоптимизаторы (AdamW, Lion, Lookahead, EMA), тренер и модели вплоть до GPT.\n"""\nfrom . import checkpoint, data, functional, models, nn, optim, proteus, tokenizer\nfrom .data import (\n    CharTokenizer,\n    DataLoader,\n    Dataset,\n    WordTokenizer,\n    make_lm_batches,\n    make_moons,\n    make_regression,\n    make_spirals,\n    normalize,\n    train_test_split,\n)\nfrom .functional import (\n    accuracy,\n    bce_with_logits,\n    binary_cross_entropy,\n    confusion_matrix,\n    cross_entropy,\n    f1_score,\n    focal_loss,\n    huber_loss,\n    mae_loss,\n    mse_loss,\n    nll_loss,\n    perplexity,\n    top_k_accuracy,\n)\nfrom .models import GPT, MLP, ConvNet, GPTConfig, ResNet, TextClassifier\nfrom .optim import (\n    EMA,\n    SGD,\n    Adagrad,\n    Adam,\n    AdamW,\n    CosineWarmup,\n    Lion,\n    Lookahead,\n    OneCycleLR,\n    ReduceLROnPlateau,\n    RMSprop,\n    StepLR,\n)\nfrom .tensor import (\n    Tensor,\n    cat,\n    get_rng,\n    manual_seed,\n    no_grad,\n    ones,\n    randn,\n    stack,\n    tensor,\n    zeros,\n)\nfrom .checkpoint import load_checkpoint, save_checkpoint\nfrom .gradcheck import gradcheck, numeric_grad\nfrom .tokenizer import BPETokenizer\nfrom .trainer import Trainer\n\n__version__ = "7.0.0"\n\n__all__ = [\n    # ядро\n    "Tensor", "tensor", "zeros", "ones", "randn", "stack", "cat", "no_grad",\n    "manual_seed", "get_rng",\n    # пакеты\n    "nn", "optim", "data", "functional", "models", "proteus",\n    # модели\n    "MLP", "ConvNet", "ResNet", "GPT", "GPTConfig", "TextClassifier",\n    # оптимизаторы и расписания\n    "SGD", "Adam", "AdamW", "RMSprop", "Adagrad", "Lion", "Lookahead", "EMA",\n    "CosineWarmup", "OneCycleLR", "StepLR", "ReduceLROnPlateau",\n    # обучение и данные\n    "Trainer", "DataLoader", "Dataset", "CharTokenizer", "WordTokenizer", "BPETokenizer",\n    "save_checkpoint", "load_checkpoint", "gradcheck", "numeric_grad",\n    "make_spirals", "make_moons", "make_regression", "make_lm_batches",\n    "train_test_split", "normalize",\n    # потери и метрики\n    "cross_entropy", "nll_loss", "binary_cross_entropy", "bce_with_logits", "focal_loss",\n    "mse_loss", "mae_loss", "huber_loss",\n    "accuracy", "top_k_accuracy", "perplexity", "confusion_matrix", "f1_score",\n]\n'

_SOURCES['ultranet.__main__'] = 'from .cli import main\n\nmain()\n'

_SOURCES['ultranet.benchmark'] = '"""Бенчмарк: скорость ключевых операций и выигрыш от оптимизаций."""\nfrom __future__ import annotations\n\nimport time\nfrom typing import Callable\n\nimport numpy as np\n\nimport ultranet as un\nfrom ultranet import nn\nfrom ultranet.tensor import Tensor, no_grad\n\n\ndef timeit(fn: Callable, n: int = 20, warmup: int = 3) -> float:\n    """Среднее время вызова в миллисекундах."""\n    for _ in range(warmup):\n        fn()\n    t0 = time.perf_counter()\n    for _ in range(n):\n        fn()\n    return (time.perf_counter() - t0) / n * 1000\n\n\ndef _row(name: str, ms: float, extra: str = "") -> None:\n    print(f"  {name:<38} {ms:8.2f} ms  {extra}")\n\n\ndef bench_ops() -> None:\n    print("\\n▸ Базовые операции (batch=128, dim=256)")\n    x = Tensor(np.random.randn(128, 256).astype(np.float32), requires_grad=True)\n    w = Tensor(np.random.randn(256, 256).astype(np.float32), requires_grad=True)\n\n    def fwd_bwd():\n        x.grad = w.grad = None\n        ((x @ w).gelu() ** 2).sum().backward()\n\n    _row("matmul+gelu forward+backward", timeit(fwd_bwd))\n    _row("softmax (fused)", timeit(lambda: x.softmax(-1)))\n\n    logits = Tensor(np.random.randn(256, 1000).astype(np.float32), requires_grad=True)\n    y = np.random.randint(0, 1000, 256)\n\n    def ce():\n        logits.grad = None\n        un.cross_entropy(logits, y).backward()\n\n    _row("cross_entropy fwd+bwd (vocab=1000)", timeit(ce))\n\n\ndef bench_grad_mode() -> None:\n    print("\\n▸ Выигрыш no_grad() на инференсе")\n    m = un.MLP([256, 512, 512, 10])\n    x = Tensor(np.random.randn(128, 256).astype(np.float32))\n    with_graph = timeit(lambda: m(x), n=20)\n\n    def infer():\n        with no_grad():\n            m(x)\n\n    without = timeit(infer, n=20)\n    _row("forward со сборкой графа", with_graph)\n    _row("forward под no_grad()", without, f"ускорение x{with_graph / max(without, 1e-9):.2f}")\n\n\ndef bench_layers() -> None:\n    print("\\n▸ Слои")\n    conv = nn.Conv2d(16, 32, 3, padding=1)\n    img = Tensor(np.random.randn(16, 16, 32, 32).astype(np.float32), requires_grad=True)\n\n    def conv_fb():\n        img.grad = None\n        conv(img).sum().backward()\n\n    _row("Conv2d 16->32, 16x32x32 fwd+bwd", timeit(conv_fb, n=5))\n\n    attn = nn.MultiHeadAttention(256, 8)\n    seq = Tensor(np.random.randn(8, 128, 256).astype(np.float32), requires_grad=True)\n\n    def attn_fb():\n        seq.grad = None\n        attn(seq).sum().backward()\n\n    _row("Attention B8 T128 D256 fwd+bwd", timeit(attn_fb, n=5))\n\n    ln, rn = nn.LayerNorm(512), nn.RMSNorm(512)\n    z = Tensor(np.random.randn(256, 512).astype(np.float32))\n    lm, rm = timeit(lambda: ln(z)), timeit(lambda: rn(z))\n    _row("LayerNorm", lm)\n    _row("RMSNorm", rm, f"x{lm / max(rm, 1e-9):.2f} быстрее LayerNorm")\n\n\ndef bench_generation() -> None:\n    print("\\n▸ Генерация GPT: KV-кэш против полного пересчёта")\n    cfg = un.GPTConfig(vocab_size=96, block_size=128, n_layer=4, n_head=4, n_embd=128)\n    model = un.GPT(cfg).eval()\n    print(f"  модель: {model.num_params():,} параметров, block_size={cfg.block_size}")\n    prompt = list(np.random.randint(0, 96, 64))\n    n_tok = 32\n\n    t0 = time.perf_counter()\n    model.generate(prompt, n_tok, temperature=0.8, use_cache=False, seed=0)\n    slow = (time.perf_counter() - t0) * 1000\n    t0 = time.perf_counter()\n    model.generate(prompt, n_tok, temperature=0.8, use_cache=True, seed=0)\n    fast = (time.perf_counter() - t0) * 1000\n\n    _row(f"без кэша ({n_tok} токенов)", slow, f"{slow / n_tok:.1f} ms/токен")\n    _row(f"с KV-кэшем ({n_tok} токенов)", fast,\n         f"{fast / n_tok:.1f} ms/токен — x{slow / max(fast, 1e-9):.2f}")\n\n\ndef bench_training() -> None:\n    print("\\n▸ Пропускная способность обучения")\n    cfg = un.GPTConfig(vocab_size=64, block_size=64, n_layer=3, n_head=4, n_embd=128)\n    model = un.GPT(cfg)\n    opt = un.AdamW(model.parameters(), lr=1e-3)\n    ids = list(np.random.randint(0, 64, 5000))\n    batch = 8\n\n    def step():\n        xb, yb = un.make_lm_batches(ids, cfg.block_size, batch)\n        loss = un.cross_entropy(model(xb), yb)\n        opt.zero_grad()\n        loss.backward()\n        opt.step()\n\n    ms = timeit(step, n=5, warmup=2)\n    tps = batch * cfg.block_size / (ms / 1000)\n    _row(f"GPT {model.num_params():,} парам., шаг обучения", ms, f"{tps:,.0f} токенов/с")\n\n\ndef run_all() -> None:\n    np.random.seed(0)\n    print("=" * 72)\n    print("UltraNet — бенчмарк (чистый NumPy, CPU)".center(72))\n    print("=" * 72)\n    bench_ops()\n    bench_grad_mode()\n    bench_layers()\n    bench_generation()\n    bench_training()\n    print("\\n" + "=" * 72)\n\n\nif __name__ == "__main__":\n    run_all()\n'

_SOURCES['ultranet.checkpoint'] = '"""Чекпоинты: сохранение модели вместе с состоянием оптимизатора и метаданными.\n\nВ отличие от `model.save()`, позволяет продолжить обучение ровно с того места,\nгде оно прервалось (моменты Adam, счётчик шагов, расписание lr).\n"""\nfrom __future__ import annotations\n\nimport pickle\nfrom typing import Any, Dict, Optional\n\nimport numpy as np\n\nfrom .nn import Module\nfrom .optim import Optimizer\n\n\ndef _optim_state(opt: Optimizer) -> Dict[str, Any]:\n    state: Dict[str, Any] = {"cls": type(opt).__name__, "lr": opt.lr, "t": opt.t}\n    for attr in ("m", "v", "buf", "sq", "slow"):\n        if hasattr(opt, attr):\n            state[attr] = [np.asarray(a).copy() for a in getattr(opt, attr)]\n    return state\n\n\ndef _load_optim_state(opt: Optimizer, state: Dict[str, Any]) -> None:\n    if state.get("cls") != type(opt).__name__:\n        raise ValueError(\n            f"оптимизатор не совпадает: в чекпоинте {state.get(\'cls\')}, передан {type(opt).__name__}"\n        )\n    opt.lr, opt.t = state["lr"], state["t"]\n    for attr in ("m", "v", "buf", "sq", "slow"):\n        if attr in state and hasattr(opt, attr):\n            setattr(opt, attr, [np.asarray(a) for a in state[attr]])\n\n\ndef save_checkpoint(path: str, model: Module, optimizer: Optional[Optimizer] = None,\n                    epoch: int = 0, step: int = 0, config: Any = None,\n                    history: Optional[Dict] = None, **extra) -> None:\n    """Сохранить полное состояние обучения."""\n    payload = {\n        "format": 1,\n        "model": model.state_dict(),\n        "optimizer": _optim_state(optimizer) if optimizer is not None else None,\n        "epoch": epoch,\n        "step": step,\n        "config": config.__dict__ if hasattr(config, "__dict__") else config,\n        "history": history,\n        "extra": extra,\n    }\n    with open(path, "wb") as f:\n        pickle.dump(payload, f, protocol=pickle.HIGHEST_PROTOCOL)\n\n\ndef load_checkpoint(path: str, model: Optional[Module] = None,\n                    optimizer: Optional[Optimizer] = None,\n                    strict: bool = True) -> Dict[str, Any]:\n    """Загрузить чекпоинт; при переданных model/optimizer — восстановить их состояние."""\n    with open(path, "rb") as f:\n        payload = pickle.load(f)\n\n    if model is not None:\n        sd = payload["model"]\n        if strict:\n            have = set(dict(model.named_parameters()))\n            want = set(sd)\n            if have != want:\n                missing, unexpected = want - have, have - want\n                raise ValueError(f"несовпадение параметров: нет {sorted(missing)[:3]}, "\n                                 f"лишние {sorted(unexpected)[:3]}")\n            for k, v in sd.items():\n                p = dict(model.named_parameters())[k]\n                if p.data.shape != np.asarray(v).shape:\n                    raise ValueError(f"форма {k}: ожидалась {p.data.shape}, в файле {np.asarray(v).shape}")\n        model.load_state_dict(sd)\n\n    if optimizer is not None and payload.get("optimizer"):\n        _load_optim_state(optimizer, payload["optimizer"])\n\n    return payload\n'

_SOURCES['ultranet.cli'] = '"""CLI: обучение и генерация из терминала.\n\n    python -m ultranet train-text --file corpus.txt --steps 500\n    python -m ultranet generate --checkpoint model.pkl --prompt "привет"\n    python -m ultranet demo\n    python -m ultranet bench\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport sys\nimport time\nfrom typing import Optional\n\nimport numpy as np\n\nimport ultranet as un\n\n\ndef _train_text(args: argparse.Namespace) -> None:\n    if args.file and os.path.exists(args.file):\n        text = open(args.file, encoding="utf-8").read()\n    else:\n        text = ("нейронная сеть учится на данных. градиент течёт назад через граф. "\n                "трансформер смотрит на контекст через внимание. ") * 60\n        print("файл не задан — использую встроенный корпус")\n\n    tok = un.CharTokenizer(text)\n    ids = tok.encode(text)\n    print(f"символов: {len(ids):,} | словарь: {tok.vocab_size}")\n\n    cfg = (un.GPTConfig.llama_style if args.llama else un.GPTConfig)(\n        vocab_size=tok.vocab_size, block_size=args.block, n_layer=args.layers,\n        n_head=args.heads, n_embd=args.embd, dropout=args.dropout,\n    )\n    model = un.GPT(cfg)\n    print(f"архитектура: {\'LLaMA-style (RoPE+RMSNorm+SwiGLU)\' if args.llama else \'GPT-2 style\'}")\n    print(f"параметров: {model.num_params():,}")\n\n    opt = un.AdamW(model.parameters(), lr=args.lr, weight_decay=0.01)\n    sched = un.CosineWarmup(opt, warmup=max(10, args.steps // 10), total=args.steps)\n    ema = un.EMA(model.parameters(), decay=0.995)  # с прогревом — безопасно и на коротких ранах\n\n    t0 = time.time()\n    for step in range(1, args.steps + 1):\n        xb, yb = un.make_lm_batches(ids, cfg.block_size, args.batch)\n        loss = un.cross_entropy(model(xb), yb)\n        opt.zero_grad()\n        loss.backward()\n        opt.clip_grad_norm(1.0)\n        opt.step()\n        lr = sched.step()\n        ema.update()\n        if step % max(1, args.steps // 20) == 0 or step == 1:\n            print(f"шаг {step:5d}/{args.steps} | loss {loss.item():.4f} "\n                  f"| ppl {un.perplexity(loss.item()):8.2f} | lr {lr:.5f} "\n                  f"| {time.time() - t0:.1f}s")\n\n    ema.apply()\n    if args.out:\n        model.save(args.out)\n        meta = {"vocab": tok.chars, "cfg": cfg.__dict__}\n        with open(args.out + ".json", "w", encoding="utf-8") as f:\n            json.dump(meta, f, ensure_ascii=False)\n        print(f"\\nсохранено: {args.out} (+ .json с конфигом)")\n\n    print("\\n--- сэмпл ---")\n    out = model.generate(tok.encode(args.prompt or text[:10]), args.tokens,\n                         temperature=args.temp, top_k=args.top_k, top_p=args.top_p, seed=0)\n    print(tok.decode(out))\n\n\ndef _generate(args: argparse.Namespace) -> None:\n    meta_path = args.checkpoint + ".json"\n    if not os.path.exists(meta_path):\n        sys.exit(f"не найден {meta_path} — он создаётся командой train-text")\n    meta = json.load(open(meta_path, encoding="utf-8"))\n    cfg = un.GPTConfig(**meta["cfg"])\n    model = un.GPT(cfg)\n    model.load(args.checkpoint)\n\n    class _Tok:\n        chars = meta["vocab"]\n        stoi = {c: i for i, c in enumerate(meta["vocab"])}\n        itos = {i: c for i, c in enumerate(meta["vocab"])}\n\n        def encode(self, s):\n            return [self.stoi[c] for c in s if c in self.stoi]\n\n        def decode(self, ids):\n            return "".join(self.itos[int(i)] for i in ids)\n\n    tok = _Tok()\n    prompt = tok.encode(args.prompt) or [0]\n    out = model.generate(prompt, args.tokens, temperature=args.temp,\n                         top_k=args.top_k, top_p=args.top_p,\n                         repetition_penalty=args.rep_penalty, seed=args.seed)\n    print(tok.decode(out))\n\n\ndef _demo(args: argparse.Namespace) -> None:\n    print("=" * 62)\n    print("UltraNet demo — классификация спиралей".center(62))\n    print("=" * 62)\n    x, y = un.make_spirals(300, 3, seed=0)\n    xtr, ytr, xte, yte = un.train_test_split(x, y, 0.2, seed=0)\n    model = un.MLP([2, 96, 96, 3], activation="gelu")\n    opt = un.AdamW(model.parameters(), lr=4e-3, weight_decay=1e-4)\n    tr = un.Trainer(model, opt, grad_clip=1.0, verbose=True)\n    tr.fit(un.DataLoader(xtr, ytr, 64), un.DataLoader(xte, yte, 128, shuffle=False),\n           epochs=25, patience=8)\n    loss, acc = tr.evaluate(un.DataLoader(xte, yte, 128, shuffle=False))\n    print(f"\\nтест: loss={loss:.4f} accuracy={acc * 100:.2f}%")\n    print("\\nкривые обучения:")\n    print(tr.plot_history())\n\n\ndef _bench(args: argparse.Namespace) -> None:\n    from .benchmark import run_all\n    run_all()\n\n\ndef main(argv: Optional[list] = None) -> None:\n    p = argparse.ArgumentParser("ultranet", description="UltraNet — нейросети на чистом NumPy")\n    sub = p.add_subparsers(dest="cmd", required=True)\n\n    t = sub.add_parser("train-text", help="обучить символьную языковую модель")\n    t.add_argument("--file", type=str, default=None, help="текстовый корпус utf-8")\n    t.add_argument("--steps", type=int, default=300)\n    t.add_argument("--batch", type=int, default=16)\n    t.add_argument("--block", type=int, default=48)\n    t.add_argument("--layers", type=int, default=3)\n    t.add_argument("--heads", type=int, default=4)\n    t.add_argument("--embd", type=int, default=96)\n    t.add_argument("--dropout", type=float, default=0.05)\n    t.add_argument("--lr", type=float, default=3e-3)\n    t.add_argument("--llama", action="store_true", help="RoPE + RMSNorm + SwiGLU")\n    t.add_argument("--out", type=str, default=None, help="куда сохранить веса")\n    t.add_argument("--prompt", type=str, default=None)\n    t.add_argument("--tokens", type=int, default=160)\n    t.add_argument("--temp", type=float, default=0.8)\n    t.add_argument("--top-k", dest="top_k", type=int, default=8)\n    t.add_argument("--top-p", dest="top_p", type=float, default=None)\n    t.set_defaults(func=_train_text)\n\n    g = sub.add_parser("generate", help="сгенерировать текст из чекпоинта")\n    g.add_argument("--checkpoint", required=True)\n    g.add_argument("--prompt", type=str, default="")\n    g.add_argument("--tokens", type=int, default=200)\n    g.add_argument("--temp", type=float, default=0.8)\n    g.add_argument("--top-k", dest="top_k", type=int, default=None)\n    g.add_argument("--top-p", dest="top_p", type=float, default=0.9)\n    g.add_argument("--rep-penalty", dest="rep_penalty", type=float, default=1.1)\n    g.add_argument("--seed", type=int, default=None)\n    g.set_defaults(func=_generate)\n\n    d = sub.add_parser("demo", help="быстрая демонстрация обучения")\n    d.set_defaults(func=_demo)\n\n    b = sub.add_parser("bench", help="бенчмарк скорости операций")\n    b.set_defaults(func=_bench)\n\n    args = p.parse_args(argv)\n    args.func(args)\n\n\nif __name__ == "__main__":\n    main()\n'

_SOURCES['ultranet.data'] = '"""Данные: загрузчик батчей, синтетические датасеты, символьный токенизатор."""\nfrom __future__ import annotations\n\nfrom typing import Iterator, List, Optional, Tuple\n\nimport numpy as np\n\n\nclass DataLoader:\n    """Итератор по мини-батчам с опциональным перемешиванием."""\n\n    def __init__(self, x: np.ndarray, y: np.ndarray, batch_size: int = 32, shuffle: bool = True,\n                 drop_last: bool = False) -> None:\n        self.x, self.y = np.asarray(x), np.asarray(y)\n        self.bs, self.shuffle, self.drop_last = batch_size, shuffle, drop_last\n\n    def __len__(self) -> int:\n        n = len(self.x)\n        return n // self.bs if self.drop_last else (n + self.bs - 1) // self.bs\n\n    def __iter__(self) -> Iterator[Tuple[np.ndarray, np.ndarray]]:\n        idx = np.random.permutation(len(self.x)) if self.shuffle else np.arange(len(self.x))\n        for i in range(len(self)):\n            b = idx[i * self.bs:(i + 1) * self.bs]\n            yield self.x[b], self.y[b]\n\n\ndef train_test_split(x: np.ndarray, y: np.ndarray, test_size: float = 0.2, seed: int = 0):\n    rng = np.random.default_rng(seed)\n    idx = rng.permutation(len(x))\n    cut = int(len(x) * (1 - test_size))\n    tr, te = idx[:cut], idx[cut:]\n    return x[tr], y[tr], x[te], y[te]\n\n\ndef make_spirals(n_per_class: int = 300, n_classes: int = 3, noise: float = 0.2, seed: int = 0):\n    """Классическая нелинейная задача «спирали» — проверка мощности модели."""\n    rng = np.random.default_rng(seed)\n    xs, ys = [], []\n    for c in range(n_classes):\n        r = np.linspace(0.05, 1.0, n_per_class)\n        t = np.linspace(c * 4, (c + 1) * 4, n_per_class) + rng.normal(0, noise, n_per_class)\n        xs.append(np.c_[r * np.sin(t), r * np.cos(t)])\n        ys.append(np.full(n_per_class, c))\n    return np.vstack(xs).astype(np.float32), np.concatenate(ys).astype(int)\n\n\ndef make_moons(n: int = 600, noise: float = 0.15, seed: int = 0):\n    rng = np.random.default_rng(seed)\n    n1 = n // 2\n    t = np.linspace(0, np.pi, n1)\n    a = np.c_[np.cos(t), np.sin(t)]\n    b = np.c_[1 - np.cos(t), 0.5 - np.sin(t)]\n    x = np.vstack([a, b]) + rng.normal(0, noise, (2 * n1, 2))\n    y = np.r_[np.zeros(n1), np.ones(n1)]\n    return x.astype(np.float32), y.astype(int)\n\n\ndef make_digits_like(n: int = 400, size: int = 8, n_classes: int = 4, seed: int = 0):\n    """Синтетические «картинки»: полоса, крест, рамка, диагональ + шум."""\n    rng = np.random.default_rng(seed)\n    x = np.zeros((n, 1, size, size), dtype=np.float32)\n    y = rng.integers(0, n_classes, n)\n    for i, c in enumerate(y):\n        img = np.zeros((size, size), dtype=np.float32)\n        if c == 0:\n            img[size // 2, :] = 1.0\n        elif c == 1:\n            img[size // 2, :] = img[:, size // 2] = 1.0\n        elif c == 2:\n            img[0, :] = img[-1, :] = img[:, 0] = img[:, -1] = 1.0\n        else:\n            np.fill_diagonal(img, 1.0)\n        x[i, 0] = img + rng.normal(0, 0.1, (size, size))\n    return x, y.astype(int)\n\n\nclass Dataset:\n    """Простейшая обёртка над массивами (x, y) с поддержкой len/индексации."""\n\n    def __init__(self, x: np.ndarray, y: np.ndarray) -> None:\n        assert len(x) == len(y), "x и y должны быть одной длины"\n        self.x, self.y = np.asarray(x), np.asarray(y)\n\n    def __len__(self) -> int:\n        return len(self.x)\n\n    def __getitem__(self, i):\n        return self.x[i], self.y[i]\n\n    def loader(self, batch_size: int = 32, shuffle: bool = True) -> "DataLoader":\n        return DataLoader(self.x, self.y, batch_size, shuffle)\n\n\ndef normalize(x: np.ndarray, mean=None, std=None):\n    """Стандартизация признаков; возвращает (x_norm, mean, std) для переиспользования."""\n    mean = x.mean(0, keepdims=True) if mean is None else mean\n    std = x.std(0, keepdims=True) + 1e-8 if std is None else std\n    return ((x - mean) / std).astype(np.float32), mean, std\n\n\ndef make_regression(n: int = 500, n_features: int = 1, noise: float = 0.1, seed: int = 0):\n    """Нелинейная регрессия y = sin(3x) + шум."""\n    rng = np.random.default_rng(seed)\n    x = rng.uniform(-2, 2, (n, n_features)).astype(np.float32)\n    y = (np.sin(3 * x).sum(1) + rng.normal(0, noise, n)).astype(np.float32)\n    return x, y[:, None]\n\n\nclass WordTokenizer:\n    """Пословный токенизатор со словарём частотных слов и <unk>."""\n\n    def __init__(self, text: str, max_vocab: int = 5000) -> None:\n        from collections import Counter\n\n        words = text.split()\n        freq = Counter(words).most_common(max_vocab - 2)\n        self.itos = {0: "<pad>", 1: "<unk>"}\n        for i, (w, _) in enumerate(freq):\n            self.itos[i + 2] = w\n        self.stoi = {w: i for i, w in self.itos.items()}\n\n    @property\n    def vocab_size(self) -> int:\n        return len(self.itos)\n\n    def encode(self, s: str) -> List[int]:\n        return [self.stoi.get(w, 1) for w in s.split()]\n\n    def decode(self, ids) -> str:\n        return " ".join(self.itos[int(i)] for i in ids)\n\n\nclass CharTokenizer:\n    """Простейший символьный токенизатор для языковой модели."""\n\n    def __init__(self, text: str) -> None:\n        self.chars = sorted(set(text))\n        self.stoi = {c: i for i, c in enumerate(self.chars)}\n        self.itos = {i: c for c, i in self.stoi.items()}\n\n    @property\n    def vocab_size(self) -> int:\n        return len(self.chars)\n\n    def encode(self, s: str) -> List[int]:\n        return [self.stoi[c] for c in s if c in self.stoi]\n\n    def decode(self, ids) -> str:\n        return "".join(self.itos[int(i)] for i in ids)\n\n\ndef make_lm_batches(ids: List[int], block_size: int, batch_size: int, seed: Optional[int] = None):\n    """Случайные окна (x, y) со сдвигом на один токен."""\n    rng = np.random.default_rng(seed)\n    arr = np.asarray(ids, dtype=int)\n    if len(arr) < block_size + 2:\n        raise ValueError(\n            f"данных слишком мало: {len(arr)} токенов при block_size={block_size}. "\n            f"Нужно минимум {block_size + 2} — уменьшите block_size или возьмите больше текста."\n        )\n    ix = rng.integers(0, len(arr) - block_size - 1, batch_size)\n    x = np.stack([arr[i:i + block_size] for i in ix])\n    y = np.stack([arr[i + 1:i + 1 + block_size] for i in ix])\n    return x, y\n'

_SOURCES['ultranet.functional'] = '"""Функции потерь и метрики."""\nfrom __future__ import annotations\n\nfrom typing import Optional\n\nimport numpy as np\n\nfrom .tensor import Tensor\n\n\ndef one_hot(idx: np.ndarray, n_classes: int) -> np.ndarray:\n    out = np.zeros((idx.shape[0], n_classes), dtype=np.float32)\n    out[np.arange(idx.shape[0]), idx.astype(int)] = 1.0\n    return out\n\n\ndef cross_entropy(logits: Tensor, targets, label_smoothing: float = 0.0,\n                  ignore_index: Optional[int] = None) -> Tensor:\n    """Fused softmax + NLL одним узлом графа.\n\n    Градиент считается аналитически как (softmax(x) - y) / N, поэтому\n    проход дешевле и численно устойчивее цепочки log_softmax -> gather.\n\n    targets: индексы классов (любой формы) или one-hot той же формы, что logits.\n    ignore_index: позиции с этой меткой исключаются из loss (паддинг).\n    """\n    if logits.ndim > 2:\n        logits = logits.reshape(-1, logits.shape[-1])\n    t = targets.data if isinstance(targets, Tensor) else np.asarray(targets)\n    n_classes = logits.shape[-1]\n\n    if t.ndim == 2 and t.shape == logits.shape:\n        y = t.astype(np.float32)\n        mask = np.ones((logits.shape[0], 1), dtype=np.float32)\n    else:\n        flat = t.reshape(-1).astype(int)\n        valid = flat != ignore_index if ignore_index is not None else np.ones_like(flat, dtype=bool)\n        y = one_hot(np.where(valid, flat, 0), n_classes)\n        mask = valid.astype(np.float32)[:, None]\n\n    if label_smoothing > 0:\n        y = y * (1 - label_smoothing) + label_smoothing / n_classes\n\n    x = logits.data\n    z = x - x.max(axis=-1, keepdims=True)\n    lse = np.log(np.exp(z).sum(axis=-1, keepdims=True))\n    logp = z - lse\n    n = max(float(mask.sum()), 1.0)\n    loss_val = -(logp * y * mask).sum() / n\n\n    out = logits._make(np.array(loss_val, dtype=np.float32), (logits,), "cross_entropy")\n    probs = np.exp(logp)\n\n    def _backward() -> None:\n        logits._accum(out.grad * (probs - y) * mask / n)\n\n    out._backward = _backward\n    return out\n\n\ndef nll_loss(log_probs: Tensor, targets) -> Tensor:\n    """Negative log-likelihood поверх уже посчитанных log-вероятностей."""\n    if log_probs.ndim > 2:\n        log_probs = log_probs.reshape(-1, log_probs.shape[-1])\n    t = np.asarray(targets.data if isinstance(targets, Tensor) else targets).reshape(-1).astype(int)\n    y = one_hot(t, log_probs.shape[-1])\n    return -(log_probs * Tensor(y)).sum(axis=-1).mean()\n\n\ndef binary_cross_entropy(probs: Tensor, targets) -> Tensor:\n    y = Tensor(targets.data if isinstance(targets, Tensor) else np.asarray(targets, dtype=np.float32))\n    p = probs.clip(1e-7, 1 - 1e-7)\n    return -(y * p.log() + (1 - y) * (1 - p).log()).mean()\n\n\ndef bce_with_logits(logits: Tensor, targets) -> Tensor:\n    """Численно устойчивая BCE прямо по логитам (log-sum-exp трюк)."""\n    y = np.asarray(targets.data if isinstance(targets, Tensor) else targets, dtype=np.float32)\n    x = logits.data\n    loss_val = float(np.mean(np.maximum(x, 0) - x * y + np.log1p(np.exp(-np.abs(x)))))\n    out = logits._make(np.array(loss_val, dtype=np.float32), (logits,), "bce_logits")\n    sig = 1.0 / (1.0 + np.exp(-x))\n\n    def _backward() -> None:\n        logits._accum(out.grad * (sig - y) / x.size)\n\n    out._backward = _backward\n    return out\n\n\ndef focal_loss(logits: Tensor, targets, gamma: float = 2.0, alpha: float = 1.0) -> Tensor:\n    """Focal loss — приглушает вклад лёгких примеров при дисбалансе классов."""\n    if logits.ndim > 2:\n        logits = logits.reshape(-1, logits.shape[-1])\n    t = np.asarray(targets.data if isinstance(targets, Tensor) else targets).reshape(-1).astype(int)\n    logp = logits.log_softmax(axis=-1)\n    y = Tensor(one_hot(t, logits.shape[-1]))\n    pt = (logp * y).sum(axis=-1)\n    focal = (1 - pt.exp()) ** gamma\n    return -(focal.detach() * pt).mean() * alpha\n\n\ndef mse_loss(pred: Tensor, target) -> Tensor:\n    y = Tensor(target.data if isinstance(target, Tensor) else np.asarray(target, dtype=np.float32))\n    return ((pred - y) ** 2).mean()\n\n\ndef mae_loss(pred: Tensor, target) -> Tensor:\n    y = Tensor(target.data if isinstance(target, Tensor) else np.asarray(target, dtype=np.float32))\n    return (pred - y).abs().mean()\n\n\ndef huber_loss(pred: Tensor, target, delta: float = 1.0) -> Tensor:\n    """Робастная к выбросам смесь MSE (внутри delta) и MAE (снаружи)."""\n    y = Tensor(target.data if isinstance(target, Tensor) else np.asarray(target, dtype=np.float32))\n    diff = pred - y\n    a = diff.abs()\n    small = (np.abs(diff.data) <= delta).astype(np.float32)\n    quad = (diff ** 2) * 0.5\n    lin = (a - 0.5 * delta) * delta\n    return (quad * Tensor(small) + lin * Tensor(1 - small)).mean()\n\n\n# ------------------------------------------------------------------------ метрики\ndef accuracy(logits: Tensor, targets) -> float:\n    t = targets.data if isinstance(targets, Tensor) else np.asarray(targets)\n    pred = logits.data.reshape(-1, logits.shape[-1]).argmax(-1)\n    return float((pred == t.reshape(-1).astype(int)).mean())\n\n\ndef top_k_accuracy(logits: Tensor, targets, k: int = 5) -> float:\n    t = np.asarray(targets.data if isinstance(targets, Tensor) else targets).reshape(-1).astype(int)\n    x = logits.data.reshape(-1, logits.shape[-1])\n    topk = np.argpartition(-x, min(k, x.shape[-1]) - 1, axis=-1)[:, :k]\n    return float(np.mean([t[i] in topk[i] for i in range(len(t))]))\n\n\ndef perplexity(loss_value: float) -> float:\n    """Перплексия языковой модели из значения кросс-энтропии."""\n    return float(np.exp(min(loss_value, 20.0)))\n\n\ndef confusion_matrix(logits: Tensor, targets, n_classes: Optional[int] = None) -> np.ndarray:\n    t = np.asarray(targets.data if isinstance(targets, Tensor) else targets).reshape(-1).astype(int)\n    pred = logits.data.reshape(-1, logits.shape[-1]).argmax(-1)\n    n = n_classes or int(max(t.max(), pred.max()) + 1)\n    cm = np.zeros((n, n), dtype=int)\n    np.add.at(cm, (t, pred), 1)\n    return cm\n\n\ndef f1_score(logits: Tensor, targets, average: str = "macro") -> float:\n    cm = confusion_matrix(logits, targets)\n    tp = np.diag(cm).astype(float)\n    prec = np.divide(tp, cm.sum(0), out=np.zeros_like(tp), where=cm.sum(0) > 0)\n    rec = np.divide(tp, cm.sum(1), out=np.zeros_like(tp), where=cm.sum(1) > 0)\n    f1 = np.divide(2 * prec * rec, prec + rec, out=np.zeros_like(tp), where=(prec + rec) > 0)\n    if average == "macro":\n        return float(f1.mean())\n    weights = cm.sum(1) / max(cm.sum(), 1)\n    return float((f1 * weights).sum())\n'

_SOURCES['ultranet.gradcheck'] = '"""Численная проверка градиентов — публичный инструмент отладки своих слоёв.\n\n    >>> import ultranet as un\n    >>> layer = un.nn.Linear(4, 3)\n    >>> x = un.Tensor(np.random.randn(2, 4), requires_grad=True)\n    >>> un.gradcheck(lambda: layer(x).sum(), [x, layer.weight])\n    True\n"""\nfrom __future__ import annotations\n\nfrom typing import Callable, List, Sequence\n\nimport numpy as np\n\nfrom .tensor import Tensor\n\n\ndef numeric_grad(fn: Callable[[], Tensor], param: Tensor, eps: float = 1e-3) -> np.ndarray:\n    """Градиент центральной разностью: (f(x+e) - f(x-e)) / 2e."""\n    grad = np.zeros_like(param.data)\n    flat = param.data.reshape(-1)\n    gflat = grad.reshape(-1)\n    for i in range(flat.size):\n        orig = flat[i]\n        flat[i] = orig + eps\n        plus = float(fn().item())\n        flat[i] = orig - eps\n        minus = float(fn().item())\n        flat[i] = orig\n        gflat[i] = (plus - minus) / (2 * eps)\n    return grad\n\n\ndef gradcheck(fn: Callable[[], Tensor], params: Sequence[Tensor], eps: float = 1e-3,\n              atol: float = 2e-2, rtol: float = 2e-2, verbose: bool = False,\n              raise_exception: bool = True) -> bool:\n    """Сравнить аналитический градиент с численным.\n\n    fn должна возвращать скалярный Tensor и быть чистой функцией от params.\n    """\n    loss = fn()\n    if loss.size != 1:\n        raise ValueError("fn должна возвращать скаляр")\n    for p in params:\n        p.grad = None\n    loss.backward()\n\n    ok = True\n    report: List[str] = []\n    for i, p in enumerate(params):\n        analytic = np.zeros_like(p.data) if p.grad is None else p.grad\n        numeric = numeric_grad(fn, p, eps)\n        denom = np.maximum(np.abs(analytic) + np.abs(numeric), 1e-8)\n        rel = np.abs(analytic - numeric) / denom\n        close = np.allclose(analytic, numeric, atol=atol, rtol=rtol)\n        ok &= bool(close)\n        report.append(\n            f"  param[{i}] shape={p.shape} max|Δ|={np.abs(analytic - numeric).max():.2e} "\n            f"max_rel={rel.max():.2e} {\'OK\' if close else \'FAIL\'}"\n        )\n\n    if verbose or (not ok):\n        text = "gradcheck:\\n" + "\\n".join(report)\n        if not ok and raise_exception:\n            raise AssertionError(text)\n        print(text)\n    return ok\n'

_SOURCES['ultranet.models'] = '"""Готовые архитектуры: MLP, CNN и GPT-подобный трансформер."""\nfrom __future__ import annotations\n\nimport math\nfrom dataclasses import dataclass\nfrom typing import List, Optional, Sequence\n\nimport numpy as np\n\nfrom . import nn\nfrom .tensor import Tensor, no_grad\n\n\nclass MLP(nn.Module):\n    """Полносвязная сеть произвольной глубины."""\n\n    def __init__(self, sizes: Sequence[int], activation: str = "relu", dropout: float = 0.0,\n                 batchnorm: bool = False) -> None:\n        super().__init__()\n        act = {"relu": nn.ReLU, "gelu": nn.GELU, "tanh": nn.Tanh, "sigmoid": nn.Sigmoid}[activation]\n        layers: List[nn.Module] = []\n        for i in range(len(sizes) - 1):\n            layers.append(nn.Linear(sizes[i], sizes[i + 1]))\n            if i < len(sizes) - 2:\n                if batchnorm:\n                    layers.append(nn.BatchNorm1d(sizes[i + 1]))\n                layers.append(act())\n                if dropout:\n                    layers.append(nn.Dropout(dropout))\n        self.net = nn.Sequential(*layers)\n\n    def forward(self, x: Tensor) -> Tensor:\n        return self.net(x)\n\n\nclass ConvNet(nn.Module):\n    """Небольшая CNN для изображений (N, C, H, W)."""\n\n    def __init__(self, in_ch: int = 1, n_classes: int = 10, width: int = 16, img_size: int = 28) -> None:\n        super().__init__()\n        self.features = nn.Sequential(\n            nn.Conv2d(in_ch, width, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),\n            nn.Conv2d(width, width * 2, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2),\n        )\n        s = img_size // 4\n        self.head = nn.Sequential(nn.Flatten(), nn.Linear(width * 2 * s * s, 128), nn.ReLU(),\n                                  nn.Linear(128, n_classes))\n\n    def forward(self, x: Tensor) -> Tensor:\n        return self.head(self.features(x))\n\n\nclass ResBlock(nn.Module):\n    """Остаточный блок: Conv-BN-ReLU x2 + skip (упрощённый ResNet-v1)."""\n\n    def __init__(self, ch: int) -> None:\n        super().__init__()\n        self.c1 = nn.Conv2d(ch, ch, 3, padding=1, bias=False)\n        self.c2 = nn.Conv2d(ch, ch, 3, padding=1, bias=False)\n\n    def forward(self, x: Tensor) -> Tensor:\n        h = self.c1(x).relu()\n        return (x + self.c2(h)).relu()\n\n\nclass ResNet(nn.Module):\n    """Небольшая ResNet для изображений (N, C, H, W)."""\n\n    def __init__(self, in_ch: int = 1, n_classes: int = 10, width: int = 16,\n                 n_blocks: int = 2, img_size: int = 8) -> None:\n        super().__init__()\n        self.stem = nn.Conv2d(in_ch, width, 3, padding=1)\n        self.blocks = [ResBlock(width) for _ in range(n_blocks)]\n        for i, b in enumerate(self.blocks):\n            self._modules[f"res{i}"] = b\n        self.pool = nn.AvgPool2d(2)\n        s = img_size // 2\n        self.head = nn.Sequential(nn.Flatten(), nn.Linear(width * s * s, n_classes))\n\n    def forward(self, x: Tensor) -> Tensor:\n        x = self.stem(x).relu()\n        for b in self.blocks:\n            x = b(x)\n        return self.head(self.pool(x))\n\n\nclass TextClassifier(nn.Module):\n    """Трансформер-энкодер (без causal-маски) + среднее по токенам -> классы."""\n\n    def __init__(self, vocab_size: int, n_classes: int, n_embd: int = 64, n_layer: int = 2,\n                 n_head: int = 4, max_len: int = 64, dropout: float = 0.1) -> None:\n        super().__init__()\n        self.tok = nn.Embedding(vocab_size, n_embd)\n        self.pos = nn.Embedding(max_len, n_embd)\n        self.blocks = [nn.TransformerBlock(n_embd, n_head, dropout=dropout, causal=False)\n                       for _ in range(n_layer)]\n        for i, b in enumerate(self.blocks):\n            self._modules[f"block{i}"] = b\n        self.norm = nn.LayerNorm(n_embd)\n        self.head = nn.Linear(n_embd, n_classes)\n\n    def forward(self, idx) -> Tensor:\n        idx = np.asarray(idx.data if isinstance(idx, Tensor) else idx).astype(int)\n        t = idx.shape[1]\n        x = self.tok(idx) + self.pos(np.arange(t))[None]\n        for b in self.blocks:\n            x = b(x)\n        return self.head(self.norm(x).mean(axis=1))\n\n\n@dataclass\nclass GPTConfig:\n    """Конфигурация GPT. По умолчанию — классический GPT-2 style.\n\n    Для современного LLaMA-style укажите rope=True, norm="rms", swiglu=True.\n    """\n\n    vocab_size: int = 128\n    block_size: int = 64\n    n_layer: int = 4\n    n_head: int = 4\n    n_embd: int = 128\n    dropout: float = 0.0\n    rope: bool = False           # вращательные позиционные эмбеддинги\n    norm: str = "layer"          # "layer" | "rms"\n    swiglu: bool = False         # SwiGLU-MLP вместо GELU-MLP\n    tie_weights: bool = True     # общая матрица эмбеддингов и выходной головы\n\n    @classmethod\n    def llama_style(cls, vocab_size: int, **kw) -> "GPTConfig":\n        base = dict(vocab_size=vocab_size, rope=True, norm="rms", swiglu=True)\n        base.update(kw)\n        return cls(**base)\n\n\nclass GPT(nn.Module):\n    """Декодер-трансформер: causal-attention, RoPE/RMSNorm/SwiGLU, KV-кэш."""\n\n    def __init__(self, cfg: GPTConfig) -> None:\n        super().__init__()\n        self.cfg = cfg\n        self.tok_emb = nn.Embedding(cfg.vocab_size, cfg.n_embd)\n        self.pos_emb = None if cfg.rope else nn.Embedding(cfg.block_size, cfg.n_embd)\n        self.drop = nn.Dropout(cfg.dropout)\n        self.blocks = [\n            nn.TransformerBlock(cfg.n_embd, cfg.n_head, dropout=cfg.dropout, causal=True,\n                                rope=cfg.rope, norm=cfg.norm, swiglu=cfg.swiglu,\n                                max_seq=cfg.block_size * 4)\n            for _ in range(cfg.n_layer)\n        ]\n        for i, b in enumerate(self.blocks):\n            self._modules[f"block{i}"] = b\n        self.ln_f = nn.RMSNorm(cfg.n_embd) if cfg.norm == "rms" else nn.LayerNorm(cfg.n_embd)\n        if cfg.tie_weights:\n            # weight tying: голова переиспользует матрицу эмбеддингов (экономит vocab*n_embd)\n            self.head = None\n        else:\n            self.head = nn.Linear(cfg.n_embd, cfg.vocab_size, bias=False)\n        # масштабированная инициализация остаточных проекций (GPT-2 § 2.3)\n        scale = 1.0 / math.sqrt(2 * cfg.n_layer)\n        for blk in self.blocks:\n            blk.attn.proj.weight.data *= scale\n\n    def _logits(self, x: Tensor) -> Tensor:\n        if self.head is not None:\n            return self.head(x)\n        return x @ self.tok_emb.weight.transpose()\n\n    def forward(self, idx, use_cache: bool = False, pos_offset: int = 0) -> Tensor:\n        idx = np.asarray(idx.data if isinstance(idx, Tensor) else idx).astype(int)\n        if idx.ndim == 1:\n            idx = idx[None]          # удобство: принимаем одиночную последовательность\n        if idx.ndim != 2:\n            raise ValueError(\n                f"GPT ожидает индексы формы (batch, seq) или (seq,), получено {idx.shape}"\n            )\n        b, t = idx.shape\n        x = self.tok_emb(idx)\n        if self.pos_emb is not None:\n            assert pos_offset + t <= self.cfg.block_size, "последовательность длиннее block_size"\n            x = x + self.pos_emb(np.arange(pos_offset, pos_offset + t))[None]\n        x = self.drop(x)\n        for block in self.blocks:\n            x = block(x, use_cache=use_cache)\n        return self._logits(self.ln_f(x))\n\n    def reset_cache(self) -> None:\n        for block in self.blocks:\n            block.attn.reset_cache()\n\n    @staticmethod\n    def _sample(logits: np.ndarray, temperature: float, top_k: Optional[int],\n                top_p: Optional[float], repetition_penalty: float,\n                seen: Sequence[int], rng) -> int:\n        logits = logits.astype(np.float64)\n        if repetition_penalty != 1.0 and seen:\n            uniq = np.unique(np.asarray(seen, dtype=int))\n            pos = logits[uniq] > 0\n            logits[uniq] = np.where(pos, logits[uniq] / repetition_penalty,\n                                    logits[uniq] * repetition_penalty)\n        if temperature <= 1e-6:\n            return int(logits.argmax())\n        logits = logits / temperature\n        if top_k is not None and top_k < len(logits):\n            thresh = np.partition(logits, -top_k)[-top_k]\n            logits = np.where(logits < thresh, -np.inf, logits)\n        if top_p is not None and 0 < top_p < 1.0:\n            order = np.argsort(-logits)\n            probs = np.exp(logits[order] - logits[order].max())\n            probs /= probs.sum()\n            cum = np.cumsum(probs)\n            cutoff = int(np.searchsorted(cum, top_p) + 1)\n            keep = order[:cutoff]\n            masked = np.full_like(logits, -np.inf)\n            masked[keep] = logits[keep]\n            logits = masked\n        p = np.exp(logits - logits.max())\n        p /= p.sum()\n        return int(rng.choice(len(p), p=p))\n\n    def generate(self, prompt: Sequence[int], max_new_tokens: int = 100, temperature: float = 1.0,\n                 top_k: Optional[int] = None, top_p: Optional[float] = None,\n                 repetition_penalty: float = 1.0, use_cache: bool = True,\n                 stop_tokens: Optional[Sequence[int]] = None,\n                 seed: Optional[int] = None) -> List[int]:\n        """Авторегрессионная генерация: temperature, top-k, nucleus (top-p), KV-кэш.\n\n        temperature=0 даёт жадный детерминированный декодинг.\n        """\n        rng = np.random.default_rng(seed)\n        was_training = self.training\n        self.eval()\n        self.reset_cache()\n        seq = list(prompt)\n        stop = set(stop_tokens or ())\n\n        with no_grad():\n            if use_cache:\n                ctx = np.array([seq[-self.cfg.block_size:]], dtype=int)\n                logits = self(ctx, use_cache=True).data[0, -1]\n                pos = len(seq)\n                for _ in range(max_new_tokens):\n                    nxt = self._sample(logits, temperature, top_k, top_p,\n                                       repetition_penalty, seq, rng)\n                    seq.append(nxt)\n                    if nxt in stop:\n                        break\n                    if pos >= self.cfg.block_size:  # кэш переполнен — пересобираем\n                        self.reset_cache()\n                        ctx = np.array([seq[-self.cfg.block_size:]], dtype=int)\n                        logits = self(ctx, use_cache=True).data[0, -1]\n                        pos = len(seq[-self.cfg.block_size:])\n                    else:\n                        logits = self(np.array([[nxt]], dtype=int), use_cache=True,\n                                      pos_offset=pos).data[0, -1]\n                        pos += 1\n            else:\n                for _ in range(max_new_tokens):\n                    ctx = np.array([seq[-self.cfg.block_size:]], dtype=int)\n                    logits = self(ctx).data[0, -1]\n                    nxt = self._sample(logits, temperature, top_k, top_p,\n                                       repetition_penalty, seq, rng)\n                    seq.append(nxt)\n                    if nxt in stop:\n                        break\n\n        self.reset_cache()\n        self.train(was_training)\n        return seq\n\n    @no_grad()\n    def loss_on(self, x: np.ndarray, y: np.ndarray) -> float:\n        """Кросс-энтропия на батче без построения графа."""\n        from .functional import cross_entropy\n        return cross_entropy(self(x), y).item()\n'

_SOURCES['ultranet.nn'] = '"""Слои и модули (аналог torch.nn), построенные поверх автограда Tensor."""\nfrom __future__ import annotations\n\nimport math\nimport pickle\nfrom typing import Any, Dict, Iterator, List, Optional, Sequence\n\nimport numpy as np\n\nfrom .tensor import Tensor, cat, get_rng\n\n\nclass Parameter(Tensor):\n    """Тензор-параметр: всегда requires_grad=True."""\n\n    def __init__(self, data) -> None:\n        super().__init__(data, requires_grad=True)\n\n\n# ------------------------------------------------------------------ инициализация\ndef kaiming(fan_in: int, fan_out: int, gain: float = 2.0) -> np.ndarray:\n    return (get_rng().standard_normal((fan_in, fan_out)) * math.sqrt(gain / fan_in)).astype(np.float32)\n\n\ndef xavier(fan_in: int, fan_out: int) -> np.ndarray:\n    limit = math.sqrt(6.0 / (fan_in + fan_out))\n    return get_rng().uniform(-limit, limit, (fan_in, fan_out)).astype(np.float32)\n\n\nclass Module:\n    """Базовый модуль: рекурсивный обход параметров, режимы train/eval, сохранение."""\n\n    def __init__(self) -> None:\n        self._modules: Dict[str, "Module"] = {}\n        self._params: Dict[str, Parameter] = {}\n        self.training = True\n\n    def __setattr__(self, name: str, value: Any) -> None:\n        if isinstance(value, Parameter):\n            self.__dict__.setdefault("_params", {})[name] = value\n        elif isinstance(value, Module):\n            self.__dict__.setdefault("_modules", {})[name] = value\n        elif isinstance(value, (list, tuple)) and value and all(isinstance(v, Module) for v in value):\n            for i, v in enumerate(value):\n                self.__dict__.setdefault("_modules", {})[f"{name}.{i}"] = v\n        object.__setattr__(self, name, value)\n\n    def parameters(self) -> List[Parameter]:\n        """Уникальные параметры módulo повторной регистрации.\n\n        Один и тот же Parameter может быть достижим несколькими путями:\n        список модулей регистрируется как "blocks.i", а ручная запись в\n        _modules добавляет те же блоки под другим именем; при weight tying\n        одна матрица делится головой и эмбеддингом. Без дедупликации\n        оптимизатор применял бы шаг к такому весу дважды за итерацию —\n        фактически удвоенный learning rate именно для общих весов.\n        """\n        out: List[Parameter] = []\n        seen = set()\n        for p in self._params.values():\n            if id(p) not in seen:\n                seen.add(id(p))\n                out.append(p)\n        for m in self._modules.values():\n            for p in m.parameters():\n                if id(p) not in seen:\n                    seen.add(id(p))\n                    out.append(p)\n        return out\n\n    def named_parameters(self, prefix: str = "", _seen: Optional[set] = None) -> Iterator[tuple]:\n        """Как parameters(), но с именами и тоже без повторов.\n\n        Общий вес выдаётся один раз — под первым встреченным именем.\n        Иначе summary() и подсчёт памяти удваивали бы связанные матрицы.\n        """\n        if _seen is None:\n            _seen = set()\n        for k, v in self._params.items():\n            if id(v) not in _seen:\n                _seen.add(id(v))\n                yield f"{prefix}{k}", v\n        for name, m in self._modules.items():\n            yield from m.named_parameters(f"{prefix}{name}.", _seen)\n\n    def num_params(self) -> int:\n        return sum(p.size for p in self.parameters())\n\n    def zero_grad(self) -> None:\n        for p in self.parameters():\n            p.grad = None\n\n    def train(self, mode: bool = True) -> "Module":\n        self.training = mode\n        for m in self._modules.values():\n            m.train(mode)\n        return self\n\n    def eval(self) -> "Module":\n        return self.train(False)\n\n    def state_dict(self) -> Dict[str, np.ndarray]:\n        return {k: v.data.copy() for k, v in self.named_parameters()}\n\n    def load_state_dict(self, sd: Dict[str, np.ndarray]) -> None:\n        params = dict(self.named_parameters())\n        for k, v in sd.items():\n            if k in params:\n                params[k].data = np.asarray(v, dtype=np.float32)\n\n    def save(self, path: str) -> None:\n        with open(path, "wb") as f:\n            pickle.dump(self.state_dict(), f)\n\n    def load(self, path: str) -> None:\n        with open(path, "rb") as f:\n            self.load_state_dict(pickle.load(f))\n\n    def summary(self, max_rows: int = 40) -> str:\n        """Таблица параметров модели — быстрый аудит архитектуры."""\n        rows = [(name, tuple(p.shape), p.size) for name, p in self.named_parameters()]\n        total = sum(r[2] for r in rows)\n        w = max([len(r[0]) for r in rows] + [9])\n        head = f"{\'параметр\'.ljust(w)}  {\'форма\':<18} {\'кол-во\':>12}"\n        lines = [head, "-" * len(head)]\n        for name, shape, size in rows[:max_rows]:\n            lines.append(f"{name.ljust(w)}  {str(shape):<18} {size:>12,}")\n        if len(rows) > max_rows:\n            lines.append(f"... ещё {len(rows) - max_rows} параметров")\n        lines.append("-" * len(head))\n        lines.append(f"{\'ИТОГО\'.ljust(w)}  {\'\':<18} {total:>12,}")\n        mb = total * 4 / 1024 ** 2\n        lines.append(f"{\'память (float32)\'.ljust(w)}  {\'\':<18} {mb:>11.2f}M")\n        return "\\n".join(lines)\n\n    def forward(self, *a, **kw):  # pragma: no cover - абстрактный\n        raise NotImplementedError\n\n    def __call__(self, *a, **kw):\n        return self.forward(*a, **kw)\n\n\n# ----------------------------------------------------------------------- слои\nclass Linear(Module):\n    def __init__(self, in_features: int, out_features: int, bias: bool = True) -> None:\n        super().__init__()\n        self.weight = Parameter(kaiming(in_features, out_features))\n        self.bias = Parameter(np.zeros(out_features, dtype=np.float32)) if bias else None\n\n    def forward(self, x: Tensor) -> Tensor:\n        if x.shape[-1] != self.weight.shape[0]:\n            raise ValueError(\n                f"Linear: ожидался вход с последней размерностью {self.weight.shape[0]}, "\n                f"получен тензор {x.shape}. Проверьте in_features слоя."\n            )\n        out = x @ self.weight\n        return out + self.bias if self.bias is not None else out\n\n\nclass Embedding(Module):\n    def __init__(self, num_embeddings: int, dim: int) -> None:\n        super().__init__()\n        self.weight = Parameter(get_rng().standard_normal((num_embeddings, dim)).astype(np.float32) * 0.02)\n\n    def forward(self, idx) -> Tensor:\n        idx = np.asarray(idx.data if isinstance(idx, Tensor) else idx).astype(int)\n        if idx.size:\n            lo, hi = int(idx.min()), int(idx.max())\n            n = self.weight.shape[0]\n            if lo < 0 or hi >= n:\n                raise IndexError(\n                    f"Embedding: индексы должны быть в [0, {n - 1}], "\n                    f"получен диапазон [{lo}, {hi}]. Увеличьте num_embeddings "\n                    f"или проверьте словарь токенизатора."\n                )\n        return self.weight[idx]\n\n\nclass LayerNorm(Module):\n    def __init__(self, dim: int, eps: float = 1e-5) -> None:\n        super().__init__()\n        self.eps = eps\n        self.gamma = Parameter(np.ones(dim, dtype=np.float32))\n        self.beta = Parameter(np.zeros(dim, dtype=np.float32))\n\n    def forward(self, x: Tensor) -> Tensor:\n        mu = x.mean(axis=-1, keepdims=True)\n        xc = x - mu\n        var = (xc ** 2).mean(axis=-1, keepdims=True)\n        return xc / (var + self.eps).sqrt() * self.gamma + self.beta\n\n\nclass RMSNorm(Module):\n    """RMSNorm (LLaMA/T5): нормировка без вычитания среднего — быстрее LayerNorm."""\n\n    def __init__(self, dim: int, eps: float = 1e-6) -> None:\n        super().__init__()\n        self.eps = eps\n        self.gamma = Parameter(np.ones(dim, dtype=np.float32))\n\n    def forward(self, x: Tensor) -> Tensor:\n        rms = ((x ** 2).mean(axis=-1, keepdims=True) + self.eps).sqrt()\n        return x / rms * self.gamma\n\n\nclass BatchNorm1d(Module):\n    def __init__(self, dim: int, eps: float = 1e-5, momentum: float = 0.1) -> None:\n        super().__init__()\n        self.eps, self.momentum = eps, momentum\n        self.gamma = Parameter(np.ones(dim, dtype=np.float32))\n        self.beta = Parameter(np.zeros(dim, dtype=np.float32))\n        self.running_mean = np.zeros(dim, dtype=np.float32)\n        self.running_var = np.ones(dim, dtype=np.float32)\n\n    def forward(self, x: Tensor) -> Tensor:\n        if self.training:\n            mu = x.mean(axis=0, keepdims=True)\n            xc = x - mu\n            var = (xc ** 2).mean(axis=0, keepdims=True)\n            self.running_mean = (1 - self.momentum) * self.running_mean + self.momentum * mu.data.squeeze(0)\n            self.running_var = (1 - self.momentum) * self.running_var + self.momentum * var.data.squeeze(0)\n            norm = xc / (var + self.eps).sqrt()\n        else:\n            norm = (x - Tensor(self.running_mean)) / Tensor(self.running_var + self.eps).sqrt()\n        return norm * self.gamma + self.beta\n\n\nclass Dropout(Module):\n    def __init__(self, p: float = 0.1) -> None:\n        super().__init__()\n        self.p = p\n\n    def forward(self, x: Tensor) -> Tensor:\n        return x.dropout(self.p, self.training)\n\n\nclass ReLU(Module):\n    def forward(self, x: Tensor) -> Tensor:\n        return x.relu()\n\n\nclass GELU(Module):\n    def forward(self, x: Tensor) -> Tensor:\n        return x.gelu()\n\n\nclass SiLU(Module):\n    def forward(self, x: Tensor) -> Tensor:\n        return x.silu()\n\n\nclass Tanh(Module):\n    def forward(self, x: Tensor) -> Tensor:\n        return x.tanh()\n\n\nclass Sigmoid(Module):\n    def forward(self, x: Tensor) -> Tensor:\n        return x.sigmoid()\n\n\nclass Flatten(Module):\n    def forward(self, x: Tensor) -> Tensor:\n        return x.flatten(1)\n\n\nclass Sequential(Module):\n    def __init__(self, *layers: Module) -> None:\n        super().__init__()\n        self.layers = list(layers)\n        for i, l in enumerate(layers):\n            self._modules[str(i)] = l\n\n    def forward(self, x: Tensor) -> Tensor:\n        for layer in self.layers:\n            x = layer(x)\n        return x\n\n\nclass Residual(Module):\n    """x + f(x) — обёртка для остаточных связей."""\n\n    def __init__(self, fn: Module) -> None:\n        super().__init__()\n        self.fn = fn\n\n    def forward(self, x: Tensor) -> Tensor:\n        return x + self.fn(x)\n\n\n# ------------------------------------------------------------------- свёртки\ndef _im2col(x: np.ndarray, kh: int, kw: int, stride: int, pad: int) -> np.ndarray:\n    n, c, h, w = x.shape\n    oh = (h + 2 * pad - kh) // stride + 1\n    ow = (w + 2 * pad - kw) // stride + 1\n    xp = np.pad(x, ((0, 0), (0, 0), (pad, pad), (pad, pad)))\n    cols = np.empty((n, c, kh, kw, oh, ow), dtype=np.float32)\n    for i in range(kh):\n        for j in range(kw):\n            cols[:, :, i, j] = xp[:, :, i:i + stride * oh:stride, j:j + stride * ow:stride]\n    return cols.transpose(0, 4, 5, 1, 2, 3).reshape(n * oh * ow, -1), oh, ow\n\n\ndef _col2im(cols: np.ndarray, shape, kh, kw, stride, pad, oh, ow) -> np.ndarray:\n    n, c, h, w = shape\n    cols = cols.reshape(n, oh, ow, c, kh, kw).transpose(0, 3, 4, 5, 1, 2)\n    xp = np.zeros((n, c, h + 2 * pad, w + 2 * pad), dtype=np.float32)\n    for i in range(kh):\n        for j in range(kw):\n            xp[:, :, i:i + stride * oh:stride, j:j + stride * ow:stride] += cols[:, :, i, j]\n    return xp[:, :, pad:pad + h, pad:pad + w]\n\n\nclass Conv2d(Module):\n    """Свёртка через im2col, форма входа (N, C, H, W)."""\n\n    def __init__(self, in_ch: int, out_ch: int, kernel_size: int = 3, stride: int = 1,\n                 padding: int = 0, bias: bool = True) -> None:\n        super().__init__()\n        self.in_ch, self.out_ch = in_ch, out_ch\n        self.k, self.stride, self.pad = kernel_size, stride, padding\n        fan_in = in_ch * kernel_size * kernel_size\n        self.weight = Parameter(get_rng().standard_normal((out_ch, fan_in)).astype(np.float32) * math.sqrt(2.0 / fan_in))\n        self.bias = Parameter(np.zeros(out_ch, dtype=np.float32)) if bias else None\n\n    def forward(self, x: Tensor) -> Tensor:\n        n = x.shape[0]\n        cols, oh, ow = _im2col(x.data, self.k, self.k, self.stride, self.pad)\n        w = self.weight\n        out_data = cols @ w.data.T\n        if self.bias is not None:\n            out_data = out_data + self.bias.data\n        out_data = out_data.reshape(n, oh, ow, self.out_ch).transpose(0, 3, 1, 2)\n        parents = [p for p in (x, w, self.bias) if p is not None]\n        out = x._make(out_data, parents, "conv2d")\n        xshape = x.shape\n\n        def _backward() -> None:\n            g = out.grad.transpose(0, 2, 3, 1).reshape(-1, self.out_ch)\n            w._accum(g.T @ cols)\n            if self.bias is not None:\n                self.bias._accum(g.sum(0))\n            if x.requires_grad:\n                dcols = g @ w.data\n                x._accum(_col2im(dcols, xshape, self.k, self.k, self.stride, self.pad, oh, ow))\n\n        out._backward = _backward\n        return out\n\n\nclass MaxPool2d(Module):\n    def __init__(self, kernel_size: int = 2, stride: Optional[int] = None) -> None:\n        super().__init__()\n        self.k = kernel_size\n        self.stride = stride or kernel_size\n\n    def forward(self, x: Tensor) -> Tensor:\n        n, c, h, w = x.shape\n        k, s = self.k, self.stride\n        oh, ow = (h - k) // s + 1, (w - k) // s + 1\n        strided = np.lib.stride_tricks.as_strided(\n            x.data,\n            shape=(n, c, oh, ow, k, k),\n            strides=x.data.strides[:2] + (x.data.strides[2] * s, x.data.strides[3] * s) + x.data.strides[2:],\n        )\n        flat = strided.reshape(n, c, oh, ow, k * k)\n        arg = flat.argmax(-1)\n        out = x._make(flat.max(-1), (x,), "maxpool")\n\n        def _backward() -> None:\n            gx = np.zeros_like(x.data)\n            ii, jj = np.divmod(arg, k)\n            nidx, cidx, hidx, widx = np.indices((n, c, oh, ow))\n            np.add.at(gx, (nidx, cidx, hidx * s + ii, widx * s + jj), out.grad)\n            x._accum(gx)\n\n        out._backward = _backward\n        return out\n\n\nclass AvgPool2d(Module):\n    """Усредняющий пулинг (N, C, H, W)."""\n\n    def __init__(self, kernel_size: int = 2, stride: Optional[int] = None) -> None:\n        super().__init__()\n        self.k = kernel_size\n        self.stride = stride or kernel_size\n\n    def forward(self, x: Tensor) -> Tensor:\n        n, c, h, w = x.shape\n        k, s = self.k, self.stride\n        oh, ow = (h - k) // s + 1, (w - k) // s + 1\n        strided = np.lib.stride_tricks.as_strided(\n            x.data,\n            shape=(n, c, oh, ow, k, k),\n            strides=x.data.strides[:2] + (x.data.strides[2] * s, x.data.strides[3] * s) + x.data.strides[2:],\n        )\n        out = x._make(strided.reshape(n, c, oh, ow, k * k).mean(-1), (x,), "avgpool")\n\n        def _backward() -> None:\n            gx = np.zeros_like(x.data)\n            g = out.grad / (k * k)\n            for i in range(k):\n                for j in range(k):\n                    gx[:, :, i:i + s * oh:s, j:j + s * ow:s] += g\n            x._accum(gx)\n\n        out._backward = _backward\n        return out\n\n\n# ---------------------------------------------------------------- внимание\nclass RotaryEmbedding(Module):\n    """RoPE — вращательное позиционное кодирование (LLaMA, GPT-NeoX).\n\n    Кодирует относительные позиции прямо в q/k, поэтому модель лучше\n    обобщается на длины, не встречавшиеся при обучении.\n    """\n\n    def __init__(self, head_dim: int, max_seq: int = 4096, base: float = 10000.0) -> None:\n        super().__init__()\n        assert head_dim % 2 == 0, "head_dim должен быть чётным для RoPE"\n        self.head_dim = head_dim\n        inv_freq = 1.0 / (base ** (np.arange(0, head_dim, 2, dtype=np.float32) / head_dim))\n        t = np.arange(max_seq, dtype=np.float32)\n        freqs = np.outer(t, inv_freq)\n        self.cos = np.cos(freqs).astype(np.float32)  # (max_seq, head_dim/2)\n        self.sin = np.sin(freqs).astype(np.float32)\n\n    def forward(self, x: Tensor, offset: int = 0) -> Tensor:\n        """x: (B, H, T, head_dim) -> повёрнутый тензор той же формы."""\n        t = x.shape[2]\n        cos = self.cos[offset:offset + t][None, None]  # (1,1,T,hd/2)\n        sin = self.sin[offset:offset + t][None, None]\n        x1 = x[:, :, :, 0::2]\n        x2 = x[:, :, :, 1::2]\n        rot1 = x1 * Tensor(cos) - x2 * Tensor(sin)\n        rot2 = x1 * Tensor(sin) + x2 * Tensor(cos)\n        # обратное чередование: (..., hd/2, 2) -> (..., hd)\n        stacked = cat([rot1.reshape(*rot1.shape, 1), rot2.reshape(*rot2.shape, 1)], axis=-1)\n        return stacked.reshape(*x.shape)\n\n\nclass MultiHeadAttention(Module):\n    """Многоголовое самовнимание: causal-маска, RoPE и KV-кэш для генерации."""\n\n    def __init__(self, dim: int, n_heads: int, dropout: float = 0.0, causal: bool = True,\n                 rope: bool = False, max_seq: int = 4096) -> None:\n        super().__init__()\n        assert dim % n_heads == 0, "dim должен делиться на n_heads"\n        self.dim, self.n_heads, self.head_dim = dim, n_heads, dim // n_heads\n        self.causal = causal\n        self.qkv = Linear(dim, 3 * dim, bias=False)\n        self.proj = Linear(dim, dim)\n        self.attn_drop = Dropout(dropout)\n        self.resid_drop = Dropout(dropout)\n        self.rope = RotaryEmbedding(self.head_dim, max_seq) if rope else None\n        self._cache: Optional[tuple] = None\n\n    def reset_cache(self) -> None:\n        self._cache = None\n\n    def forward(self, x: Tensor, use_cache: bool = False) -> Tensor:\n        b, t, c = x.shape\n        # один reshape+transpose вместо трёх срезов: (B,T,3C) -> (3,B,H,T,hd)\n        qkv = self.qkv(x).reshape(b, t, 3, self.n_heads, self.head_dim).transpose(2, 0, 3, 1, 4)\n        q, k, v = qkv[0], qkv[1], qkv[2]\n\n        offset = self._cache[0].shape[2] if (use_cache and self._cache is not None) else 0\n        if self.rope is not None:\n            q, k = self.rope(q, offset), self.rope(k, offset)\n\n        if use_cache:\n            if self._cache is not None:\n                pk, pv = self._cache\n                k = cat([Tensor(pk), k], axis=2)\n                v = cat([Tensor(pv), v], axis=2)\n            self._cache = (k.data, v.data)\n\n        att = (q @ k.transpose(0, 1, 3, 2)) * (1.0 / math.sqrt(self.head_dim))\n        if self.causal:\n            tk = k.shape[2]\n            # при генерации с кэшем запрос видит весь префикс, маска сдвигается на offset\n            mask = np.triu(np.ones((t, tk), dtype=bool), k=1 + offset)[None, None]\n            att = att.masked_fill(np.broadcast_to(mask, att.shape), -1e9)\n        att = self.attn_drop(att.softmax(axis=-1))\n        y = (att @ v).transpose(0, 2, 1, 3).reshape(b, t, c)\n        return self.resid_drop(self.proj(y))\n\n\nclass SwiGLU(Module):\n    """SwiGLU-MLP из LLaMA: gate * silu(up) — сильнее обычного GELU-MLP."""\n\n    def __init__(self, dim: int, hidden: Optional[int] = None, dropout: float = 0.0) -> None:\n        super().__init__()\n        hidden = hidden or int(8 * dim / 3 // 32 * 32) or 4 * dim\n        self.w_gate = Linear(dim, hidden, bias=False)\n        self.w_up = Linear(dim, hidden, bias=False)\n        self.w_down = Linear(hidden, dim, bias=False)\n        self.drop = Dropout(dropout)\n\n    def forward(self, x: Tensor) -> Tensor:\n        return self.drop(self.w_down(self.w_gate(x).silu() * self.w_up(x)))\n\n\nclass TransformerBlock(Module):\n    """Pre-LN блок трансформера: attention + MLP с остаточными связями.\n\n    Поддерживает современный режим (RMSNorm + RoPE + SwiGLU) и классический\n    GPT-2 (LayerNorm + выученные позиции + GELU-MLP).\n    """\n\n    def __init__(self, dim: int, n_heads: int, mlp_ratio: int = 4, dropout: float = 0.0,\n                 causal: bool = True, rope: bool = False, norm: str = "layer",\n                 swiglu: bool = False, max_seq: int = 4096) -> None:\n        super().__init__()\n        make_norm = (lambda: RMSNorm(dim)) if norm == "rms" else (lambda: LayerNorm(dim))\n        self.ln1 = make_norm()\n        self.attn = MultiHeadAttention(dim, n_heads, dropout, causal, rope=rope, max_seq=max_seq)\n        self.ln2 = make_norm()\n        if swiglu:\n            self.mlp = SwiGLU(dim, dropout=dropout)\n        else:\n            self.mlp = Sequential(\n                Linear(dim, mlp_ratio * dim),\n                GELU(),\n                Linear(mlp_ratio * dim, dim),\n                Dropout(dropout),\n            )\n\n    def forward(self, x: Tensor, use_cache: bool = False) -> Tensor:\n        x = x + self.attn(self.ln1(x), use_cache=use_cache)\n        return x + self.mlp(self.ln2(x))\n\n\n# -------------------------------------------------------------- рекуррентность\nclass RNNCell(Module):\n    def __init__(self, in_dim: int, hidden: int) -> None:\n        super().__init__()\n        self.wx = Linear(in_dim, hidden, bias=False)\n        self.wh = Linear(hidden, hidden)\n\n    def forward(self, x: Tensor, h: Tensor) -> Tensor:\n        return (self.wx(x) + self.wh(h)).tanh()\n\n\nclass LSTMCell(Module):\n    """LSTM-ячейка с входным/забывающим/выходным вентилями."""\n\n    def __init__(self, in_dim: int, hidden: int) -> None:\n        super().__init__()\n        self.x2h = Linear(in_dim, 4 * hidden)\n        self.h2h = Linear(hidden, 4 * hidden, bias=False)\n        self.hidden = hidden\n\n    def forward(self, x: Tensor, state) -> tuple:\n        h, c = state\n        g = self.x2h(x) + self.h2h(h)\n        n = self.hidden\n        i = g[:, 0:n].sigmoid()\n        f = g[:, n:2 * n].sigmoid()\n        o = g[:, 2 * n:3 * n].sigmoid()\n        u = g[:, 3 * n:4 * n].tanh()\n        c_new = f * c + i * u\n        return o * c_new.tanh(), c_new\n\n\nclass GRUCell(Module):\n    def __init__(self, in_dim: int, hidden: int) -> None:\n        super().__init__()\n        self.xz, self.hz = Linear(in_dim, hidden), Linear(hidden, hidden, bias=False)\n        self.xr, self.hr = Linear(in_dim, hidden), Linear(hidden, hidden, bias=False)\n        self.xn, self.hn = Linear(in_dim, hidden), Linear(hidden, hidden, bias=False)\n\n    def forward(self, x: Tensor, h: Tensor) -> Tensor:\n        z = (self.xz(x) + self.hz(h)).sigmoid()\n        r = (self.xr(x) + self.hr(h)).sigmoid()\n        n = (self.xn(x) + r * self.hn(h)).tanh()\n        return (1 - z) * n + z * h\n\n\n__all__ = [\n    "Parameter", "Module", "Linear", "Embedding", "LayerNorm", "RMSNorm", "BatchNorm1d",\n    "Dropout", "ReLU", "GELU", "SiLU", "Tanh", "Sigmoid", "Flatten", "Sequential", "Residual",\n    "Conv2d", "MaxPool2d", "AvgPool2d", "RotaryEmbedding", "MultiHeadAttention", "SwiGLU",\n    "TransformerBlock", "RNNCell", "GRUCell", "LSTMCell",\n]\n'

_SOURCES['ultranet.optim'] = '"""Оптимизаторы и планировщики скорости обучения."""\nfrom __future__ import annotations\n\nimport math\nfrom typing import List, Optional, Sequence\n\nimport numpy as np\n\nfrom .nn import Parameter\n\n\nclass Optimizer:\n    def __init__(self, params: Sequence[Parameter], lr: float) -> None:\n        self.params: List[Parameter] = [p for p in params if p is not None]\n        self.lr = lr\n        self.t = 0\n\n    def zero_grad(self) -> None:\n        for p in self.params:\n            p.grad = None\n\n    def clip_grad_norm(self, max_norm: float) -> float:\n        total = math.sqrt(sum(float((p.grad ** 2).sum()) for p in self.params if p.grad is not None))\n        if total > max_norm and total > 0:\n            scale = max_norm / (total + 1e-6)\n            for p in self.params:\n                if p.grad is not None:\n                    p.grad *= scale\n        return total\n\n    def step(self) -> None:  # pragma: no cover\n        raise NotImplementedError\n\n\nclass SGD(Optimizer):\n    """SGD с моментом, поддержкой Nesterov и weight decay."""\n\n    def __init__(self, params, lr: float = 1e-2, momentum: float = 0.9,\n                 weight_decay: float = 0.0, nesterov: bool = False) -> None:\n        super().__init__(params, lr)\n        self.momentum, self.wd, self.nesterov = momentum, weight_decay, nesterov\n        self.buf = [np.zeros_like(p.data) for p in self.params]\n\n    def step(self) -> None:\n        self.t += 1\n        for i, p in enumerate(self.params):\n            if p.grad is None:\n                continue\n            g = p.grad + self.wd * p.data\n            self.buf[i] = self.momentum * self.buf[i] + g\n            upd = g + self.momentum * self.buf[i] if self.nesterov else self.buf[i]\n            p.data -= self.lr * upd\n\n\nclass Adam(Optimizer):\n    """Adam / AdamW (decoupled weight decay)."""\n\n    def __init__(self, params, lr: float = 1e-3, betas=(0.9, 0.999), eps: float = 1e-8,\n                 weight_decay: float = 0.0, decoupled: bool = True) -> None:\n        super().__init__(params, lr)\n        self.b1, self.b2 = betas\n        self.eps, self.wd, self.decoupled = eps, weight_decay, decoupled\n        self.m = [np.zeros_like(p.data) for p in self.params]\n        self.v = [np.zeros_like(p.data) for p in self.params]\n        #: переиспользуемый буфер под знаменатель — чтобы не аллоцировать на шаге\n        self._buf = [np.zeros_like(p.data) for p in self.params]\n\n    def step(self) -> None:\n        self.t += 1\n        bc1 = 1 - self.b1 ** self.t\n        bc2 = 1 - self.b2 ** self.t\n        for i, p in enumerate(self.params):\n            if p.grad is None:\n                continue\n            g = p.grad\n            if self.wd and not self.decoupled:\n                g = g + self.wd * p.data\n            # in-place: раньше каждая строка порождала новый массив на каждый\n            # параметр каждый шаг. Для GPT-2.7M это ~50 аллокаций на шаг.\n            m, v = self.m[i], self.v[i]\n            m *= self.b1\n            m += (1 - self.b1) * g\n            v *= self.b2\n            v += (1 - self.b2) * (g * g)\n            if self.wd and self.decoupled:\n                p.data -= self.lr * self.wd * p.data\n            # буфер переиспользуется: sqrt(v/bc2) + eps\n            denom = self._buf[i]\n            np.multiply(v, 1.0 / bc2, out=denom)\n            np.sqrt(denom, out=denom)\n            denom += self.eps\n            np.divide(m, denom, out=denom)\n            p.data -= (self.lr / bc1) * denom\n\n\nAdamW = Adam\n\n\nclass RMSprop(Optimizer):\n    def __init__(self, params, lr: float = 1e-3, alpha: float = 0.99, eps: float = 1e-8) -> None:\n        super().__init__(params, lr)\n        self.alpha, self.eps = alpha, eps\n        self.sq = [np.zeros_like(p.data) for p in self.params]\n\n    def step(self) -> None:\n        self.t += 1\n        for i, p in enumerate(self.params):\n            if p.grad is None:\n                continue\n            self.sq[i] = self.alpha * self.sq[i] + (1 - self.alpha) * p.grad ** 2\n            p.data -= self.lr * p.grad / (np.sqrt(self.sq[i]) + self.eps)\n\n\nclass Lion(Optimizer):\n    """Lion (EvoLved Sign Momentum, Google 2023) — знаковые обновления, мало памяти."""\n\n    def __init__(self, params, lr: float = 1e-4, betas=(0.9, 0.99), weight_decay: float = 0.0) -> None:\n        super().__init__(params, lr)\n        self.b1, self.b2 = betas\n        self.wd = weight_decay\n        self.m = [np.zeros_like(p.data) for p in self.params]\n\n    def step(self) -> None:\n        self.t += 1\n        for i, p in enumerate(self.params):\n            if p.grad is None:\n                continue\n            upd = np.sign(self.b1 * self.m[i] + (1 - self.b1) * p.grad)\n            if self.wd:\n                p.data -= self.lr * self.wd * p.data\n            p.data -= self.lr * upd\n            self.m[i] = self.b2 * self.m[i] + (1 - self.b2) * p.grad\n\n\nclass Adagrad(Optimizer):\n    def __init__(self, params, lr: float = 1e-2, eps: float = 1e-10) -> None:\n        super().__init__(params, lr)\n        self.eps = eps\n        self.sq = [np.zeros_like(p.data) for p in self.params]\n\n    def step(self) -> None:\n        self.t += 1\n        for i, p in enumerate(self.params):\n            if p.grad is None:\n                continue\n            self.sq[i] += p.grad ** 2\n            p.data -= self.lr * p.grad / (np.sqrt(self.sq[i]) + self.eps)\n\n\nclass Lookahead(Optimizer):\n    """Lookahead (Zhang et al.): «медленные» веса догоняют быстрые каждые k шагов."""\n\n    def __init__(self, base: Optimizer, k: int = 5, alpha: float = 0.5) -> None:\n        self.base, self.k, self.alpha = base, k, alpha\n        self.params = base.params\n        self.t = 0\n        self.slow = [p.data.copy() for p in self.params]\n\n    @property\n    def lr(self) -> float:\n        return self.base.lr\n\n    @lr.setter\n    def lr(self, v: float) -> None:\n        self.base.lr = v\n\n    def zero_grad(self) -> None:\n        self.base.zero_grad()\n\n    def clip_grad_norm(self, max_norm: float) -> float:\n        return self.base.clip_grad_norm(max_norm)\n\n    def step(self) -> None:\n        self.base.step()\n        self.t += 1\n        if self.t % self.k == 0:\n            for i, p in enumerate(self.params):\n                self.slow[i] += self.alpha * (p.data - self.slow[i])\n                p.data = self.slow[i].copy()\n\n\nclass EMA:\n    """Экспоненциальное скользящее среднее весов — обычно даёт лучший eval.\n\n    Использует «прогрев» decay = min(decay, (1+t)/(10+t)), поэтому на ранних\n    шагах среднее не отстаёт от весов (иначе короткое обучение ломается).\n    """\n\n    def __init__(self, params: Sequence[Parameter], decay: float = 0.999,\n                 warmup: bool = True) -> None:\n        self.params = list(params)\n        self.decay = decay\n        self.warmup = warmup\n        self.num_updates = 0\n        self.shadow = [p.data.copy() for p in self.params]\n        self._backup: Optional[List[np.ndarray]] = None\n\n    def _current_decay(self) -> float:\n        if not self.warmup:\n            return self.decay\n        t = self.num_updates\n        return min(self.decay, (1.0 + t) / (10.0 + t))\n\n    def update(self) -> None:\n        self.num_updates += 1\n        d = self._current_decay()\n        for i, p in enumerate(self.params):\n            self.shadow[i] = d * self.shadow[i] + (1 - d) * p.data\n\n    def apply(self) -> None:\n        """Подставить усреднённые веса (с возможностью восстановить)."""\n        self._backup = [p.data.copy() for p in self.params]\n        for p, s in zip(self.params, self.shadow):\n            p.data = s.copy()\n\n    def restore(self) -> None:\n        if self._backup is not None:\n            for p, b in zip(self.params, self._backup):\n                p.data = b\n            self._backup = None\n\n\nclass CosineWarmup:\n    """Косинусный спад с линейным прогревом (как у GPT)."""\n\n    def __init__(self, optimizer: Optimizer, warmup: int, total: int, min_lr_ratio: float = 0.1) -> None:\n        self.opt, self.warmup, self.total = optimizer, max(1, warmup), total\n        self.base_lr, self.min_ratio, self.step_num = optimizer.lr, min_lr_ratio, 0\n\n    def step(self) -> float:\n        self.step_num += 1\n        if self.step_num <= self.warmup:\n            lr = self.base_lr * self.step_num / self.warmup\n        else:\n            prog = min(1.0, (self.step_num - self.warmup) / max(1, self.total - self.warmup))\n            lr = self.base_lr * (self.min_ratio + (1 - self.min_ratio) * 0.5 * (1 + math.cos(math.pi * prog)))\n        self.opt.lr = lr\n        return lr\n\n\nclass StepLR:\n    """Ступенчатое снижение lr каждые step_size шагов."""\n\n    def __init__(self, optimizer: Optimizer, step_size: int, gamma: float = 0.1) -> None:\n        self.opt, self.step_size, self.gamma = optimizer, step_size, gamma\n        self.base_lr, self.step_num = optimizer.lr, 0\n\n    def step(self) -> float:\n        self.step_num += 1\n        self.opt.lr = self.base_lr * self.gamma ** (self.step_num // self.step_size)\n        return self.opt.lr\n\n\nclass OneCycleLR:\n    """One-cycle политика Лесли Смита: разогрев до max_lr и спад почти до нуля."""\n\n    def __init__(self, optimizer: Optimizer, max_lr: float, total: int,\n                 pct_start: float = 0.3, final_div: float = 1e4) -> None:\n        self.opt, self.max_lr, self.total = optimizer, max_lr, max(1, total)\n        self.warm = max(1, int(total * pct_start))\n        self.init_lr = max_lr / 25.0\n        self.final_lr = max_lr / final_div\n        self.step_num = 0\n\n    def step(self) -> float:\n        self.step_num += 1\n        if self.step_num <= self.warm:\n            prog = self.step_num / self.warm\n            lr = self.init_lr + (self.max_lr - self.init_lr) * 0.5 * (1 - math.cos(math.pi * prog))\n        else:\n            prog = min(1.0, (self.step_num - self.warm) / max(1, self.total - self.warm))\n            lr = self.final_lr + (self.max_lr - self.final_lr) * 0.5 * (1 + math.cos(math.pi * prog))\n        self.opt.lr = lr\n        return lr\n\n\nclass ReduceLROnPlateau:\n    """Снижает lr, когда метрика перестаёт улучшаться."""\n\n    def __init__(self, optimizer: Optimizer, factor: float = 0.5, patience: int = 3,\n                 min_lr: float = 1e-6) -> None:\n        self.opt, self.factor, self.patience, self.min_lr = optimizer, factor, patience, min_lr\n        self.best, self.bad = float("inf"), 0\n\n    def step(self, metric: float) -> float:\n        if metric < self.best - 1e-6:\n            self.best, self.bad = metric, 0\n        else:\n            self.bad += 1\n            if self.bad >= self.patience:\n                self.opt.lr = max(self.min_lr, self.opt.lr * self.factor)\n                self.bad = 0\n        return self.opt.lr\n'

_SOURCES['ultranet.proteus'] = '"""Proteus — подсистема UltraNet: вложенная байтовая модель, живущая на любом железе."""\nfrom .adapt import Feedback, LoRALayer, PersonalAdapter\nfrom .assembly import Assembly, ProteusBody, detect_triggers\nfrom .capsules import Capsule, CapsuleRegistry, Level\nfrom .catalog import CATALOG, BY_KEY, CapsuleSpec, Group, Stage, by_group\nfrom .context import Activity, AdaptationLoops, Context, Place, Style, style_for\nfrom .core import Proteus, Response\nfrom .growth import (LADDER, GrowingProteus, GrowthState, HardwareProfile,\n                     ladder_table, next_stage, probe_hardware, stage_at)\nfrom .experts import MoE, Expert\nfrom .shards import Shard, ShardedSwarm, SwarmNode\nfrom .steering import SteeringLibrary, SteeringVector\nfrom .weights import (RVQ, ComplexWeight, FisherImportance, FractalStack,\n                      HyperNetwork, LogPolarWeight, SphericalWeight,\n                      compare_methods, cosine, rel_error, slerp)\nfrom .bytes import ByteTokenizer, make_byte_batches\nfrom .controller import RLMetaController, MetaController, Plan\nfrom .devices import DEVICES, Device, DeviceState, get_device, list_devices\nfrom .memory import Doc, LocalMemory\nfrom .swarm import Node, Swarm\nfrom .matformer import MatBlock, MatConfig, MatFormer\nfrom .train import evaluate_widths, train_matryoshka\nfrom .quant import TernaryLinear, ste_round, QuantStats, TernaryModel, quantization_error, ternary_quantize\n\n__all__ = [\n    "TernaryLinear",\n    "ste_round",\n    "RLMetaController",\n    "Proteus", "Response",\n    "MoE", "Expert", "SteeringLibrary", "SteeringVector",\n    "PersonalAdapter", "LoRALayer", "Feedback",\n    "Capsule", "CapsuleRegistry", "Level",\n    "CATALOG", "BY_KEY", "CapsuleSpec", "Group", "Stage", "by_group",\n    "ProteusBody", "Assembly", "detect_triggers",\n    "SphericalWeight", "LogPolarWeight", "RVQ", "FisherImportance",\n    "FractalStack", "ComplexWeight", "HyperNetwork", "compare_methods",\n    "rel_error", "cosine", "slerp",\n    "GrowingProteus", "GrowthState", "HardwareProfile", "probe_hardware",\n    "LADDER", "stage_at", "next_stage", "ladder_table",\n    "Shard", "ShardedSwarm", "SwarmNode",\n    "Context", "Activity", "Place", "Style", "style_for", "AdaptationLoops",\n    "ByteTokenizer", "make_byte_batches",\n    "MatConfig", "MatFormer", "MatBlock",\n    "Device", "DeviceState", "DEVICES", "get_device", "list_devices",\n    "MetaController", "Plan",\n    "LocalMemory", "Doc", "Swarm", "Node",\n    "train_matryoshka", "evaluate_widths",\n    "TernaryModel", "QuantStats", "ternary_quantize", "quantization_error",\n]\n'

_SOURCES['ultranet.proteus.adapt'] = '"""Персонализация: LoRA-адаптеры, защита от forgetting, четыре петли адаптации.\n\n«Ядро заморожено. Меняются только маленькие надстройки — несколько мегабайт».\n\nЗащита от забывания реализована тремя способами из спецификации:\n  1. Ортогональная инициализация новых адаптеров к старым.\n  2. Replay — подмешивание старых примеров.\n  3. Регуляризация важных весов (EWC-подобная).\n"""\nfrom __future__ import annotations\n\nimport math\nfrom collections import deque\nfrom dataclasses import dataclass, field\nfrom typing import Deque, Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\nfrom ..functional import cross_entropy\nfrom ..nn import Module, Parameter\nfrom ..optim import Adam\nfrom ..tensor import Tensor, get_rng, no_grad\n\n\nclass LoRALayer(Module):\n    """Низкоранговая добавка: W_eff = W + (B @ A) * scale.\n\n    Обучаются только A и B — это r*(in+out) параметров вместо in*out.\n    """\n\n    def __init__(self, in_f: int, out_f: int, rank: int = 4, alpha: float = 8.0) -> None:\n        super().__init__()\n        self.in_f, self.out_f, self.rank = in_f, out_f, rank\n        self.scale = alpha / rank\n        # A ~ N(0, σ), B = 0 -> в начале адаптер не меняет поведение\n        self.A = Parameter(get_rng().standard_normal((in_f, rank)).astype(np.float32)\n                           * (1.0 / math.sqrt(in_f)))\n        self.B = Parameter(np.zeros((rank, out_f), dtype=np.float32))\n\n    def forward(self, x: Tensor, in_d: Optional[int] = None,\n                out_d: Optional[int] = None) -> Tensor:\n        in_d = in_d or self.in_f\n        out_d = out_d or self.out_f\n        return (x @ self.A[:in_d]) @ self.B[:, :out_d] * self.scale\n\n    def delta(self, in_d: Optional[int] = None, out_d: Optional[int] = None) -> np.ndarray:\n        in_d = in_d or self.in_f\n        out_d = out_d or self.out_f\n        return (self.A.data[:in_d] @ self.B.data[:, :out_d]) * self.scale\n\n    def n_params(self) -> int:\n        return self.A.size + self.B.size\n\n    def orthogonalize_to(self, others: Sequence["LoRALayer"]) -> None:\n        """Ортогонализовать A к подпространствам прошлых адаптеров (Грам-Шмидт).\n\n        Новый адаптер не пересекается со старыми -> меньше интерференции.\n        """\n        if not others:\n            return\n        basis: List[np.ndarray] = []\n        for o in others:\n            for col in o.A.data.T:\n                v = col.copy()\n                for b in basis:\n                    v -= np.dot(v, b) * b\n                n = np.linalg.norm(v)\n                if n > 1e-6:\n                    basis.append(v / n)\n        newA = self.A.data.copy()\n        for j in range(newA.shape[1]):\n            v = newA[:, j]\n            for b in basis:\n                v -= np.dot(v, b) * b\n            n = np.linalg.norm(v)\n            newA[:, j] = v / n * (1.0 / math.sqrt(self.in_f)) if n > 1e-6 else newA[:, j]\n        self.A.data = newA\n\n    def overlap_with(self, other: "LoRALayer") -> float:\n        """Косинусная близость подпространств (0 = ортогональны)."""\n        def orth(M: np.ndarray) -> np.ndarray:\n            q, _ = np.linalg.qr(M)\n            return q\n        qa, qb = orth(self.A.data), orth(other.A.data)\n        return float(np.abs(qa.T @ qb).max())\n\n\n@dataclass\nclass Feedback:\n    """Сигнал от пользователя: правка, лайк, игнор."""\n\n    ids: List[int]\n    reward: float = 1.0        # 1 = нравится, -1 = плохо, 0 = нейтрально\n    tag: str = ""\n\n\nclass PersonalAdapter(Module):\n    """Набор LoRA-адаптеров поверх замороженного ядра.\n\n    >>> pa = PersonalAdapter(model, rank=4)\n    >>> pa.observe(Feedback(ids, reward=1.0))\n    >>> pa.consolidate(steps=20)     # раз в несколько часов\n    """\n\n    def __init__(self, model, rank: int = 4, alpha: float = 8.0,\n                 replay_size: int = 64) -> None:\n        super().__init__()\n        # ВАЖНО: ядро хранится в обход Module.__setattr__, иначе оно попадёт\n        # в _modules и parameters() вернёт его веса — оптимизатор начнёт\n        # обучать ядро, хотя спецификация требует «ядро заморожено».\n        object.__setattr__(self, "model", model)\n        self.rank = rank\n        d = model.cfg.n_embd\n        # адаптеры на выходных проекциях внимания каждого слоя\n        self.loras: Dict[int, LoRALayer] = {}\n        for i in range(model.cfg.n_layer):\n            lora = LoRALayer(d, d, rank, alpha)\n            self.loras[i] = lora\n            self._modules[f"lora{i}"] = lora\n        self.buffer: Deque[Feedback] = deque(maxlen=replay_size)\n        self.replay: Deque[List[int]] = deque(maxlen=replay_size)\n        self.fisher: Dict[str, np.ndarray] = {}\n        self.anchor: Dict[str, np.ndarray] = {}\n        self.updates = 0\n        self.enabled = True\n\n    # -------------------------------------------------------------- параметры\n    def n_params(self) -> int:\n        return sum(l.n_params() for l in self.loras.values())\n\n    def core_params(self) -> int:\n        return self.model.num_params()\n\n    def ratio(self) -> float:\n        return self.n_params() / max(self.core_params(), 1)\n\n    def core_frozen(self) -> bool:\n        """Ядро не должно получать градиенты при обучении адаптера."""\n        return all(p.grad is None or not np.abs(p.grad).any()\n                   for p in self.model.parameters())\n\n    # ----------------------------------------------------------------- петли\n    def observe(self, fb: Feedback) -> None:\n        """Быстрая петля: копим сигналы (лайки/правки)."""\n        self.buffer.append(fb)\n\n    def add_replay(self, ids: Sequence[int]) -> None:\n        """Старые примеры для защиты от забывания."""\n        self.replay.append(list(ids))\n\n    def snapshot_importance(self, ids: Sequence[int], block: int) -> None:\n        """Оценить важность параметров адаптера (диагональ Фишера) и закрепить."""\n        params = dict(self.named_parameters())\n        arr = np.array([list(ids)[:block]], dtype=int)\n        x, y = arr[:, :-1], arr[:, 1:]\n        for p in params.values():\n            p.grad = None\n        loss = cross_entropy(self.forward_with_adapter(x), y)\n        loss.backward()\n        for name, p in params.items():\n            g = np.zeros_like(p.data) if p.grad is None else p.grad\n            self.fisher[name] = self.fisher.get(name, 0.0) + g ** 2\n            self.anchor[name] = p.data.copy()\n            p.grad = None\n\n    # -------------------------------------------------------------- forward\n    def forward_with_adapter(self, idx, width: float = 1.0) -> Tensor:\n        """Прогон модели с активными LoRA-добавками."""\n        d = self.model.width_dim(width)\n        x = self.model.embed(idx, d)\n        for i in range(self.model.cfg.n_layer):\n            x = self.model.run_block(i, x, d)\n            if self.enabled:\n                x = x + self.loras[i](x, d, d)\n        return self.model.readout(x, d)\n\n    # ---------------------------------------------------------- консолидация\n    def consolidate(self, steps: int = 20, lr: float = 1e-3, block: int = 32,\n                    ewc_lambda: float = 1.0, replay_ratio: float = 0.5,\n                    verbose: bool = False) -> Dict[str, List[float]]:\n        """Средняя петля: дообучить адаптеры на накопленных сигналах.\n\n        Ядро заморожено: оптимизатор видит только параметры LoRA.\n        """\n        if not self.buffer:\n            return {"loss": []}\n        opt = Adam(self.parameters(), lr=lr)      # ТОЛЬКО параметры адаптера\n        hist: List[float] = []\n        pos = [f for f in self.buffer if f.reward > 0]\n        if not pos:\n            return {"loss": []}\n\n        for step in range(steps):\n            use_replay = self.replay and np.random.rand() < replay_ratio\n            if use_replay:\n                ids = list(self.replay[np.random.randint(len(self.replay))])\n            else:\n                ids = list(pos[np.random.randint(len(pos))].ids)\n            ids = ids[:block + 1]\n            if len(ids) < 4:\n                continue\n            arr = np.array([ids], dtype=int)\n            x, y = arr[:, :-1], arr[:, 1:]\n\n            opt.zero_grad()\n            loss = cross_entropy(self.forward_with_adapter(x), y)\n            # EWC-регуляризация: важные веса держатся около якоря\n            if self.fisher and ewc_lambda > 0:\n                for name, p in self.named_parameters():\n                    if name in self.fisher:\n                        f = Tensor(self.fisher[name])\n                        a = Tensor(self.anchor[name])\n                        loss = loss + ((p - a) ** 2 * f).sum() * ewc_lambda\n            loss.backward()\n            opt.clip_grad_norm(1.0)\n            opt.step()\n            hist.append(loss.item())\n            if verbose and step % 10 == 0:\n                print(f"    адаптер шаг {step}: {loss.item():.4f}")\n\n        self.updates += 1\n        return {"loss": hist}\n\n    def new_task_adapter(self, layer: int) -> LoRALayer:\n        """Создать адаптер для новой задачи, ортогональный существующим."""\n        d = self.model.cfg.n_embd\n        fresh = LoRALayer(d, d, self.rank)\n        fresh.orthogonalize_to([self.loras[layer]])\n        return fresh\n\n    # ------------------------------------------------------------------ вес\n    def size_bytes(self, bits: float = 16.0) -> int:\n        return int(self.n_params() * bits / 8)\n\n    def report(self) -> str:\n        return (f"LoRA rank={self.rank}: {self.n_params():,} параметров "\n                f"({self.size_bytes() / 1024:.1f} КБ) против ядра "\n                f"{self.core_params():,} — {self.ratio() * 100:.2f}% | "\n                f"обновлений: {self.updates}")\n'

_SOURCES['ultranet.proteus.assembly'] = '"""Сборка Протея из 48 капсул под конкретный запрос и конкретное железо.\n\n«Что не нужно — не активируется». Движок делает три вещи:\n  1. Понимает, какие капсулы нужны запросу (триггеры + зависимости).\n  2. Отсекает те, что не влезают в железо.\n  3. Выстраивает их в конвейер: вход -> понимание -> память -> мышление\n     -> экспертиза -> генерация -> проверка, плюс фоновые.\n"""\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass, field\nfrom typing import Dict, Iterable, List, Optional, Sequence, Set, Tuple\n\nimport numpy as np\n\nfrom .capsules import Capsule, CapsuleRegistry, Level\nfrom .catalog import (BY_KEY, CATALOG, GROUP_COUNTS, CapsuleSpec, Group, Stage,\n                      resolve_deps, tier_rank)\nfrom .devices import Device, DeviceState, get_device\n\n#: слова запроса -> триггеры капсул\n_KEYWORDS: Dict[str, Tuple[str, ...]] = {\n    "код": ("код", "функци", "程序", "def ", "class ", "багу", "баг", "рефактор",\n            "скрипт", "программ", "python", "тест"),\n    "математика": ("посчитай", "сколько будет", "уравнен", "реши", "интеграл",\n                   "производн", "формул", "процент"),\n    "творчество": ("стих", "сочини", "придумай", "поэм", "рассказ", "истори",\n                   "песн", "идея", "идеи"),\n    "рассуждение": ("почему", "объясни", "проанализируй", "разбер", "сравни",\n                    "докажи", "как работает"),\n    "план": ("план", "распиши шаги", "организуй", "спланируй", "расписание"),\n    "перевод": ("переведи", "перевод", "как будет по-", "translate", "на японск",\n                "на английск", "на русск"),\n    "медицина": ("симптом", "болит", "боль", "лекарств", "диагноз", "анализ крови",\n                 "давлени", "температура тела", "врач"),\n    "право": ("договор", "закон", "юрид", "иск", "штраф", "суд"),\n    "финансы": ("расход", "инвест", "налог", "бюджет", "зарплат", "кредит"),\n    "наука": ("стать", "гипотез", "исследован", "эксперимент", "публикац",\n              "научн"),\n    "изображение": ("нарисуй", "картинк", "изображен", "фото", "видео", "сцен"),\n    "голос": ("скажи вслух", "озвучь", "голосом", "произнеси"),\n    "аудио": ("послушай", "запись", "звук", "шум"),\n    "действие": ("открой", "закрой", "отправь", "включи", "выключи", "купи",\n                 "позвони", "напомни"),\n    "жест": ("жест", "покажи руками", "язык жестов"),\n    "сенсор": ("пульс", "шаги", "сон", "температур", "давлени"),\n    "формула": ("формула", "ноты", "днк", "химическ", "шахмат"),\n}\n\n\ndef detect_triggers(prompt: str) -> Set[str]:\n    """Какие триггеры зажигает запрос."""\n    p = prompt.lower()\n    found = {t for t, words in _KEYWORDS.items() if any(w in p for w in words)}\n    found.add("текст")                      # текст на входе есть всегда\n    return found\n\n\n@dataclass\nclass Assembly:\n    """Собранный Протей: какие капсулы проснулись и во что это обошлось."""\n\n    prompt: str\n    device: Device\n    active: List[CapsuleSpec]\n    skipped: List[CapsuleSpec]\n    unavailable: List[CapsuleSpec]\n    triggers: Set[str]\n    params: int\n    bytes_used: int\n    budget: int\n\n    # --------------------------------------------------------------- доли\n    @property\n    def n_active(self) -> int:\n        return len(self.active)\n\n    @property\n    def capsule_fraction(self) -> float:\n        return self.n_active / len(CATALOG)\n\n    @property\n    def foreground(self) -> List[CapsuleSpec]:\n        """Капсулы конвейера — без фоновых служб, которые работают всегда."""\n        return [c for c in self.active if c.stage is not Stage.BACKGROUND]\n\n    @property\n    def foreground_fraction(self) -> float:\n        total = len([c for c in CATALOG if c.stage is not Stage.BACKGROUND])\n        return len(self.foreground) / max(total, 1)\n\n    def heavy_active(self, threshold: int = 50_000_000) -> List[CapsuleSpec]:\n        """Тяжёлые капсулы (>50M) — именно они определяют реальную цену."""\n        return [c for c in self.active\n                if c.params_for(self.device) >= threshold]\n\n    @property\n    def fits(self) -> bool:\n        return self.bytes_used <= self.budget\n\n    @property\n    def degraded(self) -> List[CapsuleSpec]:\n        """Капсулы, которые железо потянуло бы, но не хватило бюджета памяти."""\n        active = {c.key for c in self.active}\n        unavail = {c.key for c in self.unavailable}\n        return [c for c in self.skipped\n                if c.key not in active and c.key not in unavail\n                and (c.always_on or c.triggers & self.triggers)]\n\n    def energy_fraction(self) -> float:\n        """Грубая доля энергии: активные параметры от полного тела."""\n        total = sum(c.params_for(self.device) for c in CATALOG\n                    if c.fits_on(self.device))\n        return self.params / max(total, 1)\n\n    # ------------------------------------------------------------ конвейер\n    def pipeline(self) -> List[Tuple[Stage, List[CapsuleSpec]]]:\n        """Активные капсулы, выстроенные по стадиям обработки."""\n        out: List[Tuple[Stage, List[CapsuleSpec]]] = []\n        for st in Stage:\n            caps = sorted([c for c in self.active if c.stage is st], key=lambda c: c.key)\n            if caps:\n                out.append((st, caps))\n        return out\n\n    def groups_used(self) -> Dict[Group, int]:\n        d: Dict[Group, int] = {}\n        for c in self.active:\n            d[c.group] = d.get(c.group, 0) + 1\n        return d\n\n    def names(self) -> List[str]:\n        return [c.name for c in self.active]\n\n    # -------------------------------------------------------------- отчёты\n    def explain(self) -> str:\n        stage_names = {\n            Stage.INPUT: "вход", Stage.PARSE: "понимание", Stage.RECALL: "память",\n            Stage.REASON: "мышление", Stage.EXPERT: "экспертиза",\n            Stage.PRODUCE: "генерация", Stage.VERIFY: "проверка",\n            Stage.BACKGROUND: "фон",\n        }\n        lines = [f"запрос: «{self.prompt}»",\n                 f"железо: {self.device}",\n                 f"триггеры: {\', \'.join(sorted(self.triggers))}",\n                 ""]\n        n = 0\n        for st, caps in self.pipeline():\n            lines.append(f"  [{stage_names[st]}]")\n            for c in caps:\n                n += 1\n                p = c.params_for(self.device)\n                lines.append(f"    {n:>2}. {c.name:<26} {p / 1e6:>8.1f}M  {c.does[:44]}")\n        lines.append("")\n        n_heavy = len(self.heavy_active())\n        total_heavy = len([c for c in CATALOG\n                           if c.params_for(self.device) >= 50_000_000])\n        lines.append(f"активно {self.n_active} из {len(CATALOG)} капсул "\n                     f"({self.capsule_fraction * 100:.0f}%), из них в конвейере "\n                     f"{len(self.foreground)} ({self.foreground_fraction * 100:.0f}%)")\n        lines.append(f"тяжёлых (>50M) задействовано {n_heavy} из {total_heavy}; "\n                     f"{self.params / 1e6:.0f}M параметров, "\n                     f"{self.bytes_used / 1024 / 1024:.1f} МБ "\n                     f"из бюджета {self.budget / 1024 / 1024:.1f} МБ")\n        if self.skipped:\n            names = ", ".join(c.name for c in self.skipped[:6])\n            lines.append(f"не активировалось ({len(self.skipped)}): {names}…")\n        if self.unavailable:\n            lines.append(f"не помещается на это железо: {len(self.unavailable)} капсул")\n        if self.degraded:\n            names = ", ".join(c.name for c in self.degraded[:5])\n            lines.append(f"урезано по памяти ({len(self.degraded)}): {names}…")\n        return "\\n".join(lines)\n\n    def __str__(self) -> str:\n        return (f"Assembly({self.n_active}/{len(CATALOG)} капсул, "\n                f"{self.params / 1e6:.0f}M, {\'влезает\' if self.fits else \'НЕ влезает\'})")\n\n\nclass ProteusBody:\n    """Полное тело Протея: все 48 капсул и правила их сборки.\n\n    >>> body = ProteusBody("phone")\n    >>> a = body.assemble("напиши код сортировки")\n    >>> "Кодовая экспертная" in a.names()\n    True\n    """\n\n    def __init__(self, device: str | Device = "phone",\n                 state: Optional[DeviceState] = None) -> None:\n        self.device = get_device(device) if isinstance(device, str) else device\n        self.state = state or DeviceState(self.device)\n\n    # ------------------------------------------------------------ выбор\n    def available(self) -> List[CapsuleSpec]:\n        """Капсулы, которые физически могут жить на этом железе."""\n        return [c for c in CATALOG if c.fits_on(self.device)]\n\n    def _needed_keys(self, triggers: Set[str], want: Sequence[str] = ()) -> Set[str]:\n        keys: Set[str] = set(want)\n        for c in CATALOG:\n            if c.always_on:\n                keys.add(c.key)\n            if c.triggers & triggers:\n                keys.add(c.key)\n        # текстовый ответ нужен почти всегда\n        keys.add("gen_text")\n        return resolve_deps(keys)\n\n    def assemble(self, prompt: str, want: Sequence[str] = (),\n                 respect_budget: bool = True) -> Assembly:\n        """Собрать тело под запрос: триггеры -> зависимости -> бюджет."""\n        triggers = detect_triggers(prompt)\n        needed = self._needed_keys(triggers, want)\n\n        avail = {c.key for c in self.available()}\n        unavailable = [BY_KEY[k] for k in sorted(needed - avail)]\n        chosen = [BY_KEY[k] for k in sorted(needed & avail)]\n\n        tier = self.device          # передаём устройство: размер зависит от RAM\n        budget = self.state.available_bytes\n        # приоритет: всегда включённые и ранние стадии выживают первыми\n        chosen.sort(key=lambda c: (not c.always_on, int(c.stage), -c.params_for(tier)))\n\n        # Бюджет обязателен для всех, включая always_on: на смарт-карте с 16 КБ\n        # физически не может жить 26 МБ фоновых служб. Дешёвые капсулы идут\n        # первыми, чтобы при жёстком лимите выжило максимум функций.\n        chosen.sort(key=lambda c: (not c.always_on, int(c.stage), c.params_for(tier)))\n        active: List[CapsuleSpec] = []\n        used = 0\n        for c in chosen:\n            b = c.bytes_for(tier)\n            if respect_budget and used + b > budget:\n                continue\n            active.append(c)\n            used += b\n\n        active_keys = {c.key for c in active}\n        skipped = [c for c in CATALOG\n                   if c.key not in active_keys and c.key not in {x.key for x in unavailable}]\n        params = sum(c.params_for(tier) for c in active)\n        return Assembly(prompt, self.device, active, skipped, unavailable,\n                        triggers, params, used, budget)\n\n    # --------------------------------------------------------- как дерево\n    def to_registry(self, assembly: Optional[Assembly] = None) -> CapsuleRegistry:\n        """Представить тело деревом капсул (орган = группа, клетка = капсула)."""\n        tier = self.device\n        active_keys = {c.key for c in assembly.active} if assembly else set()\n        root = Capsule("Протей", Level.BODY, 0, {"ядро"})\n        for g in Group:\n            organ = Capsule(g.value, Level.ORGAN, 0, {"ядро"})\n            for spec in [c for c in CATALOG if c.group is g]:\n                cell = Capsule(spec.name, Level.CELL, spec.params_for(tier),\n                               set(spec.skills))\n                if spec.key in active_keys:\n                    cell.wake()\n                organ.children.append(cell)\n            root.children.append(organ)\n        return CapsuleRegistry(root)\n\n    # -------------------------------------------------------------- отчёты\n    def inventory(self) -> str:\n        """Сводная таблица каталога — как в спецификации."""\n        tier = self.device\n        lines = [f"Каталог капсул Протея на «{self.device.name}» [{self.device.tier}]",\n                 f"{\'группа\':<14}{\'капсул\':>7}{\'влезает\':>9}{\'параметров\':>14}"]\n        total = fit_total = 0\n        for g in Group:\n            caps = [c for c in CATALOG if c.group is g]\n            fit = [c for c in caps if c.fits_on(self.device)]\n            p = sum(c.params_for(tier) for c in fit)\n            total += len(caps)\n            fit_total += len(fit)\n            lines.append(f"{g.value:<14}{len(caps):>7}{len(fit):>9}{p / 1e6:>12.0f}M")\n        allp = sum(c.params_for(tier) for c in CATALOG if c.fits_on(self.device))\n        lines.append(f"{\'ВСЕГО\':<14}{total:>7}{fit_total:>9}{allp / 1e6:>12.0f}M")\n        return "\\n".join(lines)\n\n    def device_capabilities(self) -> str:\n        """Какие группы капсул доступны на разных классах железа."""\n        rows = ["устройство          micro→ сенс пони памя мышл эксп гене упра адап сист  всего"]\n        for key in ("smartcard", "esp32", "earbuds", "smartwatch", "phone",\n                    "laptop", "workstation", "server"):\n            dev = get_device(key)\n            cells = []\n            for g in Group:\n                n = sum(1 for c in CATALOG if c.group is g and c.fits_on(dev))\n                cells.append(f"{n:>4}")\n            tot = sum(1 for c in CATALOG if c.fits_on(dev))\n            rows.append(f"{dev.name:<20}{dev.tier:<7}{\'\'.join(cells)}{tot:>7}")\n        return "\\n".join(rows)\n'

_SOURCES['ultranet.proteus.bytes'] = '"""Байтовый «токенизатор» — словаря нет вовсе.\n\nРеализует заявление Протея: «Токенизатор отсутствует. Каждый байт — вход».\nЛюбой UTF-8 текст кодируется без <unk>, все языки равноправны по построению.\n"""\nfrom __future__ import annotations\n\nfrom typing import Dict, List, Sequence\n\nimport numpy as np\n\nPAD, BOS, EOS, MASK = 256, 257, 258, 259\n\n\nclass ByteTokenizer:\n    """Кодирование на уровне байтов: фиксированный «словарь» 256 + 4 спецтокена.\n\n    Словаря в обычном смысле нет — есть биекция байт <-> id, одинаковая\n    для всех языков, эмодзи, кода, нот и произвольных бинарных данных.\n\n    >>> tok = ByteTokenizer()\n    >>> tok.decode(tok.encode("привет 日本語 🚀")) == "привет 日本語 🚀"\n    True\n    """\n\n    vocab_size = 260\n    pad_id, bos_id, eos_id, mask_id = PAD, BOS, EOS, MASK\n\n    def encode(self, text: str, bos: bool = False, eos: bool = False) -> List[int]:\n        ids = list(text.encode("utf-8"))\n        if bos:\n            ids = [BOS] + ids\n        if eos:\n            ids = ids + [EOS]\n        return ids\n\n    def decode(self, ids: Sequence[int]) -> str:\n        raw = bytes(int(i) for i in ids if 0 <= int(i) < 256)\n        return raw.decode("utf-8", errors="replace")\n\n    def encode_bytes(self, data: bytes) -> List[int]:\n        """Произвольные бинарные данные — тоже последовательность."""\n        return list(data)\n\n    # ------------------------------------------------------------------ анализ\n    @staticmethod\n    def bytes_per_char(text: str) -> float:\n        """Сколько байтов приходится на символ — цена языка при байтовом входе."""\n        return len(text.encode("utf-8")) / max(len(text), 1)\n\n    @staticmethod\n    def fairness_report(samples: Dict[str, str]) -> Dict[str, Dict[str, float]]:\n        """Сравнить стоимость одного и того же смысла на разных языках.\n\n        Возвращает по языку: символы, байты, байт/символ.\n        """\n        out: Dict[str, Dict[str, float]] = {}\n        for lang, text in samples.items():\n            n_chars = len(text)\n            n_bytes = len(text.encode("utf-8"))\n            out[lang] = {\n                "chars": float(n_chars),\n                "bytes": float(n_bytes),\n                "bytes_per_char": n_bytes / max(n_chars, 1),\n            }\n        return out\n\n\ndef make_byte_batches(ids: Sequence[int], block_size: int, batch_size: int,\n                      seed: int | None = None):\n    """Случайные окна (x, y) из байтового потока."""\n    rng = np.random.default_rng(seed)\n    arr = np.asarray(ids, dtype=int)\n    if len(arr) < block_size + 2:\n        raise ValueError(\n            f"данных слишком мало: {len(arr)} байт при block_size={block_size}"\n        )\n    ix = rng.integers(0, len(arr) - block_size - 1, batch_size)\n    x = np.stack([arr[i:i + block_size] for i in ix])\n    y = np.stack([arr[i + 1:i + 1 + block_size] for i in ix])\n    return x, y\n'

_SOURCES['ultranet.proteus.capsules'] = '"""Наночастицы (капсулы): минимальные единицы Протея.\n\n«Капсула — функциональный блок, который знает про себя всё: сколько ест,\nчто умеет, как сжимается, как взаимодействует с другими».\n\nУровни вложенности из спецификации: атом -> молекула -> клетка -> орган -> тело.\nНеактивные капсулы «не существуют» — они не занимают ни памяти, ни энергии,\nпока не собраны (lazy materialization).\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom enum import IntEnum\nfrom typing import Callable, Dict, List, Optional, Sequence, Set\n\nimport numpy as np\n\n\nclass Level(IntEnum):\n    """Уровни вложенности наночастиц."""\n\n    ATOM = 0        # один нейрон / строка матрицы\n    MOLECULE = 1    # группа нейронов\n    CELL = 2        # слой\n    ORGAN = 3       # группа слоёв (эксперт, блок внимания)\n    BODY = 4        # весь Протей\n\n    @property\n    def label(self) -> str:\n        return {0: "атом", 1: "молекула", 2: "клетка", 3: "орган", 4: "тело"}[int(self)]\n\n\n@dataclass\nclass Capsule:\n    """Наночастица: веса + метаданные + интерфейс + состояние."""\n\n    name: str\n    level: Level\n    n_params: int\n    skills: Set[str] = field(default_factory=set)\n    children: List["Capsule"] = field(default_factory=list)\n    materialize: Optional[Callable[[], object]] = None\n    energy_per_call: float = 1.0\n    latency_ms: float = 1.0\n\n    # состояние\n    _awake: bool = field(default=False, init=False)\n    _payload: object = field(default=None, init=False)\n    calls: int = field(default=0, init=False)\n\n    # -------------------------------------------------------------- жизнь\n    @property\n    def awake(self) -> bool:\n        return self._awake\n\n    def wake(self, recursive: bool = False) -> object:\n        """Пробуждение: капсула собирается на месте из своих компонентов.\n\n        recursive=False — просыпается только сама капсула; её дети решают\n        сами (иначе пробуждение органа тянуло бы всех спящих экспертов).\n        """\n        if not self._awake:\n            self._payload = self.materialize() if self.materialize else None\n            self._awake = True\n        if recursive:\n            for c in self.children:\n                c.wake(recursive=True)\n        self.calls += 1\n        return self._payload\n\n    def sleep(self) -> None:\n        """Сон: капсула перестаёт существовать в памяти."""\n        self._payload = None\n        self._awake = False\n        for c in self.children:\n            c.sleep()\n\n    # -------------------------------------------------------------- размеры\n    def bytes_at(self, bits: float = 2.0) -> int:\n        """Сколько весит капсула при заданной битности (по умолчанию 1.58-bit)."""\n        return int(self.total_params() * bits / 8)\n\n    def total_params(self) -> int:\n        return self.n_params + sum(c.total_params() for c in self.children)\n\n    def active_params(self) -> int:\n        """Только то, что реально проснулось (по всему поддереву)."""\n        own = self.n_params if self._awake else 0\n        return own + sum(c.active_params() for c in self.children)\n\n    def all_skills(self) -> Set[str]:\n        s = set(self.skills)\n        for c in self.children:\n            s |= c.all_skills()\n        return s\n\n    def matches(self, need: Sequence[str]) -> float:\n        """Насколько капсула подходит под требуемые навыки (0..1)."""\n        if not need:\n            return 0.0\n        have = self.all_skills()\n        return len(have & set(need)) / len(set(need))\n\n    def tree(self, indent: int = 0) -> str:\n        mark = "●" if self._awake else "○"\n        pad = "  " * indent\n        line = (f"{pad}{mark} {self.name:<22} {self.level.label:<9} "\n                f"{self.total_params():>9,} пар. {self.bytes_at() / 1024:>8.1f} КБ")\n        if self.skills:\n            line += f"  [{\', \'.join(sorted(self.skills))}]"\n        return "\\n".join([line] + [c.tree(indent + 1) for c in self.children])\n\n    def __repr__(self) -> str:\n        return f"Capsule({self.name}, {self.level.label}, {self.total_params():,})"\n\n\nclass CapsuleRegistry:\n    """Реестр капсул: сборка тела под задачу.\n\n    «Что не нужно — не активируется. Атомы "поэзия" спят».\n\n    >>> reg = CapsuleRegistry.from_model(model)\n    >>> reg.assemble(["код"])            # проснутся только кодовые капсулы\n    >>> reg.active_fraction() < 1.0\n    True\n    """\n\n    def __init__(self, root: Capsule) -> None:\n        self.root = root\n        self.index: Dict[str, Capsule] = {}\n        self._index(root)\n\n    def _index(self, c: Capsule) -> None:\n        self.index[c.name] = c\n        for ch in c.children:\n            self._index(ch)\n\n    # ------------------------------------------------------------- сборка\n    def assemble(self, need: Sequence[str], threshold: float = 0.01) -> List[Capsule]:\n        """Разбудить капсулы, подходящие под задачу; остальные спят."""\n        self.sleep_all()\n        woken: List[Capsule] = []\n        need_set = set(need)\n        for cap in self.index.values():\n            if cap.level is Level.BODY:\n                continue\n            # капсула нужна, если её СОБСТВЕННЫЕ навыки пересекаются с задачей\n            # либо это инфраструктура ядра (внимание, эмбеддинги)\n            own_match = bool(cap.skills & need_set)\n            is_core = "ядро" in cap.skills and not (cap.skills - {"ядро", "байты", "контекст"})\n            if own_match or is_core:\n                cap.wake()\n                woken.append(cap)\n\n        # фолбэк: если ни одна специализированная капсула не подошла,\n        # будим все — незнакомая задача должна решаться полным телом,\n        # а не голым ядром.\n        specialized = [c for c in woken if not ("ядро" in c.skills)]\n        if not specialized:\n            for cap in self.index.values():\n                if cap.level is not Level.BODY and not cap.awake:\n                    cap.wake()\n                    woken.append(cap)\n        return woken\n\n    def sleep_all(self) -> None:\n        self.root.sleep()\n\n    def wake_all(self) -> None:\n        self.root.wake(recursive=True)\n\n    # -------------------------------------------------------------- отчёты\n    def active_params(self) -> int:\n        return self.root.active_params()\n\n    def total_params(self) -> int:\n        return self.root.total_params()\n\n    def active_fraction(self) -> float:\n        return self.active_params() / max(self.total_params(), 1)\n\n    def by_level(self, level: Level) -> List[Capsule]:\n        return [c for c in self.index.values() if c.level == level]\n\n    def report(self) -> str:\n        lines = [f"капсул всего: {len(self.index)}, "\n                 f"активно: {sum(1 for c in self.index.values() if c.awake)}"]\n        for lvl in Level:\n            caps = self.by_level(lvl)\n            if caps:\n                awake = sum(1 for c in caps if c.awake)\n                lines.append(f"  {lvl.label:<9} {len(caps):>3} шт, активно {awake:>3}")\n        lines.append(f"активная доля параметров: {self.active_fraction() * 100:.1f}%")\n        return "\\n".join(lines)\n\n    # --------------------------------------------------------- из модели\n    @classmethod\n    def from_model(cls, model, skills_by_expert: Optional[Dict[int, Set[str]]] = None\n                   ) -> "CapsuleRegistry":\n        """Построить дерево капсул по реальной структуре MatFormer."""\n        cfg = model.cfg\n        d = cfg.n_embd\n        body = Capsule("Протей", Level.BODY, 0, {"ядро"})\n\n        emb = Capsule("эмбеддинги", Level.ORGAN, cfg.vocab_size * d, {"ядро", "байты"})\n        body.children.append(emb)\n\n        for li, blk in enumerate(model.blocks):\n            organ = Capsule(f"слой{li}", Level.ORGAN, 0, {"ядро"})\n            attn = Capsule(f"слой{li}.внимание", Level.CELL, 4 * d * d,\n                           {"ядро", "контекст"})\n            organ.children.append(attn)\n            if getattr(blk, "moe", None) is not None:\n                for ei, ex in enumerate(blk.moe.experts):\n                    sk = (skills_by_expert or {}).get(ei, {f"эксперт{ei}"})\n                    cell = Capsule(f"слой{li}.эксперт{ei}", Level.CELL,\n                                   ex.active_params(d), set(sk))\n                    # молекулы внутри эксперта\n                    for gi in range(2):\n                        cell.children.append(\n                            Capsule(f"слой{li}.эксперт{ei}.мол{gi}", Level.MOLECULE,\n                                    ex.active_params(d) // 8, set(sk))\n                        )\n                    organ.children.append(cell)\n            else:\n                organ.children.append(\n                    Capsule(f"слой{li}.mlp", Level.CELL, 3 * d * blk.mlp_dim, {"ядро"})\n                )\n            body.children.append(organ)\n        return cls(body)\n'

_SOURCES['ultranet.proteus.catalog'] = '"""Каталог всех 48 капсул Протея.\n\nДевять групп: сенсорные, понимания, памяти, мышления, экспертные,\nгенерации, управления, адаптации, системные.\n\nКаждая капсула знает про себя всё: сколько ест (min/max параметров),\nчто умеет (навыки), где может жить (минимальный класс железа), от кого\nзависит (граф) и когда просыпается (триггеры).\n"""\nfrom __future__ import annotations\n\nimport math\nfrom dataclasses import dataclass, field\nfrom enum import Enum\nfrom typing import Dict, Iterable, List, Optional, Sequence, Set, Tuple\n\nimport numpy as np\n\nfrom .capsules import Capsule, Level\nfrom .devices import Device, DeviceState, get_device\n\nK, M, B = 1_000, 1_000_000, 1_000_000_000\n\n#: порядок классов железа от слабого к сильному\nTIERS: Tuple[str, ...] = ("micro", "small", "medium", "large", "datacenter")\n\n\ndef tier_rank(tier: str) -> int:\n    return TIERS.index(tier) if tier in TIERS else 0\n\n\nclass Group(str, Enum):\n    """Девять групп капсул."""\n\n    SENSORY = "сенсорные"\n    UNDERSTANDING = "понимания"\n    MEMORY = "памяти"\n    THINKING = "мышления"\n    EXPERT = "экспертные"\n    GENERATION = "генерации"\n    CONTROL = "управления"\n    ADAPTATION = "адаптации"\n    SYSTEM = "системные"\n\n\nclass Stage(int, Enum):\n    """Позиция в конвейере обработки запроса."""\n\n    INPUT = 0        # приём сигнала\n    PARSE = 1        # понимание\n    RECALL = 2       # память\n    REASON = 3       # мышление\n    EXPERT = 4       # предметная экспертиза\n    PRODUCE = 5      # генерация\n    VERIFY = 6       # проверка\n    BACKGROUND = 7   # фон: управление, адаптация, система\n\n\n@dataclass(frozen=True)\nclass CapsuleSpec:\n    """Паспорт капсулы из каталога."""\n\n    key: str\n    name: str\n    group: Group\n    does: str\n    min_params: int\n    max_params: int\n    min_tier: str = "medium"\n    min_ram: int = 0                # 0 = ограничения по RAM нет\n    skills: frozenset = frozenset()\n    triggers: frozenset = frozenset()\n    depends_on: frozenset = frozenset()\n    stage: Stage = Stage.REASON\n    always_on: bool = False\n    private: bool = False\n    notes: str = ""\n\n    # ------------------------------------------------------------- размеры\n    #: опорные точки шкалы роста: RAM -> позиция 0..1 внутри диапазона капсулы\n    _RAM_LO = 32 * 1024 ** 2          # 32 МБ  -> минимальный размер\n    _RAM_HI = 512 * 1024 ** 3         # 512 ГБ -> максимальный размер\n\n    def params_for(self, tier_or_device=None, ram_bytes: Optional[int] = None) -> int:\n        """Сколько параметров капсула возьмёт на конкретном железе.\n\n        Размер тянется за РЕАЛЬНОЙ памятью, а не за ярлыком класса: иначе\n        Smart TV с 4 ГБ и рабочий ноутбук с 32 ГБ получали бы одинаковые\n        капсулы. Шкала логарифмическая — размеры растут на порядки.\n        """\n        tier, ram = self._resolve(tier_or_device, ram_bytes)\n        if tier_rank(tier) < tier_rank(self.min_tier):\n            return 0\n        if ram and self.min_ram and ram < self.min_ram:\n            return 0\n        lo, hi = float(self.min_params), float(self.max_params)\n        if ram is None:                      # известен только класс железа\n            span = tier_rank("datacenter") - tier_rank(self.min_tier)\n            pos = tier_rank(tier) - tier_rank(self.min_tier)\n            frac = 0.0 if span <= 0 else pos / span\n        else:\n            lo_r, hi_r = float(self._RAM_LO), float(self._RAM_HI)\n            r = min(max(float(ram), lo_r), hi_r)\n            frac = math.log(r / lo_r) / math.log(hi_r / lo_r)\n        return int(round(lo * (hi / lo) ** float(np.clip(frac, 0.0, 1.0))))\n\n    @staticmethod\n    def _resolve(tier_or_device, ram_bytes):\n        """Принимаем и строку-класс, и Device, и DeviceState — так удобнее."""\n        if tier_or_device is None:\n            return "medium", ram_bytes\n        if isinstance(tier_or_device, str):\n            return tier_or_device, ram_bytes\n        dev = getattr(tier_or_device, "device", tier_or_device)\n        return dev.tier, (ram_bytes if ram_bytes is not None else dev.ram_bytes)\n\n    def bytes_for(self, tier_or_device=None, bits: float = 2.0,\n                  ram_bytes: Optional[int] = None) -> int:\n        return int(self.params_for(tier_or_device, ram_bytes) * bits / 8)\n\n    def fits_on(self, device: Device) -> bool:\n        """Влезает ли капсула на устройство: и по классу, и по объёму RAM."""\n        return (tier_rank(device.tier) >= tier_rank(self.min_tier)\n                and device.ram_bytes >= self.min_ram)\n\n    def size_range(self) -> str:\n        def h(n: int) -> str:\n            if n >= B:\n                return f"{n / B:g}B"\n            if n >= M:\n                return f"{n / M:g}M"\n            if n >= K:\n                return f"{n / K:g}K"\n            return str(n)\n        return f"{h(self.min_params)}–{h(self.max_params)}"\n\n    def __str__(self) -> str:\n        return f"{self.name} [{self.group.value}, {self.size_range()}, от {self.min_tier}]"\n\n\ndef _c(key, name, group, does, lo, hi, tier, skills=(), triggers=(),\n       depends=(), stage=Stage.REASON, always_on=False, private=False, notes="",\n       min_ram=0):\n    return CapsuleSpec(key, name, group, does, lo, hi, tier, min_ram,\n                       frozenset(skills), frozenset(triggers), frozenset(depends),\n                       stage, always_on, private, notes)\n\n\n# ═══════════════════════════════════════════ ГРУППА 1: СЕНСОРНЫЕ (7)\n_SENSORY = [\n    _c("text_in", "Текстовая", Group.SENSORY,\n       "принимает байты текста, превращает в векторы смыслов",\n       1 * M, 500 * M, "small", ("текст", "байты", "языки"), ("текст",),\n       (), Stage.INPUT, notes="байтовый уровень: любой язык, опечатки, транслит"),\n    _c("voice_in", "Голосовая", Group.SENSORY,\n       "звук в байты: речь, интонация, эмоция, темп, диаризация",\n       5 * M, 300 * M, "small", ("звук", "речь", "эмоция"), ("аудио", "голос"),\n       (), Stage.INPUT, notes="офлайн; шум, акцент, шёпот"),\n    _c("vision_in", "Зрительная", Group.SENSORY,\n       "изображения и видео: объекты, лица, текст, сцены, движение",\n       10 * M, 1 * B, "medium", ("зрение", "объекты", "лица"), ("изображение", "видео"),\n       (), Stage.INPUT, notes="поток, а не кадры; «это твоя кошка»"),\n    _c("sensor_in", "Сенсорная", Group.SENSORY,\n       "датчики: температура, пульс, движение, свет, GPS, магнитометр",\n       1 * K, 50 * M, "micro", ("датчики", "тело", "движение"), ("сенсор", "пульс"),\n       (), Stage.INPUT, True, notes="реальное время; «пульс + движение = бег»"),\n    _c("code_in", "Кодовая (вход)", Group.SENSORY,\n       "код на любом языке: синтаксис, семантика, контекст проекта",\n       10 * M, 1 * B, "medium", ("код", "синтаксис"), ("код",),\n       (), Stage.INPUT, notes="структура проекта и зависимости"),\n    _c("gesture_in", "Жестовая", Group.SENSORY,\n       "движение рук, тела, мимика в смыслы",\n       5 * M, 200 * M, "medium", ("жесты", "мимика"), ("жест", "видео"),\n       (), Stage.INPUT, notes="ASL, РЖЯ, международный"),\n    _c("formal_in", "Формальная", Group.SENSORY,\n       "математика, логика, химия, ноты, ДНК, шахматы",\n       1 * M, 500 * M, "medium", ("формальное", "математика", "ноты", "днк"),\n       ("формула", "математика", "ноты"), (), Stage.INPUT,\n       notes="каждый формальный язык — подкапсула"),\n]\n\n# ═══════════════════════════════════════ ГРУППА 2: ПОНИМАНИЯ (4)\n_UNDERSTANDING = [\n    _c("meaning", "Смысла", Group.UNDERSTANDING,\n       "векторы в смыслы: не слова, а понятия",\n       10 * M, 1 * B, "medium", ("смысл", "понятия"), (),\n       ("text_in",), Stage.PARSE, notes="безъязыковая: собака = dog = 犬"),\n    _c("intent", "Интента", Group.UNDERSTANDING,\n       "что пользователь имел в виду, а не что сказал",\n       5 * M, 200 * M, "small", ("интент", "намерение"), (),\n       ("meaning",), Stage.PARSE, notes="вопрос / команда / просьба / шутка"),\n    _c("context", "Контекста", Group.UNDERSTANDING,\n       "время, место, активность, устройства, сеть, настроение",\n       1 * M, 100 * M, "small", ("контекст", "время", "место"), (),\n       (), Stage.PARSE, True, notes="в фоне, обновляется каждую секунду"),\n    _c("task", "Задачи", Group.UNDERSTANDING,\n       "классифицирует: факт, рассуждение, код, творчество, анализ, план",\n       1 * M, 50 * M, "micro", ("классификация", "задача"), (),\n       ("intent",), Stage.PARSE, True,\n       notes="решает за миллисекунды, включает остальные капсулы"),\n]\n\n# ══════════════════════════════════════════ ГРУППА 3: ПАМЯТИ (6)\n_MEMORY = [\n    _c("working_mem", "Рабочей памяти", Group.MEMORY,\n       "текущий контекст: последние сообщения, документы, факты",\n       10 * M, 500 * M, "micro", ("память", "контекст"), (),\n       (), Stage.RECALL, True, notes="аналог RAM: 2k / 8k / 128k токенов"),\n    _c("episodic_mem", "Эпизодической памяти", Group.MEMORY,\n       "события: «вчера ты спрашивал про проект»",\n       50 * M, 1 * B, "medium", ("память", "события", "время"), (),\n       (), Stage.RECALL, private=True, notes="временные метки, связь событий"),\n    _c("semantic_mem", "Семантической памяти", Group.MEMORY,\n       "факты о тебе: «твоя жена — Анна», «аллергия на пыль»",\n       100 * M, 2 * B, "medium", ("память", "факты"), (),\n       ("rag",), Stage.RECALL, True, private=True, notes="в RAG, только локально"),\n    _c("procedural_mem", "Процедурной памяти", Group.MEMORY,\n       "навыки: как ты пишешь письма, как решаешь задачи",\n       10 * M, 500 * M, "medium", ("память", "навыки", "стиль"), (),\n       ("lora",), Stage.RECALL, private=True, notes="хранится в LoRA-адаптерах"),\n    _c("rag", "RAG-поиска", Group.MEMORY,\n       "ищет в локальной базе: документы, заметки, сообщения",\n       5 * M, 200 * M, "small", ("поиск", "документы"), (),\n       (), Stage.RECALL, True, notes="HNSW, ~1 мс на 100 документах, офлайн"),\n    _c("forgetting", "Забывания", Group.MEMORY,\n       "удаляет устаревшее, неважное, дублирующееся",\n       1 * M, 50 * M, "micro", ("забывание", "приватность"), (),\n       (), Stage.BACKGROUND, True, private=True, notes="в фоне, оценивает важность"),\n]\n\n# ════════════════════════════════════════ ГРУППА 4: МЫШЛЕНИЯ (6)\n_THINKING = [\n    _c("logic", "Логики", Group.THINKING,\n       "логические цепочки, проверка противоречий, выводы",\n       50 * M, 2 * B, "medium", ("логика", "рассуждение"),\n       ("рассуждение", "анализ", "код", "математика", "план", "наука",\n        "право", "финансы", "медицина"),\n       ("meaning",), Stage.REASON, notes="пошагово, с откатом"),\n    _c("math", "Математики", Group.THINKING,\n       "считает, решает уравнения, доказывает теоремы",\n       20 * M, 1 * B, "medium", ("математика", "вычисления"), ("математика",),\n       ("formal_in",), Stage.REASON, notes="символьные + численные методы"),\n    _c("planning", "Планирования", Group.THINKING,\n       "строит планы, разбивает задачи, распределяет шаги",\n       30 * M, 1 * B, "medium", ("план", "декомпозиция"), ("план",),\n       ("logic",), Stage.REASON, notes="на несколько шагов вперёд"),\n    _c("creativity", "Творчества", Group.THINKING,\n       "генерирует новое: идеи, стихи, истории, музыку",\n       50 * M, 2 * B, "medium", ("творчество", "идеи"), ("творчество",),\n       (), Stage.REASON, notes="высокая temperature + steering «творчество»"),\n    _c("critic", "Критики", Group.THINKING,\n       "проверяет ответ: логику, факты, стиль, безопасность",\n       10 * M, 500 * M, "micro", ("критика", "проверка"), (),\n       (), Stage.VERIFY, True, notes="может вернуть на доработку"),\n    _c("reflection", "Рефлексии", Group.THINKING,\n       "анализирует своё мышление: «я ошибся здесь»",\n       20 * M, 1 * B, "medium", ("рефлексия", "самоанализ"), (),\n       ("critic",), Stage.BACKGROUND, notes="в фоне, обновляет адаптеры"),\n]\n\n# ═══════════════════════════════════════ ГРУППА 5: ЭКСПЕРТНЫЕ (6)\n_EXPERT = [\n    _c("expert_code", "Кодовая экспертная", Group.EXPERT,\n       "пишет, читает, рефакторит код на любом языке",\n       100 * M, 7 * B, "medium", ("код", "рефакторинг"), ("код",),\n       ("code_in",), Stage.EXPERT, notes="Python, C, Rust, JS; фреймворки"),\n    _c("expert_med", "Медицинская экспертная", Group.EXPERT,\n       "анализирует симптомы, лекарства, анализы",\n       200 * M, 7 * B, "medium", ("медицина", "здоровье"), ("медицина",),\n       (), Stage.EXPERT, private=True, notes="не заменяет врача; только локально"),\n    _c("expert_law", "Юридическая экспертная", Group.EXPERT,\n       "анализирует договоры, законы, права",\n       200 * M, 7 * B, "medium", ("право", "договоры"), ("право",),\n       (), Stage.EXPERT, private=True, notes="местное законодательство"),\n    _c("expert_sci", "Научная экспертная", Group.EXPERT,\n       "анализирует статьи, данные, гипотезы",\n       500 * M, 14 * B, "medium", ("наука", "данные"), ("наука",),\n       ("math",), Stage.EXPERT, notes="формулы и графики", min_ram=16 * 1024 ** 3),\n    _c("expert_fin", "Финансовая экспертная", Group.EXPERT,\n       "анализирует расходы, инвестиции, налоги",\n       100 * M, 3 * B, "medium", ("финансы", "прогноз"), ("финансы",),\n       (), Stage.EXPERT, private=True, notes="твои данные, прогнозы"),\n    _c("expert_lang", "Языковая экспертная", Group.EXPERT,\n       "переводит, объясняет грамматику, учит языку",\n       50 * M, 2 * B, "medium", ("перевод", "языки", "грамматика"), ("перевод",),\n       ("meaning",), Stage.EXPERT, notes="7000+ языков"),\n]\n\n# ══════════════════════════════════════ ГРУППА 6: ГЕНЕРАЦИИ (5)\n_GENERATION = [\n    _c("gen_text", "Текстовая генерация", Group.GENERATION,\n       "пишет текст на любом языке, в любом стиле",\n       50 * M, 7 * B, "micro", ("генерация", "текст"), (),\n       ("steering",), Stage.PRODUCE, True, notes="учитывает стиль пользователя"),\n    _c("gen_voice", "Голосовая генерация", Group.GENERATION,\n       "говорит голосом, похожим на твой или любой другой",\n       10 * M, 500 * M, "small", ("генерация", "голос"), ("голос",),\n       (), Stage.PRODUCE, notes="клонирование, эмоции, офлайн"),\n    _c("gen_image", "Визуальная генерация", Group.GENERATION,\n       "рисует, редактирует, анимирует изображения",\n       100 * M, 7 * B, "medium", ("генерация", "изображение"), ("изображение",),\n       (), Stage.PRODUCE, notes="диффузия + трансформер", min_ram=8 * 1024 ** 3),\n    _c("gen_code", "Кодовая генерация", Group.GENERATION,\n       "пишет код, тесты, документацию",\n       100 * M, 7 * B, "medium", ("генерация", "код"), ("код",),\n       ("expert_code",), Stage.PRODUCE, notes="пошагово, с проверкой синтаксиса"),\n    _c("action", "Действие", Group.GENERATION,\n       "выполняет действия: открыть, закрыть, отправить, купить",\n       1 * M, 100 * M, "micro", ("действие", "api"), ("действие",),\n       ("intent", "safety"), Stage.PRODUCE, notes="API + проверка безопасности"),\n]\n\n# ═════════════════════════════════════ ГРУППА 7: УПРАВЛЕНИЯ (5)\n_CONTROL = [\n    _c("meta", "Мета-контроллер", Group.CONTROL,\n       "какой размер, какие эксперты, где выход",\n       10 * M, 100 * M, "micro", ("управление", "бюджет"), (),\n       ("profiler",), Stage.BACKGROUND, True,\n       notes="RL-агент; награда = качество − задержка − энергия"),\n    _c("router", "Роутер", Group.CONTROL,\n       "выбирает, какие эксперты активировать",\n       5 * M, 50 * M, "micro", ("управление", "роутинг"), (),\n       ("task",), Stage.BACKGROUND, True, notes="на каждый запрос, быстрый"),\n    _c("early_exit", "Раннего выхода", Group.CONTROL,\n       "решает, когда остановиться",\n       1 * M, 20 * M, "micro", ("управление", "выход"), (),\n       (), Stage.BACKGROUND, True, notes="проверяет качество на каждом слое"),\n    _c("distribution", "Распределения", Group.CONTROL,\n       "какие слои на каком узле",\n       5 * M, 50 * M, "micro", ("управление", "рой"), (),\n       ("network",), Stage.BACKGROUND, True, notes="пересобирается каждую секунду"),\n    _c("safety", "Безопасности", Group.CONTROL,\n       "проверяет запросы и ответы на безопасность",\n       10 * M, 200 * M, "micro", ("безопасность", "приватность"), (),\n       (), Stage.VERIFY, True, private=True, notes="локально, без облака"),\n]\n\n# ═════════════════════════════════════ ГРУППА 8: АДАПТАЦИИ (4)\n_ADAPTATION = [\n    _c("lora", "LoRA", Group.ADAPTATION,\n       "хранит твои персональные адаптеры",\n       1 * M, 100 * M, "medium", ("адаптация", "персонализация"), (),\n       (), Stage.BACKGROUND, private=True,\n       notes="на устройстве; защита от forgetting; несколько адаптеров"),\n    _c("steering", "Steering vectors", Group.ADAPTATION,\n       "направляет мышление в момент ответа",\n       100 * K, 10 * M, "micro", ("адаптация", "направление"), (),\n       (), Stage.BACKGROUND, True, notes="не меняет веса, работает мгновенно"),\n    _c("feedback", "Фидбека", Group.ADAPTATION,\n       "собирает реакции: лайки, правки, игноры",\n       100 * K, 5 * M, "micro", ("адаптация", "обратная связь"), (),\n       ("lora",), Stage.BACKGROUND, True, private=True, notes="в фоне"),\n    _c("profiler", "Профилирования", Group.ADAPTATION,\n       "зондирует железо: RAM, GPU, батарея, температура",\n       100 * K, 5 * M, "micro", ("железо", "профиль"), (),\n       (), Stage.BACKGROUND, True, notes="каждые несколько секунд"),\n]\n\n# ══════════════════════════════════════ ГРУППА 9: СИСТЕМНЫЕ (5)\n_SYSTEM = [\n    _c("energy", "Энергии", Group.SYSTEM,\n       "управляет энергопотреблением",\n       1 * M, 20 * M, "micro", ("энергия", "батарея"), (),\n       ("profiler",), Stage.BACKGROUND, True, notes="сжимает Протея при низком заряде"),\n    _c("thermal", "Тепла", Group.SYSTEM,\n       "управляет троттлингом",\n       1 * M, 10 * M, "small", ("тепло", "троттлинг"), (),\n       ("profiler",), Stage.BACKGROUND, True, notes="перекладывает слои"),\n    _c("network", "Сети", Group.SYSTEM,\n       "управляет связью между узлами",\n       1 * M, 20 * M, "micro", ("сеть", "p2p"), (),\n       (), Stage.BACKGROUND, True, notes="Wi-Fi Direct, Bluetooth, Thread; шифрование"),\n    _c("storage", "Хранения", Group.SYSTEM,\n       "что хранить, что удалить, что сжать",\n       1 * M, 50 * M, "micro", ("хранение", "сжатие"), (),\n       (), Stage.BACKGROUND, True, notes="LRU-выгрузка, сжатие холодных слоёв"),\n    _c("update", "Обновления", Group.SYSTEM,\n       "новые знания, новые капсулы",\n       1 * M, 30 * M, "medium", ("обновление",), (),\n       ("network",), Stage.BACKGROUND, notes="в фоне, с откатом при ошибке"),\n]\n\n#: полный каталог: 48 капсул\nCATALOG: Tuple[CapsuleSpec, ...] = tuple(\n    _SENSORY + _UNDERSTANDING + _MEMORY + _THINKING + _EXPERT\n    + _GENERATION + _CONTROL + _ADAPTATION + _SYSTEM\n)\n\nBY_KEY: Dict[str, CapsuleSpec] = {c.key: c for c in CATALOG}\n\n#: сколько капсул в каждой группе (из сводной таблицы спецификации)\nGROUP_COUNTS: Dict[Group, int] = {\n    Group.SENSORY: 7, Group.UNDERSTANDING: 4, Group.MEMORY: 6,\n    Group.THINKING: 6, Group.EXPERT: 6, Group.GENERATION: 5,\n    Group.CONTROL: 5, Group.ADAPTATION: 4, Group.SYSTEM: 5,\n}\n\n\ndef by_group(group: Group) -> List[CapsuleSpec]:\n    return [c for c in CATALOG if c.group is group]\n\n\ndef resolve_deps(keys: Iterable[str]) -> Set[str]:\n    """Дотянуть все зависимости: капсула не работает без тех, на ком стоит."""\n    out: Set[str] = set()\n    stack = list(keys)\n    while stack:\n        k = stack.pop()\n        if k in out or k not in BY_KEY:\n            continue\n        out.add(k)\n        stack.extend(BY_KEY[k].depends_on)\n    return out\n'

_SOURCES['ultranet.proteus.context'] = '"""Адаптивность к контексту и четыре петли адаптации по скоростям.\n\nИз спецификации:\n  миллисекунды — steering-векторы (без обучения);\n  секунды      — мета-контроллер (ширина, слои, эксперты);\n  часы         — LoRA-адаптеры (персонализация);\n  недели       — база знаний / RAG (новые факты).\n\nКонтекст: время суток, место, активность, устройства рядом, сеть.\n«За рулём -> короткие ответы голосом. Ночью -> тише и короче».\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom enum import Enum\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\n\nclass Activity(str, Enum):\n    IDLE = "покой"\n    DRIVING = "за рулём"\n    WALKING = "ходьба"\n    WORKING = "работа"\n    SLEEPING = "сон"\n    MEETING = "встреча"\n\n\nclass Place(str, Enum):\n    HOME = "дом"\n    WORK = "работа"\n    TRANSIT = "транспорт"\n    OUTDOORS = "улица"\n    UNKNOWN = "неизвестно"\n\n\n@dataclass\nclass Context:\n    """Ситуация вокруг пользователя прямо сейчас."""\n\n    hour: int = 12                       # 0..23\n    place: Place = Place.UNKNOWN\n    activity: Activity = Activity.IDLE\n    nearby_devices: List[str] = field(default_factory=list)\n    network: str = "wifi"                # wifi | cellular | none\n    headphones: bool = False\n\n    @property\n    def is_night(self) -> bool:\n        return self.hour >= 23 or self.hour < 6\n\n    @property\n    def offline(self) -> bool:\n        return self.network == "none"\n\n    @property\n    def hands_busy(self) -> bool:\n        return self.activity in (Activity.DRIVING, Activity.WALKING)\n\n    def __str__(self) -> str:\n        return (f"{self.hour:02d}:00, {self.place.value}, {self.activity.value}, "\n                f"сеть={self.network}, рядом={len(self.nearby_devices)}")\n\n\n@dataclass\nclass Style:\n    """Как отвечать в данном контексте."""\n\n    max_tokens: int = 64\n    voice: bool = False\n    verbosity: float = 1.0        # 0 = телеграфно, 1 = обычно, 2 = подробно\n    steering: Optional[str] = None\n    reason: str = ""\n\n    def __str__(self) -> str:\n        v = "голосом" if self.voice else "текстом"\n        return (f"{v}, до {self.max_tokens} токенов, подробность {self.verbosity:.1f}"\n                + (f", вектор «{self.steering}»" if self.steering else "")\n                + f" [{self.reason}]")\n\n\ndef style_for(ctx: Context) -> Style:\n    """Правила из спецификации: контекст -> стиль ответа."""\n    if ctx.activity is Activity.DRIVING:\n        return Style(max_tokens=24, voice=True, verbosity=0.3,\n                     steering="простота", reason="за рулём: коротко и голосом")\n    if ctx.activity is Activity.SLEEPING or ctx.is_night:\n        return Style(max_tokens=24, voice=ctx.headphones, verbosity=0.4,\n                     steering="простота", reason="ночь: тихо и коротко")\n    if ctx.activity is Activity.MEETING:\n        return Style(max_tokens=32, voice=False, verbosity=0.5,\n                     reason="встреча: только текст, коротко")\n    if ctx.activity is Activity.WORKING and ctx.place is Place.WORK:\n        return Style(max_tokens=128, voice=False, verbosity=1.5,\n                     steering="детальность", reason="работа: подробно и технически")\n    if ctx.activity is Activity.WALKING:\n        return Style(max_tokens=32, voice=ctx.headphones, verbosity=0.5,\n                     reason="в движении: кратко")\n    return Style(reason="обычный режим")\n\n\n@dataclass\nclass LoopEvent:\n    loop: str\n    what: str\n    at_step: int\n\n\nclass AdaptationLoops:\n    """Четыре петли, работающие на разных скоростях одновременно.\n\n    >>> loops = AdaptationLoops(proteus)\n    >>> loops.tick(ctx)        # каждый запрос\n    >>> loops.log              # что сработало\n    """\n\n    # период срабатывания в «тиках» (условных запросах)\n    PERIOD = {"мс": 1, "сек": 1, "часы": 20, "недели": 50}\n\n    def __init__(self, proteus, consolidate_steps: int = 10) -> None:\n        self.p = proteus\n        self.steps = 0\n        self.consolidate_steps = consolidate_steps\n        self.log: List[LoopEvent] = []\n        self.counts: Dict[str, int] = {k: 0 for k in self.PERIOD}\n\n    def _fire(self, loop: str, what: str) -> None:\n        self.counts[loop] += 1\n        self.log.append(LoopEvent(loop, what, self.steps))\n\n    def tick(self, ctx: Context, prompt: str = "") -> Style:\n        """Один запрос: срабатывают те петли, чьё время пришло."""\n        self.steps += 1\n        style = style_for(ctx)\n\n        # ---- петля 1: миллисекунды — steering, без обучения\n        if style.steering and style.steering in self.p.steering:\n            self.p.steering.apply(style.steering)\n            self._fire("мс", f"вектор «{style.steering}»")\n        # ---- петля 2: секунды — мета-контроллер меняет конфигурацию\n        plan = self.p.controller.plan(self.p.state,\n                                      self.p.estimate_complexity(prompt) if prompt else 0.5)\n        self._fire("сек", f"план {plan.n_layers} слоёв, w={plan.width:.2f}")\n        # ---- петля 3: часы — консолидация LoRA\n        if self.steps % self.PERIOD["часы"] == 0 and self.p.adapter is not None:\n            self.p.consolidate(steps=self.consolidate_steps)\n            self._fire("часы", "консолидация LoRA")\n        # ---- петля 4: недели — перестройка базы знаний\n        if self.steps % self.PERIOD["недели"] == 0:\n            n = len(self.p.memory) if self.p.memory is not None else 0\n            self._fire("недели", f"переиндексация памяти ({n} фактов)")\n        return style\n\n    def report(self) -> str:\n        names = {"мс": "миллисекунды (steering)", "сек": "секунды (мета-контроллер)",\n                 "часы": "часы (LoRA)", "недели": "недели (знания)"}\n        lines = [f"тиков: {self.steps}"]\n        for k, v in self.counts.items():\n            lines.append(f"  {names[k]:<30} сработала {v:>3} раз")\n        return "\\n".join(lines)\n'

_SOURCES['ultranet.proteus.controller'] = '"""Мета-контроллер: пересобирает Протея под текущее железо и задачу.\n\nРеализует Часть 2 спецификации: профилирование -> сборка -> мышление ->\nранний выход. Решение принимается по реальному бюджету байтов, а не «на глаз»:\nконфигурация проверяется на то, что упакованные веса влезают в память.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import List, Optional, Sequence, Tuple\n\nimport math\n\nimport numpy as np\n\nfrom .devices import Device, DeviceState\nfrom .matformer import MatConfig, MatFormer\n\n\n@dataclass\nclass Plan:\n    """Решение мета-контроллера."""\n\n    width: float\n    n_layers: int\n    active_params: int\n    weight_bytes: int\n    exit_threshold: float\n    reason: str\n    fits: bool = True\n\n    def __str__(self) -> str:\n        kb = self.weight_bytes / 1024\n        size = f"{kb / 1024:.1f} МБ" if kb >= 1024 else f"{kb:.0f} КБ"\n        return (f"width={self.width:.2f} слоёв={self.n_layers} "\n                f"активно={self.active_params:,} ({size}) порог={self.exit_threshold:.2f} "\n                f"[{self.reason}]")\n\n\nclass MetaController:\n    """Выбирает максимальную конфигурацию, влезающую в бюджет устройства.\n\n    >>> mc = MetaController(model)\n    >>> plan = mc.plan(DeviceState(get_device("esp32")))\n    >>> plan.fits\n    True\n    """\n\n    # 2 бита на вес + fp32-скейлы: реальная стоимость тернарной упаковки\n    BITS_PER_WEIGHT = 2.0\n\n    def __init__(self, model: MatFormer, bits_per_weight: float = BITS_PER_WEIGHT) -> None:\n        self.model = model\n        self.bits = bits_per_weight\n        self.candidates = self._build_candidates()\n\n    def _build_candidates(self) -> List[Tuple[float, int]]:\n        cfg = self.model.cfg\n        widths = sorted({round(self.model.width_dim(w) / cfg.n_embd, 4)\n                         for w in list(cfg.widths) + [0.125, 0.25, 0.5, 0.75, 1.0]})\n        layers = sorted({max(1, int(cfg.n_layer * f)) for f in (0.25, 0.5, 0.75, 1.0)})\n        out = [(w, l) for w in widths for l in layers if w > 0]\n        out.sort(key=lambda wl: self.model.active_params(wl[0], wl[1]))\n        return out\n\n    def weight_bytes(self, width: float, n_layers: int) -> int:\n        return int(self.model.active_params(width, n_layers) * self.bits / 8)\n\n    # --------------------------------------------------------------- решение\n    def plan(self, state: DeviceState, task_complexity: float = 0.5,\n             latency_ms: Optional[float] = None) -> Plan:\n        """Подобрать конфигурацию под память, батарею, температуру и задачу.\n\n        task_complexity: 0 = тривиально (включить свет), 1 = сложно (анализ).\n        """\n        budget = state.available_bytes\n        throttle = state.throttle\n        complexity = float(np.clip(task_complexity, 0.0, 1.0))\n\n        fitting = [(w, l) for (w, l) in self.candidates\n                   if self.weight_bytes(w, l) <= budget]\n\n        if not fitting:\n            w, l = self.candidates[0]\n            return Plan(w, l, self.model.active_params(w, l), self.weight_bytes(w, l),\n                        0.5, f"не влезает даже минимум ({budget / 1024:.0f} КБ бюджет)", fits=False)\n\n        # верхняя граница: throttle и сложность задачи ограничивают долю от максимума\n        ceiling = max(1, int(len(fitting) * min(1.0, throttle * (0.45 + 0.55 * complexity)) + 0.5))\n        w, l = fitting[ceiling - 1]\n\n        reasons = []\n        if ceiling < len(fitting):\n            if throttle < 1.0:\n                reasons.append(f"throttle {throttle:.2f}")\n            if complexity < 0.9:\n                reasons.append(f"задача {complexity:.2f}")\n        else:\n            reasons.append("максимум для устройства")\n        if len(fitting) < len(self.candidates):\n            reasons.append(f"лимит памяти {budget / 1024:.0f} КБ")\n\n        # простые задачи выходят раньше\n        threshold = float(np.clip(0.55 + 0.4 * complexity, 0.5, 0.97))\n        return Plan(w, l, self.model.active_params(w, l), self.weight_bytes(w, l),\n                    threshold, ", ".join(reasons) or "по умолчанию")\n\n    def explain(self, state: DeviceState, task_complexity: float = 0.5) -> str:\n        p = self.plan(state, task_complexity)\n        total = self.model.num_params()\n        frac = p.active_params / max(total, 1) * 100\n        return (f"{state}\\n  -> {p}\\n"\n                f"  -> активно {frac:.1f}% от полной модели ({total:,} параметров)")\n\n\n# ═══════════════════════════════════ RL-мета-контроллер (награда из спеки)\n@dataclass\nclass Experience:\n    """Один шаг: состояние, выбранное действие, полученная награда."""\n\n    state: Tuple[float, ...]\n    action: int\n    reward: float\n\n\nclass RLMetaController:\n    """Мета-контроллер, обучающийся на награде  качество − λ·задержка − μ·энергия.\n\n    Политика — линейный softmax по признакам состояния (батарея, температура,\n    свободная память, сложность задачи). Обучение — REINFORCE с baseline:\n\n        L = -E[log π(a|s) · A(s, a)],   A = R - b\n\n    Это ровно та формула, что заявлена в спецификации.\n    """\n\n    #: веса награды: сколько стоят задержка и энергия относительно качества\n    LAMBDA_LATENCY = 0.35\n    MU_ENERGY = 0.25\n\n    def __init__(self, model: MatFormer, lam: float = LAMBDA_LATENCY,\n                 mu: float = MU_ENERGY, lr: float = 0.05, seed: int = 0) -> None:\n        self.base = MetaController(model)\n        self.model = model\n        self.lam, self.mu, self.lr = lam, mu, lr\n        self.actions = self.base.candidates           # (width, n_layers)\n        self.n_features = 5\n        self.rng = np.random.default_rng(seed)\n        # Политика линейна по признакам ПАРЫ (состояние, действие).\n        # Таблица θ[признак, действие] не работала: действия (width, layers)\n        # не упорядочены, и линейная по состоянию модель не могла выразить\n        # оптимум. Здесь действие описано своей стоимостью — политика\n        # научается сопоставлять «сколько ресурса» и «сколько его есть».\n        self.n_pair = 11\n        self.theta = np.zeros(self.n_pair, dtype=np.float64)\n        self.baseline = 0.0\n        self.temperature = 1.0\n        self.history: List[Experience] = []\n\n    # ------------------------------------------------------------ признаки\n    def features(self, state: DeviceState, complexity: float) -> np.ndarray:\n        return np.array([\n            1.0,\n            state.battery_pct / 100.0,\n            min(state.temperature_c, 100.0) / 100.0,\n            float(np.clip(state.available_bytes / max(state.device.weight_budget, 1), 0, 1)),\n            float(np.clip(complexity, 0.0, 1.0)),\n        ], dtype=np.float64)\n\n    def action_features(self, action: int, state: DeviceState,\n                        complexity: float) -> np.ndarray:\n        """φ(s, a): стоимость действия в контексте состояния."""\n        w, layers = self.actions[action]\n        params = self.model.active_params(w, layers)\n        biggest = max(self.model.active_params(1.0, self.model.cfg.n_layer), 1)\n        frac = params / biggest\n        budget_use = self.base.weight_bytes(w, layers) / max(state.available_bytes, 1)\n        thr = state.throttle\n        bat = state.battery_pct / 100.0\n        root = math.sqrt(frac)          # качество в награде растёт как √frac\n        return np.array([\n            root,                       # выигрыш в качестве\n            root * complexity,          # качество там, где задача сложная\n            root * thr,                 # качество, когда железо позволяет\n            frac,                       # сколько ресурса берём\n            frac * frac,                # нелинейная цена\n            frac * complexity,          # ресурс под сложную задачу\n            frac * thr,                 # ресурс, когда железо не душит\n            frac * bat,                 # ресурс при заряде\n            frac / max(thr, 0.05),      # штраф за задержку при троттлинге\n            min(budget_use, 2.0),       # заполнение бюджета памяти\n            float(layers) / max(self.model.cfg.n_layer, 1),   # глубина\n        ], dtype=np.float64)\n\n    def _all_action_features(self, state: DeviceState, complexity: float) -> np.ndarray:\n        return np.stack([self.action_features(i, state, complexity)\n                         for i in range(len(self.actions))])\n\n    def policy(self, state: DeviceState, complexity: float) -> np.ndarray:\n        """π(a|s) — распределение по конфигурациям."""\n        logits = (self._all_action_features(state, complexity) @ self.theta) / self.temperature\n        # недопустимые действия (не влезают в память) исключаются жёстко\n        mask = np.array([self.base.weight_bytes(w, l) <= state.available_bytes\n                         for w, l in self.actions], dtype=bool)\n        if not mask.any():\n            mask[0] = True\n        logits = np.where(mask, logits, -1e9)\n        z = logits - logits.max()\n        p = np.exp(z)\n        return p / p.sum()\n\n    # -------------------------------------------------------------- награда\n    def reward(self, action: int, state: DeviceState, complexity: float) -> float:\n        """качество − λ·задержка − μ·энергия, всё в долях 0..1."""\n        w, layers = self.actions[action]\n        params = self.model.active_params(w, layers)\n        biggest = self.model.active_params(1.0, self.model.cfg.n_layer)\n        frac = params / max(biggest, 1)\n\n        # качество растёт с размером, но насыщается; сложной задаче нужен размер\n        quality = float(np.sqrt(frac)) * (0.45 + 0.55 * complexity)\n        # задержка и энергия линейны по активным параметрам и падают от throttle\n        latency = frac / max(state.throttle, 0.05)\n        energy = frac * (2.0 - state.battery_pct / 100.0)\n        return float(quality - self.lam * latency - self.mu * energy)\n\n    # ------------------------------------------------------------- действие\n    def act(self, state: DeviceState, complexity: float,\n            explore: bool = True) -> int:\n        p = self.policy(state, complexity)\n        if explore:\n            return int(self.rng.choice(len(p), p=p))\n        return int(p.argmax())\n\n    def plan(self, state: DeviceState, complexity: float = 0.5) -> Plan:\n        """Готовый план по выученной политике (без исследования)."""\n        a = self.act(state, complexity, explore=False)\n        w, layers = self.actions[a]\n        threshold = float(np.clip(0.55 + 0.4 * complexity, 0.5, 0.97))\n        return Plan(w, layers, self.model.active_params(w, layers),\n                    self.base.weight_bytes(w, layers), threshold,\n                    f"RL-политика (награда {self.reward(a, state, complexity):+.3f})")\n\n    # ------------------------------------------------------------- обучение\n    def train_step(self, state: DeviceState, complexity: float) -> float:\n        """Один шаг REINFORCE с ТОЧНЫМ per-state baseline.\n\n        Скользящее среднее по всем состояниям в качестве baseline давало\n        вырожденную политику: «хорошая» награда на ноутбуке выглядела\n        отличной на фоне часов, и градиент тянул все состояния к одному\n        действию. Здесь baseline = E_π[r | s] считается честно для текущего\n        состояния — advantage становится сравнением действий между собой.\n        """\n        phi = self._all_action_features(state, complexity)\n        p = self.policy(state, complexity)\n        rewards = np.array([self.reward(i, state, complexity)\n                            for i in range(len(p))], dtype=np.float64)\n        a = int(self.rng.choice(len(p), p=p))\n        r = float(rewards[a])\n\n        baseline = float(np.dot(p, rewards))       # ожидаемая награда в ЭТОМ состоянии\n        self.baseline = 0.95 * self.baseline + 0.05 * r\n        advantage = r - baseline\n\n        # ∇ log π(a|s) = φ(s,a) − E_π[φ(s,·)]\n        grad = phi[a] - p @ phi\n        self.theta += self.lr * advantage * grad\n        self.history.append(Experience(tuple(self.features(state, complexity)), a, r))\n        return r\n\n    def train(self, states: Sequence[DeviceState], steps: int = 400,\n              complexities: Sequence[float] = (0.1, 0.5, 0.9)) -> List[float]:\n        """Обучение на наборе ситуаций. Возвращает историю наград."""\n        out: List[float] = []\n        lr0 = self.lr\n        for i in range(steps):\n            st = states[i % len(states)]\n            cx = complexities[i % len(complexities)]\n            # отжиг: сначала широкое исследование, к концу — уверенный выбор\n            frac_done = i / max(steps - 1, 1)\n            # отжиг: сначала широкое исследование, к концу — уверенный выбор\n            self.temperature = max(0.05, 1.0 - 0.95 * frac_done)\n            # затухание шага: крупные правки вначале, тонкая настройка в конце\n            self.lr = lr0 * (1.0 - 0.9 * frac_done)\n            out.append(self.train_step(st, cx))\n        self.temperature = 0.05\n        self.lr = lr0\n        return out\n\n    def mean_reward(self, states: Sequence[DeviceState],\n                    complexities: Sequence[float] = (0.1, 0.5, 0.9),\n                    greedy: bool = True) -> float:\n        """Средняя награда текущей политики — метрика качества обучения."""\n        vals = []\n        for st in states:\n            for cx in complexities:\n                a = self.act(st, cx, explore=not greedy)\n                vals.append(self.reward(a, st, cx))\n        return float(np.mean(vals))\n\n    def baseline_reward(self, states: Sequence[DeviceState],\n                        complexities: Sequence[float] = (0.1, 0.5, 0.9)) -> float:\n        """Награда эвристического MetaController — честный конкурент."""\n        vals = []\n        for st in states:\n            for cx in complexities:\n                plan = self.base.plan(st, cx)\n                key = (plan.width, plan.n_layers)\n                a = self.actions.index(key) if key in self.actions else 0\n                vals.append(self.reward(a, st, cx))\n        return float(np.mean(vals))\n'

_SOURCES['ultranet.proteus.core'] = '"""Proteus — единый фасад: один объект, живущий на любом железе.\n\nСобирает вместе байтовый вход, вложенную модель, мета-контроллер,\nлокальную память и рой. Это реализация цикла из Части 2 спецификации:\nприём -> профилирование -> сборка -> мышление -> память -> ранний выход -> ответ.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\nfrom ..tensor import no_grad\nfrom .adapt import Feedback, PersonalAdapter\nfrom .bytes import ByteTokenizer\nfrom .assembly import Assembly, ProteusBody\nfrom .capsules import CapsuleRegistry\nfrom .controller import MetaController, Plan\nfrom .devices import Device, DeviceState, get_device\nfrom .matformer import MatConfig, MatFormer\nfrom .memory import LocalMemory\nfrom .quant import TernaryModel\nfrom .shards import ShardedSwarm\nfrom .steering import SteeringLibrary\nfrom .swarm import Swarm\n\n\n@dataclass\nclass Response:\n    """Результат одного запроса — со всей телеметрией «как думал»."""\n\n    text: str\n    plan: Plan\n    layers_used: int\n    context_used: str = ""\n    swarm_hops: int = 0\n    stayed_local: bool = True\n    steering: str = ""\n    experts_active: Optional[int] = None\n    capsules_active: float = 1.0\n    adapter_applied: bool = False\n\n    def __str__(self) -> str:\n        return self.text\n\n    def trace(self) -> str:\n        lines = [\n            f"  план      : {self.plan}",\n            f"  слоёв     : {self.layers_used}",\n            f"  локально  : {\'да\' if self.stayed_local else \'НЕТ\'}",\n        ]\n        if self.context_used:\n            lines.append(f"  из памяти : {self.context_used[:60]}...")\n        if self.steering:\n            lines.append(f"  вектор    : {self.steering}")\n        if self.experts_active is not None:\n            lines.append(f"  экспертов : {self.experts_active}")\n        if self.capsules_active < 1.0:\n            lines.append(f"  капсул    : {self.capsules_active * 100:.0f}% активно")\n        if self.adapter_applied:\n            lines.append(f"  адаптер   : LoRA применён")\n        if self.swarm_hops:\n            lines.append(f"  прыжков   : {self.swarm_hops}")\n        return "\\n".join(lines)\n\n\nclass Proteus:\n    """Один Протей: байтовый вход, вложенная модель, адаптация под железо.\n\n    >>> p = Proteus.tiny()\n    >>> p.attach("phone")\n    >>> r = p.respond("привет", max_new_tokens=8)\n    >>> r.stayed_local\n    True\n    """\n\n    def __init__(self, model: Optional[MatFormer] = None,\n                 memory: Optional[LocalMemory] = None,\n                 device: str | Device = "phone") -> None:\n        self.tok = ByteTokenizer()\n        self.model = model or MatFormer(MatConfig())\n        self.memory = memory or LocalMemory()\n        self.controller = MetaController(self.model)\n        self.state = DeviceState(get_device(device) if isinstance(device, str) else device)\n        self.swarm: Optional[Swarm] = None\n        self.sharded: Optional[ShardedSwarm] = None\n        self.cloud_enabled = False        # по умолчанию — никогда\n        self.steering = SteeringLibrary(self.model)\n        self.adapter: Optional[PersonalAdapter] = None\n        self.capsules: Optional[CapsuleRegistry] = None\n        self.task_vectors: Dict[str, str] = {}   # тип задачи -> имя steering-вектора\n        self.body = ProteusBody(self.state.device, self.state)  # каталог 48 капсул\n\n    # ------------------------------------------------------------ конструкторы\n    @classmethod\n    def tiny(cls, **kw) -> "Proteus":\n        """Маленький Протей для тестов и микроконтроллеров."""\n        cfg = MatConfig(n_layer=4, n_embd=96, head_dim=32, block_size=48,\n                        widths=(0.33, 0.67, 1.0), exit_layers=(1,))\n        return cls(MatFormer(cfg), **kw)\n\n    @classmethod\n    def standard(cls, **kw) -> "Proteus":\n        cfg = MatConfig(n_layer=8, n_embd=256, head_dim=32, block_size=128,\n                        widths=(0.25, 0.5, 1.0), exit_layers=(2, 5))\n        return cls(MatFormer(cfg), **kw)\n\n    @classmethod\n    def with_experts(cls, n_experts: int = 4, top_k: int = 2, **kw) -> "Proteus":\n        """Протей с MoE: разные эксперты для разных задач."""\n        cfg = MatConfig(n_layer=4, n_embd=128, head_dim=32, block_size=64,\n                        widths=(0.25, 0.5, 1.0), exit_layers=(1,),\n                        n_experts=n_experts, top_k_experts=top_k)\n        return cls(MatFormer(cfg), **kw)\n\n    # ------------------------------------------------------------ подсистемы\n    def enable_adapter(self, rank: int = 4) -> PersonalAdapter:\n        """Включить персонализацию (LoRA поверх замороженного ядра)."""\n        self.adapter = PersonalAdapter(self.model, rank=rank)\n        return self.adapter\n\n    def plan_capsules(self, prompt: str) -> Assembly:\n        """Какие из 48 капсул каталога нужны этому запросу на этом железе."""\n        return self.body.assemble(prompt)\n\n    def enable_capsules(self, skills_by_expert: Optional[Dict[int, set]] = None\n                        ) -> CapsuleRegistry:\n        self.capsules = CapsuleRegistry.from_model(self.model, skills_by_expert)\n        return self.capsules\n\n    def bind_vector(self, task: str, vector_name: str) -> None:\n        """Связать тип задачи со steering-вектором."""\n        self.task_vectors[task] = vector_name\n\n    @staticmethod\n    def classify_task(prompt: str) -> str:\n        """Первые слои — классификатор задачи (из спецификации, часть 2)."""\n        p = prompt.lower()\n        if any(k in p for k in ("код", "функци", "def ", "class ", "code", "напиши программ")):\n            return "код"\n        if any(k in p for k in ("стих", "поэм", "придумай", "сочини", "poem")):\n            return "творчество"\n        if any(k in p for k in ("посчитай", "сколько будет", "реши", "уравнен", "+", "=")):\n            return "математика"\n        if any(k in p for k in ("почему", "объясни", "проанализируй", "разбер", "why", "explain")):\n            return "рассуждение"\n        return "диалог"\n\n    # ------------------------------------------------------------- устройства\n    def attach(self, device: str | Device, **state_kw) -> "Proteus":\n        """Переехать на устройство (или описать его текущее состояние)."""\n        dev = get_device(device) if isinstance(device, str) else device\n        self.state = DeviceState(dev, **state_kw)\n        return self\n\n    def form_swarm(self, devices: Sequence[str], width: float = 1.0) -> Swarm:\n        """Собрать рой из нескольких устройств."""\n        states = [DeviceState(get_device(d)) for d in devices]\n        self.swarm = Swarm(self.model, states, width=width)\n        return self.swarm\n\n    def form_sharded_swarm(self, devices: Sequence[str],\n                           skills_by_layer: Optional[Dict[int, set]] = None,\n                           width: float = 1.0) -> ShardedSwarm:\n        """Рой с шардами, консенсусом и выбором роутера без лидера."""\n        states = [DeviceState(get_device(d)) for d in devices]\n        self.sharded = ShardedSwarm(self.model, states, width=width,\n                                    skills_by_layer=skills_by_layer)\n        return self.sharded\n\n    def dissolve_swarm(self) -> None:\n        self.swarm = None\n        self.sharded = None\n\n    # ------------------------------------------------------------ обратная связь\n    def feedback(self, prompt: str, reward: float = 1.0) -> None:\n        """Лайк/правка/игнор — сигнал для средней петли адаптации."""\n        if self.adapter is None:\n            self.enable_adapter()\n        self.adapter.observe(Feedback(self.tok.encode(prompt), reward=reward))\n\n    def consolidate(self, steps: int = 20, **kw) -> Dict[str, List[float]]:\n        """Средняя петля: дообучить LoRA на накопленных сигналах."""\n        if self.adapter is None:\n            return {"loss": []}\n        return self.adapter.consolidate(steps=steps, **kw)\n\n    # ------------------------------------------------------------------ знание\n    def remember(self, *facts: str) -> None:\n        """Положить знание в локальную память (вне весов)."""\n        for f in facts:\n            self.memory.add(f)\n\n    # ---------------------------------------------------------------- ответ\n    @no_grad()\n    def respond(self, prompt: str, max_new_tokens: int = 48,\n                task_complexity: Optional[float] = None,\n                temperature: float = 0.7, top_k: int = 40,\n                use_memory: bool = True, seed: Optional[int] = None) -> Response:\n        """Полный цикл: профилирование -> план -> (память) -> генерация."""\n        complexity = self.estimate_complexity(prompt) if task_complexity is None else task_complexity\n        task = self.classify_task(prompt)\n        plan = self.controller.plan(self.state, complexity)\n\n        # мета-контроллер крутит число экспертов: простая задача — меньше\n        experts_active = None\n        if self.model.cfg.n_experts > 1:\n            experts_active = int(np.clip(\n                round(1 + (self.model.cfg.n_experts - 1) * complexity),\n                1, self.model.cfg.n_experts))\n            self.model.set_active_experts(experts_active)\n\n        # капсулы: просыпаются только нужные\n        capsule_frac = 1.0\n        if self.capsules is not None:\n            self.capsules.assemble([task])\n            capsule_frac = self.capsules.active_fraction()\n\n        # steering: направление мышления под тип задачи\n        steer_name = self.task_vectors.get(task, "")\n        if steer_name and steer_name in self.steering:\n            self.steering.apply(steer_name)\n\n        context = ""\n        if use_memory and len(self.memory):\n            context = self.memory.context_for(prompt, top_k=2, max_chars=200)\n\n        full = f"{context}\\n{prompt}" if context else prompt\n        ids = self.tok.encode(full)[-self.model.cfg.block_size:]\n        if not ids:\n            ids = [self.tok.bos_id]\n\n        if self.swarm is not None:\n            logits = self.swarm.forward(np.array([ids]))\n            out_ids = self._sample_loop(ids, plan, max_new_tokens, temperature, top_k, seed)\n            hops = self.swarm.hops\n        else:\n            out_ids = self._sample_loop(ids, plan, max_new_tokens, temperature, top_k, seed)\n            hops = 0\n\n        text = self.tok.decode(out_ids[len(ids):])\n        if steer_name:\n            self.steering.clear()\n        self.model.set_active_experts(None)\n\n        # быстрая петля: запоминаем взаимодействие для будущей консолидации\n        if self.adapter is not None:\n            self.adapter.observe(Feedback(self.tok.encode(full), reward=0.0, tag=task))\n\n        return Response(text=text, plan=plan, layers_used=plan.n_layers,\n                        context_used=context, swarm_hops=hops,\n                        stayed_local=not self.cloud_enabled,\n                        steering=steer_name, experts_active=experts_active,\n                        capsules_active=capsule_frac,\n                        adapter_applied=self.adapter is not None)\n\n    def _sample_loop(self, ids: List[int], plan: Plan, n: int,\n                     temperature: float, top_k: int, seed: Optional[int]) -> List[int]:\n        return self.model.generate(ids, max_new_tokens=n, width=plan.width,\n                                   temperature=temperature, top_k=top_k,\n                                   n_layers=plan.n_layers, seed=seed)\n\n    @staticmethod\n    def estimate_complexity(prompt: str) -> float:\n        """Грубая оценка сложности запроса: команда или размышление."""\n        p = prompt.lower().strip()\n        simple_markers = ("включи", "выключи", "открой", "закрой", "стоп", "да", "нет",\n                          "on", "off", "open", "close", "yes", "no")\n        if any(p.startswith(m) for m in simple_markers) or len(p) < 12:\n            return 0.15\n        hard_markers = ("почему", "объясни", "проанализируй", "докажи", "напиши код",\n                        "why", "explain", "analyze", "prove")\n        if any(m in p for m in hard_markers) or len(p) > 120:\n            return 0.95\n        return 0.5\n\n    # --------------------------------------------------------------- отчёты\n    def footprint(self) -> str:\n        """Сколько Протей весит на текущем устройстве."""\n        q = TernaryModel(self.model)\n        plan = self.controller.plan(self.state, 1.0)\n        return (f"{self.state}\\n"\n                f"  полная модель : {q.stats}\\n"\n                f"  активная часть: {plan.active_params:,} параметров "\n                f"({plan.weight_bytes / 1024:.0f} КБ)\\n"\n                f"  память знаний : {self.memory.size_bytes() / 1024:.1f} КБ "\n                f"({len(self.memory)} фактов, вне весов)")\n\n    def device_matrix(self, devices: Optional[Sequence[str]] = None,\n                      task_complexity: float = 0.8) -> str:\n        """Таблица: как Протей выглядит на разных устройствах."""\n        keys = list(devices or ["smartcard", "esp32", "ring", "earbuds", "smartwatch",\n                                "phone", "laptop", "workstation", "server"])\n        rows = [f"{\'устройство\':<22} {\'RAM\':>9} {\'активно\':>12} {\'вес\':>10} {\'слоёв\':>6}"]\n        rows.append("-" * 64)\n        for k in keys:\n            dev = get_device(k)\n            plan = self.controller.plan(DeviceState(dev), task_complexity)\n            ram = (f"{dev.ram_bytes / 1024**3:.0f}ГБ" if dev.ram_bytes >= 1024**3\n                   else f"{dev.ram_bytes / 1024**2:.0f}МБ" if dev.ram_bytes >= 1024**2\n                   else f"{dev.ram_bytes / 1024:.0f}КБ")\n            w = (f"{plan.weight_bytes / 1024**2:.1f}МБ" if plan.weight_bytes >= 1024**2\n                 else f"{plan.weight_bytes / 1024:.0f}КБ")\n            mark = "" if plan.fits else "  (не влезает!)"\n            rows.append(f"{dev.name:<22} {ram:>9} {plan.active_params:>12,} {w:>10} "\n                        f"{plan.n_layers:>6}{mark}")\n        return "\\n".join(rows)\n'

_SOURCES['ultranet.proteus.devices'] = '"""Профили устройств — от ESP32 до датацентра.\n\nЧисла взяты из спецификации Протея (Часть 3) и используются мета-контроллером\nдля подбора конфигурации. Бюджет памяти — реальный ограничитель: если\nупакованная модель не влезает, конфигурация отвергается.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional\n\nKB = 1024\nMB = 1024 * KB\nGB = 1024 * MB\n\n\n@dataclass\nclass Device:\n    """Описание железа."""\n\n    name: str\n    tier: str                 # micro | small | medium | large | datacenter\n    ram_bytes: int\n    ram_for_model: float = 0.35     # какую долю RAM можно отдать весам\n    gflops: float = 0.1             # грубая оценка вычислительной мощности\n    battery: bool = True\n    always_on: bool = False\n\n    @property\n    def weight_budget(self) -> int:\n        return int(self.ram_bytes * self.ram_for_model)\n\n    def __str__(self) -> str:\n        r = self.ram_bytes\n        h = f"{r / GB:.0f} ГБ" if r >= GB else (f"{r / MB:.0f} МБ" if r >= MB else f"{r / KB:.0f} КБ")\n        return f"{self.name} [{self.tier}, RAM {h}]"\n\n\n# ------------------------------------------------------------------ каталог\nDEVICES: Dict[str, Device] = {\n    # микроуровень\n    "esp32":        Device("ESP32", "micro", 520 * KB, 0.45, 0.001, True, True),\n    "stm32":        Device("STM32", "micro", 256 * KB, 0.45, 0.0005, True, True),\n    "rp2040":       Device("RP2040", "micro", 264 * KB, 0.45, 0.0005, True, True),\n    "smartcard":    Device("Смарт-карта", "micro", 32 * KB, 0.5, 0.0001, False, True),\n    "implant":      Device("Имплантат", "micro", 128 * KB, 0.4, 0.0002, True, True),\n    # малый\n    "earbuds":      Device("Наушники", "small", 256 * MB, 0.25, 0.05, True, True),\n    "smartwatch":   Device("Умные часы", "small", 2 * GB, 0.25, 0.3, True, True),\n    "glasses":      Device("Умные очки", "small", 4 * GB, 0.3, 0.5, True, True),\n    "ring":         Device("Умное кольцо", "small", 64 * MB, 0.25, 0.01, True, True),\n    "speaker":      Device("Умная колонка", "small", 1 * GB, 0.4, 0.2, False, True),\n    "drone":        Device("Дрон", "small", 512 * MB, 0.3, 0.3, True, False),\n    # средний\n    "phone":        Device("Смартфон", "medium", 8 * GB, 0.35, 2.0, True, True),\n    "phone_hi":     Device("Смартфон (флагман)", "medium", 16 * GB, 0.4, 4.0, True, True),\n    "tablet":       Device("Планшет", "medium", 8 * GB, 0.4, 2.5, True, False),\n    "laptop":       Device("Ноутбук", "medium", 32 * GB, 0.5, 8.0, True, False),\n    "console":      Device("Игровая консоль", "medium", 16 * GB, 0.5, 10.0, False, False),\n    "car":          Device("Автомобиль", "medium", 16 * GB, 0.5, 6.0, False, True),\n    "tv":           Device("Smart TV", "medium", 4 * GB, 0.4, 1.0, False, True),\n    # большой\n    "workstation":  Device("Рабочая станция", "large", 128 * GB, 0.6, 50.0, False, False),\n    "server":       Device("Сервер", "datacenter", 512 * GB, 0.7, 200.0, False, True),\n    "cluster":      Device("Кластер", "datacenter", 4096 * GB, 0.8, 2000.0, False, True),\n}\n\n\n@dataclass\nclass DeviceState:\n    """Мгновенное состояние устройства — меняется между запросами."""\n\n    device: Device\n    battery_pct: float = 100.0\n    temperature_c: float = 35.0\n    ram_free_frac: float = 1.0        # доля бюджета, реально доступная сейчас\n    latency_budget_ms: float = 1000.0\n\n    @property\n    def available_bytes(self) -> int:\n        return int(self.device.weight_budget * max(self.ram_free_frac, 0.0))\n\n    @property\n    def throttle(self) -> float:\n        """Коэффициент 0..1: насколько урезать вычисления.\n\n        Низкий заряд и перегрев заставляют Протея сжиматься.\n        """\n        f = 1.0\n        if self.device.battery:\n            if self.battery_pct < 10:\n                f *= 0.25\n            elif self.battery_pct < 20:\n                f *= 0.4\n            elif self.battery_pct < 50:\n                f *= 0.75\n        if self.temperature_c > 80:\n            f *= 0.3\n        elif self.temperature_c > 65:\n            f *= 0.6\n        return f\n\n    def __str__(self) -> str:\n        return (f"{self.device} батарея {self.battery_pct:.0f}% "\n                f"t={self.temperature_c:.0f}°C throttle={self.throttle:.2f}")\n\n\ndef get_device(key: str) -> Device:\n    if key not in DEVICES:\n        raise KeyError(f"неизвестное устройство \'{key}\'. Доступны: {\', \'.join(sorted(DEVICES))}")\n    return DEVICES[key]\n\n\ndef list_devices(tier: Optional[str] = None) -> List[Device]:\n    return [d for d in DEVICES.values() if tier is None or d.tier == tier]\n'

_SOURCES['ultranet.proteus.experts'] = '"""MoE: специализированные эксперты и роутер.\n\n«Активны разные 10% для разных задач. Просишь код — работают одни.\nПросишь стихи — другие». Роутер — маленькая сеть, которая решает,\nкаких экспертов включить.\n"""\nfrom __future__ import annotations\n\nimport math\nfrom typing import Dict, List, Optional, Tuple\n\nimport numpy as np\n\nfrom .. import nn\nfrom ..nn import Parameter\nfrom ..tensor import Tensor, get_rng\n\n\ndef _round_to(d: int, mult: int) -> int:\n    return max(mult, int(round(d / mult)) * mult)\n\n\nclass Expert(nn.Module):\n    """Один эксперт — SwiGLU-блок с эластичной шириной."""\n\n    def __init__(self, dim: int, hidden: int) -> None:\n        super().__init__()\n        from .matformer import ElasticLinear\n\n        self.dim, self.hidden = dim, hidden\n        self.w_gate = ElasticLinear(dim, hidden)\n        self.w_up = ElasticLinear(dim, hidden)\n        self.w_down = ElasticLinear(hidden, dim)\n\n    def forward(self, x: Tensor, d_act: int) -> Tensor:\n        h_act = _round_to(self.hidden * d_act // self.dim, 8)\n        gated = self.w_gate(x, d_act, h_act).silu() * self.w_up(x, d_act, h_act)\n        return self.w_down(gated, h_act, d_act)\n\n    def active_params(self, d_act: int) -> int:\n        h_act = _round_to(self.hidden * d_act // self.dim, 8)\n        return 3 * d_act * h_act\n\n\nclass MoE(nn.Module):\n    """Смесь экспертов с top-k роутингом.\n\n    Роутер обучается предсказывать, какой эксперт даст лучший ответ.\n    Вспомогательный loss балансирует нагрузку, иначе роутер схлопывается\n    в одного «любимого» эксперта.\n\n    >>> moe = MoE(64, n_experts=4, top_k=2)\n    >>> y = moe(Tensor(np.random.randn(2, 5, 64)), d_act=64)\n    """\n\n    def __init__(self, dim: int, n_experts: int = 4, top_k: int = 2,\n                 mlp_ratio: int = 4) -> None:\n        super().__init__()\n        assert 1 <= top_k <= n_experts, "top_k должен быть в [1, n_experts]"\n        self.dim, self.n_experts, self.top_k = dim, n_experts, top_k\n        hidden = mlp_ratio * dim\n        self.experts = [Expert(dim, hidden) for _ in range(n_experts)]\n        for i, e in enumerate(self.experts):\n            self._modules[f"expert{i}"] = e\n        # роутер — маленькая матрица dim -> n_experts\n        self.router = Parameter(\n            get_rng().standard_normal((dim, n_experts)).astype(np.float32) * 0.02\n        )\n        self.last_load: Optional[np.ndarray] = None\n        self.last_aux: float = 0.0\n        self._forced: Optional[List[int]] = None\n\n    # ------------------------------------------------------------ управление\n    def force_experts(self, idx: Optional[List[int]]) -> None:\n        """Принудительно активировать конкретных экспертов (для отладки/капсул)."""\n        self._forced = idx\n\n    def route(self, x: Tensor, d_act: int) -> np.ndarray:\n        """Распределение по экспертам (без вычисления самих экспертов)."""\n        logits = (x @ self.router[:d_act]).data\n        z = logits - logits.max(-1, keepdims=True)\n        p = np.exp(z)\n        return p / p.sum(-1, keepdims=True)\n\n    # --------------------------------------------------------------- forward\n    def forward(self, x: Tensor, d_act: int, n_active: Optional[int] = None,\n                force: Optional[List[int]] = None) -> Tensor:\n        """force — временно активировать конкретных экспертов (капсулы/отладка)."""\n        if force is not None:\n            self._forced = list(force)\n        k = int(np.clip(n_active or self.top_k, 1, self.n_experts))\n        gate_logits = x @ self.router[:d_act]              # (B,T,E)\n        probs = gate_logits.softmax(axis=-1)\n        pd = probs.data\n        b, t, _ = pd.shape\n\n        if self._forced is not None:\n            chosen = np.tile(np.array(self._forced[:k], dtype=int), (b, t, 1))\n        else:\n            chosen = np.argsort(-pd, axis=-1)[..., :k]      # (B,T,k)\n\n        # нормируем веса выбранных экспертов\n        sel = np.take_along_axis(pd, chosen, axis=-1)\n        sel_norm = sel / np.clip(sel.sum(-1, keepdims=True), 1e-9, None)\n\n        # знаменатель нормировки top-k (константа для градиента — как в Switch/Mixtral)\n        denom = np.clip(sel.sum(-1, keepdims=True), 1e-9, None)   # (B,T,1)\n        out: Optional[Tensor] = None\n        load = np.zeros(self.n_experts, dtype=np.float64)\n        for e_idx in range(self.n_experts):\n            hit = (chosen == e_idx).any(-1)                  # (B,T) выбран ли эксперт\n            if not hit.any():\n                continue\n            load[e_idx] = float(hit.mean())\n            # вес = prob эксперта / сумму вероятностей выбранных; градиент идёт в роутер\n            keep = Tensor(hit[..., None].astype(np.float32))\n            gate = probs[:, :, e_idx:e_idx + 1] * keep / Tensor(denom.astype(np.float32))\n            contrib = self.experts[e_idx](x, d_act) * gate\n            out = contrib if out is None else out + contrib\n\n        self.last_load = load\n        # aux-loss: поощряем равномерную загрузку (Switch Transformer)\n        frac = load / max(load.sum(), 1e-9)\n        mean_p = pd.reshape(-1, self.n_experts).mean(0)\n        self.last_aux = float(self.n_experts * (frac * mean_p).sum())\n\n        if out is None:                                       # страховка\n            out = self.experts[0](x, d_act) * 0.0\n        return out\n\n    def aux_loss(self, x: Optional[Tensor] = None,\n                 d_act: Optional[int] = None):\n        """Балансирующий loss роутера.\n\n        С аргументами — дифференцируемый Tensor для обучения.\n        Без аргументов — число: дисбаланс последнего прогона (для отчётов).\n        """\n        if x is None:\n            load = self.last_load\n            if load is None or not len(load):\n                return 0.0\n            target = 1.0 / self.n_experts\n            return float(((load / max(load.sum(), 1e-9) - target) ** 2).sum()\n                         * self.n_experts)\n        probs = (x @ self.router[:d_act]).softmax(axis=-1)\n        mean_p = probs.mean(axis=(0, 1))\n        target = 1.0 / self.n_experts\n        return ((mean_p - target) ** 2).sum() * float(self.n_experts)\n\n    def active_params(self, d_act: int, n_active: Optional[int] = None) -> int:\n        k = int(np.clip(n_active or self.top_k, 1, self.n_experts))\n        return k * self.experts[0].active_params(d_act) + d_act * self.n_experts\n\n    def total_params(self, d_act: int) -> int:\n        return self.n_experts * self.experts[0].active_params(d_act) + d_act * self.n_experts\n\n    # ---------------------------------------------------------- специализация\n    def specialization(self, samples: Dict[str, np.ndarray], model, d_act: int,\n                       layer: int) -> Dict[str, np.ndarray]:\n        """Какие эксперты активируются на разных типах задач."""\n        out: Dict[str, np.ndarray] = {}\n        for name, ids in samples.items():\n            x = model.embed(ids, d_act)\n            for i in range(layer):\n                x = model.run_block(i, x, d_act)\n            h = model.norm_for_moe(x, layer, d_act)\n            p = self.route(h, d_act).reshape(-1, self.n_experts).mean(0)\n            out[name] = p\n        return out\n'

_SOURCES['ultranet.proteus.growth'] = '"""Путь Протея от 0% до 100%: автоматический рост под железо.\n\n«Протей не обновляется. Он растёт» — по мере использования, а не по расписанию.\n\nДевять стадий из спецификации: 0 (ничего) → 1 (зонд) → 5 (базовая сборка)\n→ 10 (знакомство) → 25 (локальный) → 50 (центр) → 75 (полный рой)\n→ 90 (персонализация) → 100 (ультимативная форма).\n\nРост считается не «по расписанию», а по пяти реальным осям:\n  железо (что зондировали) · использование (сколько запросов)\n  · знания (RAG) · персонализация (LoRA) · рой (сколько узлов).\n"""\nfrom __future__ import annotations\n\nimport math\nimport os\nimport platform\nimport shutil\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional, Sequence, Set, Tuple\n\nimport numpy as np\n\nfrom .catalog import BY_KEY, CATALOG, CapsuleSpec, Group, Stage\nfrom .devices import Device, DeviceState, get_device\n\nGB = 1024 ** 3\nMB = 1024 ** 2\n\n\n# ═══════════════════════════════════════════════════ 1%: зонд железа\n@dataclass\nclass HardwareProfile:\n    """Карта возможного: что железо реально потянет.\n\n    Строится капсулой профилирования на 1% — первой из всех.\n    """\n\n    name: str\n    cpu_count: int\n    ram_bytes: int\n    ram_available: int\n    disk_bytes: int\n    has_gpu: bool = False\n    battery: bool = True\n    tier: str = "medium"\n    machine: str = ""\n    system: str = ""\n\n    # ---------------------------------------------------------- вычисления\n    @property\n    def ram_gb(self) -> float:\n        return self.ram_bytes / GB\n\n    def weight_budget(self, frac: float = 0.35) -> int:\n        """Сколько байт можно отдать весам модели."""\n        return int(min(self.ram_available, self.ram_bytes * frac))\n\n    def max_params(self, bits: float = 2.0) -> int:\n        """Сколько параметров влезет при 1.58-битном квантовании."""\n        return int(self.weight_budget() * 8 / bits)\n\n    def tokens_per_sec(self) -> float:\n        """Грубая оценка скорости: ядра × частота-эквивалент."""\n        return max(1.0, self.cpu_count * 8.0 * (2.0 if self.has_gpu else 1.0))\n\n    def context_window(self) -> int:\n        """Какой контекст потянет память."""\n        for ctx in (128_000, 32_000, 8_000, 2_000, 512):\n            if self.ram_available > ctx * 2048:\n                return ctx\n        return 256\n\n    def as_device(self) -> Device:\n        """Превратить зонд в Device — дальше работает обычный конвейер."""\n        return Device(self.name, self.tier, self.ram_bytes, 0.35,\n                      self.cpu_count * (4.0 if self.has_gpu else 0.5),\n                      self.battery, False)\n\n    def report(self) -> str:\n        return (f"железо     : {self.name} [{self.tier}]\\n"\n                f"CPU        : {self.cpu_count} ядер"\n                + (", GPU есть" if self.has_gpu else ", GPU нет") + "\\n"\n                f"RAM        : {self.ram_gb:.1f} ГБ "\n                f"(свободно {self.ram_available / GB:.1f} ГБ)\\n"\n                f"диск       : {self.disk_bytes / GB:.0f} ГБ\\n"\n                f"бюджет     : {self.weight_budget() / MB:.0f} МБ весов "\n                f"= до {self.max_params() / 1e6:.0f}M параметров @1.58-bit\\n"\n                f"скорость   : ~{self.tokens_per_sec():.0f} ток/с, "\n                f"контекст {self.context_window():,}")\n\n\ndef probe_hardware(simulate: Optional[str] = None) -> HardwareProfile:\n    """Зонд железа. Реальный — или симуляция известного устройства.\n\n    Это первое, что делает Протей на 1%: «Анализирую устройство».\n    """\n    if simulate is not None:\n        d = get_device(simulate)\n        return HardwareProfile(\n            name=d.name, cpu_count=max(1, int(d.gflops) or 1),\n            ram_bytes=d.ram_bytes, ram_available=d.weight_budget,\n            disk_bytes=d.ram_bytes * 8, has_gpu=d.gflops >= 8.0,\n            battery=d.battery, tier=d.tier, machine="simulated",\n            system="simulated")\n\n    cpu = os.cpu_count() or 1\n    ram = _total_ram()\n    avail = _available_ram(ram)\n    try:\n        disk = shutil.disk_usage("/").total\n    except OSError:\n        disk = ram * 4\n    tier = _tier_for(ram)\n    return HardwareProfile(\n        name=platform.node() or "это устройство", cpu_count=cpu,\n        ram_bytes=ram, ram_available=avail, disk_bytes=disk,\n        has_gpu=_detect_gpu(), battery=_detect_battery(), tier=tier,\n        machine=platform.machine(), system=platform.system())\n\n\ndef _total_ram() -> int:\n    try:\n        return os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_PHYS_PAGES")\n    except (ValueError, OSError, AttributeError):\n        return 2 * GB\n\n\ndef _available_ram(total: int) -> int:\n    try:\n        with open("/proc/meminfo", "r", encoding="utf-8") as fh:\n            for line in fh:\n                if line.startswith("MemAvailable:"):\n                    return int(line.split()[1]) * 1024\n    except OSError:\n        pass\n    return int(total * 0.5)\n\n\ndef _detect_gpu() -> bool:\n    if shutil.which("nvidia-smi"):\n        return True\n    return any(os.path.exists(p) for p in ("/dev/nvidia0", "/dev/dri/card0"))\n\n\ndef _detect_battery() -> bool:\n    return os.path.isdir("/sys/class/power_supply/BAT0")\n\n\ndef _device_by_name(name: str) -> Optional[Device]:\n    """Найти Device по человеческому имени (узлы роя хранятся именами)."""\n    from .devices import DEVICES\n    for d in DEVICES.values():\n        if d.name == name:\n            return d\n    return None\n\n\ndef _tier_for(ram: int) -> str:\n    if ram < 1 * MB:\n        return "micro"\n    if ram < 2 * GB:\n        return "small"\n    if ram < 64 * GB:\n        return "medium"\n    if ram < 256 * GB:\n        return "large"\n    return "datacenter"\n\n\n# ═══════════════════════════════════════════════════ шкала стадий\n@dataclass(frozen=True)\nclass Stage_:\n    """Одна ступень пути 0→100%."""\n\n    pct: int\n    title: str\n    capsules: int\n    params: int\n    memory: str\n    can_do: str\n    user_says: str\n    hardware: str\n\n\nLADDER: Tuple[Stage_, ...] = (\n    Stage_(0, "Абсолютный ноль", 0, 0, "0",\n           "ничего: нет модели, нет весов, нет капсул", "«Что это?»",\n           "голое железо"),\n    Stage_(1, "Первый байт", 1, 100_000, "1 МБ",\n           "зондирует железо, строит карту возможного", "«Что это?»",\n           "одно устройство, минимум ресурсов"),\n    Stage_(5, "Базовая сборка", 7, 100_000_000, "50 МБ",\n           "простые вопросы, короткие ответы, один язык", "«Полезно»",\n           "одно устройство, минимум ресурсов"),\n    Stage_(10, "Первое знакомство", 12, 150_000_000, "80 МБ",\n           "простые задачи, слабая персонализация, 1–2 языка", "«Полезно»",\n           "одно устройство, средние ресурсы"),\n    Stage_(25, "Локальный Протей", 25, 1_000_000_000, "600 МБ",\n           "сложные задачи, персонализация, память, 5–10 языков", "«Я привык»",\n           "одно устройство, средние ресурсы"),\n    Stage_(50, "Центр цифровой жизни", 35, 3_000_000_000, "2 ГБ",\n           "рой из 2 узлов, эпизодическая память, 20+ языков",\n           "«Я не могу без него»", "два устройства, рой"),\n    Stage_(75, "Полный рой", 45, 7_000_000_000, "5 ГБ",\n           "6 узлов, все экспертизы, рефлексия, 50+ языков", "«Он знает меня»",\n           "4–6 устройств, полный рой"),\n    Stage_(90, "Ультимативная персонализация", 48, 14_000_000_000, "10 ГБ",\n           "предсказывает вопросы, 100+ языков, все модальности",\n           "«Он — часть меня»", "все устройства, включая IoT"),\n    Stage_(100, "Ультимативная форма", 48, 0, "всё железо",\n           "предел железа: слияние с пользователем", "«Он — часть меня»",\n           "все устройства + внешние GPU + кооперация"),\n)\n\n\ndef stage_at(pct: float) -> Stage_:\n    """Ближайшая достигнутая ступень."""\n    reached = [s for s in LADDER if s.pct <= pct]\n    return reached[-1] if reached else LADDER[0]\n\n\ndef next_stage(pct: float) -> Optional[Stage_]:\n    ahead = [s for s in LADDER if s.pct > pct]\n    return ahead[0] if ahead else None\n\n\n# ═══════════════════════════════════════════════════ счётчик роста\n@dataclass\nclass GrowthState:\n    """Что Протей накопил. Из этого считается процент."""\n\n    probed: bool = False\n    installed: bool = False\n    requests: int = 0\n    documents: int = 0\n    adapters: int = 0\n    vectors: int = 0\n    nodes: int = 1\n    reflections: int = 0\n    feedback: int = 0\n\n    #: цели «100%» по каждой оси — из спецификации\n    TARGET_REQUESTS = 2000\n    TARGET_DOCS = 1_000_000\n    TARGET_ADAPTERS = 200\n    TARGET_VECTORS = 500\n    TARGET_NODES = 6\n\n    @staticmethod\n    def _log_frac(value: float, target: float) -> float:\n        """Логарифмический прогресс: первые шаги дают больше, чем сотые."""\n        if value <= 0:\n            return 0.0\n        return float(np.clip(math.log1p(value) / math.log1p(target), 0.0, 1.0))\n\n    # ------------------------------------------------------------- оси\n    def axes(self) -> Dict[str, float]:\n        return {\n            "железо": 1.0 if self.probed else 0.0,\n            "использование": self._log_frac(self.requests, self.TARGET_REQUESTS),\n            "знания": self._log_frac(self.documents, self.TARGET_DOCS),\n            "персонализация": max(\n                self._log_frac(self.adapters, self.TARGET_ADAPTERS),\n                self._log_frac(self.vectors, self.TARGET_VECTORS)),\n            "рой": float(np.clip((self.nodes - 1) / (self.TARGET_NODES - 1), 0.0, 1.0)),\n        }\n\n    def percent(self) -> float:\n        """Итоговый процент роста 0..100."""\n        if not self.probed:\n            return 0.0\n        if not self.installed:\n            return 1.0\n        a = self.axes()\n        # железо — предусловие, а не ось роста: зонд уже учтён в базовых 5%.\n        # Растят Протея использование, знания, персонализация и рой.\n        w = {"использование": 0.32, "знания": 0.26,\n             "персонализация": 0.26, "рой": 0.16}\n        score = sum(a[k] * w[k] for k in w)\n        return float(np.clip(5.0 + score * 95.0, 5.0, 100.0))\n\n\n# ═══════════════════════════════════════════════════ живой организм\nclass GrowingProteus:\n    """Протей, который растёт сам: зондирует железо и разворачивается под него.\n\n    >>> p = GrowingProteus.install(simulate="phone")\n    >>> p.percent > 0\n    True\n    >>> p.use("напиши код", documents=10)\n    >>> p.add_node("laptop")\n    """\n\n    def __init__(self, profile: Optional[HardwareProfile] = None) -> None:\n        self.profile = profile\n        self.state = GrowthState(probed=profile is not None)\n        self.nodes: List[str] = []\n        self.history: List[Tuple[float, str]] = []\n        self._log(0.0, "Протея нет: голое железо")\n\n    # ------------------------------------------------------------- 0 → 1%\n    @classmethod\n    def bare(cls) -> "GrowingProteus":\n        """0%: ничего нет."""\n        return cls(None)\n\n    def probe(self, simulate: Optional[str] = None) -> HardwareProfile:\n        """1%: капсула профилирования просыпается первой."""\n        self.profile = probe_hardware(simulate)\n        self.state.probed = True\n        self._log(self.percent, f"зонд: {self.profile.name}, "\n                                f"{self.profile.ram_gb:.1f} ГБ, "\n                                f"до {self.profile.max_params() / 1e6:.0f}M параметров")\n        return self.profile\n\n    # ------------------------------------------------------------- 1 → 5%\n    def install(self) -> "GrowingProteus":\n        """5%: мета-контроллер собирает минимальную конфигурацию."""\n        if self.profile is None:\n            self.probe()\n        self.state.installed = True\n        self.nodes = [self.profile.name]\n        self.state.nodes = 1\n        self._log(self.percent, f"базовая сборка: {len(self.active_capsules())} капсул")\n        return self\n\n    @classmethod\n    def install_on(cls, simulate: Optional[str] = None) -> "GrowingProteus":\n        p = cls.bare()\n        p.probe(simulate)\n        return p.install()\n\n    # --------------------------------------------------------------- рост\n    def use(self, prompt: str = "", documents: int = 0, liked: bool = False,\n            requests: int = 1) -> None:\n        """«Каждый запрос → адаптеры, каждый документ → RAG»."""\n        if not self.state.installed:\n            self.install()\n        before = self.percent\n        self.state.requests += max(0, requests)\n        self.state.documents += max(0, documents)\n        if liked:\n            self.state.feedback += 1\n        # адаптеры и векторы копятся по мере использования\n        self.state.adapters = min(GrowthState.TARGET_ADAPTERS,\n                                  1 + self.state.requests // 10)\n        self.state.vectors = min(GrowthState.TARGET_VECTORS,\n                                 self.state.requests // 4)\n        self.state.reflections = self.state.requests // 25\n        after = self.percent\n        if int(after) > int(before):\n            self._log(after, f"вырос до {after:.0f}% — {self.stage.title}")\n\n    def add_node(self, device_key: str) -> None:\n        """«Каждое новое устройство → расширение роя»."""\n        if not self.state.installed:\n            self.install()\n        name = get_device(device_key).name\n        if name in self.nodes:\n            return\n        self.nodes.append(name)\n        self.state.nodes = len(self.nodes)\n        self._log(self.percent, f"в рой пришёл {name} ({self.state.nodes} узлов)")\n\n    def remove_node(self, name: str) -> None:\n        if name in self.nodes and len(self.nodes) > 1:\n            self.nodes.remove(name)\n            self.state.nodes = len(self.nodes)\n            self._log(self.percent, f"узел {name} ушёл ({self.state.nodes})")\n\n    # -------------------------------------------------------------- статус\n    @property\n    def percent(self) -> float:\n        """Процент роста, честно ограниченный возможностями железа.\n\n        ESP32 с четырьмя капсулами не может называться «полным роем»:\n        потолок задаётся тем, сколько капсул железо реально тянет.\n        """\n        return min(self.state.percent(), self.ceiling())\n\n    def ceiling(self) -> float:\n        """Максимум, достижимый на этом железе (и текущем рое)."""\n        if self.profile is None:\n            return 0.0\n        dev = self.host\n        fits = [c for c in CATALOG if c.fits_on(dev)]\n        if not fits:\n            return 1.0\n        # сколько капсул влезает в бюджет памяти роя при полной зрелости\n        budget = self.total_budget()\n        order = sorted(fits, key=lambda c: (not c.always_on, c.params_for(dev)))\n        used = n = 0\n        for c in order:\n            b = c.bytes_for(dev)\n            if used + b > budget:\n                break\n            used += b\n            n += 1\n        if n >= len(CATALOG):\n            return 100.0\n        pts = [(0, 0), (1, 1), (5, 7), (10, 12), (25, 25),\n               (50, 35), (75, 45), (90, 48)]\n        caps = [c for _, c in pts]\n        pcts = [p for p, _ in pts]\n        return float(np.clip(np.interp(n, caps, pcts), 1.0, 100.0))\n\n    @property\n    def stage(self) -> Stage_:\n        return stage_at(self.percent)\n\n    def active_capsules(self) -> List[CapsuleSpec]:\n        """Какие капсулы развёрнуты на текущем проценте роста.\n\n        Порядок пробуждения повторяет спецификацию: сначала зонд, затем\n        базовая семёрка, дальше — по мере роста, от дешёвых к дорогим.\n        """\n        if not self.state.probed:\n            return []\n        if not self.state.installed:\n            return [BY_KEY["profiler"]]\n\n        pct = self.percent\n        target = self._target_count(pct)\n        dev = self.host\n        fits = [c for c in CATALOG if c.fits_on(dev)]\n\n        # приоритет пробуждения\n        maturity = self.maturity()\n        base = ["profiler", "meta", "text_in", "meaning", "intent",\n                "working_mem", "gen_text", "critic", "safety"]\n        order: List[str] = [k for k in base if BY_KEY[k] in fits]\n        rest = sorted([c for c in fits if c.key not in order],\n                      key=lambda c: (not c.always_on, c.params_for(dev)))\n        order += [c.key for c in rest]\n        wanted = [BY_KEY[k] for k in order[:target]]\n\n        # Жёсткая гарантия: сумма капсул не превышает бюджет памяти роя.\n        # Протей растёт под железо, а не поверх него.\n        budget = self.total_budget()\n        out: List[CapsuleSpec] = []\n        used = 0\n        for c in wanted:\n            b = self.capsule_bytes(c)\n            if used + b > budget:\n                continue\n            out.append(c)\n            used += b\n        return out\n\n    def maturity(self) -> float:\n        """Зрелость 0..1: молодой Протей берёт нижнюю границу размеров.\n\n        «Базовый размер — 100M» на 5% и «максимум, который тянет железо»\n        на 100%. Растёт не только число капсул, но и каждая капсула.\n        """\n        return float(np.clip((self.percent - 5.0) / 95.0, 0.0, 1.0))\n\n    def capsule_params(self, spec: CapsuleSpec) -> int:\n        """Размер капсулы с учётом и железа, и текущей зрелости Протея."""\n        ceiling = spec.params_for(self.host)\n        if ceiling <= 0:\n            return 0\n        lo = float(spec.min_params)\n        hi = float(max(ceiling, spec.min_params))\n        return int(round(lo * (hi / lo) ** self.maturity()))\n\n    def capsule_bytes(self, spec: CapsuleSpec, bits: float = 2.0) -> int:\n        return int(self.capsule_params(spec) * bits / 8)\n\n    def total_budget(self) -> int:\n        """Бюджет памяти всего роя: каждый узел приносит свою долю."""\n        if self.profile is None:\n            return 0\n        own = self.profile.weight_budget()\n        extra = 0\n        for name in self.nodes[1:]:\n            dev = _device_by_name(name)\n            if dev is not None:\n                extra += dev.weight_budget\n        return own + extra\n\n    def _target_count(self, pct: float) -> int:\n        """Сколько капсул должно быть живо на этом проценте (шкала спеки)."""\n        pts = [(0, 0), (1, 1), (5, 7), (10, 12), (25, 25),\n               (50, 35), (75, 45), (90, 48), (100, 48)]\n        xs = [p for p, _ in pts]\n        ys = [c for _, c in pts]\n        n = int(round(float(np.interp(pct, xs, ys))))\n        return min(n, len([c for c in CATALOG if c.fits_on(self.host)]))\n\n    @property\n    def device(self) -> Device:\n        """Своё железо."""\n        if self.profile is None:\n            return get_device("phone")\n        return self.profile.as_device()\n\n    @property\n    def host(self) -> Device:\n        """Самый мощный узел роя — он определяет, что Протею вообще доступно.\n\n        Часы в паре с ноутбуком умеют то же, что ноутбук: тяжёлые капсулы\n        просто живут на сильном узле. Это и есть «рой как одно тело».\n        """\n        best = self.device\n        for name in self.nodes[1:]:\n            d = _device_by_name(name)\n            if d is not None and d.ram_bytes > best.ram_bytes:\n                best = d\n        return best\n\n    def active_params(self) -> int:\n        return sum(self.capsule_params(c) for c in self.active_capsules())\n\n    def memory_bytes(self, bits: float = 2.0) -> int:\n        return int(self.active_params() * bits / 8)\n\n    def fits_hardware(self) -> bool:\n        """Главная гарантия: Протей никогда не перерастает своё железо."""\n        if self.profile is None:\n            return True\n        return self.memory_bytes() <= self.total_budget()\n\n    # -------------------------------------------------------------- отчёты\n    def _log(self, pct: float, what: str) -> None:\n        self.history.append((pct, what))\n\n    def status(self) -> str:\n        s = self.stage\n        nxt = next_stage(self.percent)\n        lines = [\n            f"Протей {self.percent:.0f}% — {s.title}",\n            f"  капсул    : {len(self.active_capsules())} из 48",\n            f"  параметров: {self.active_params() / 1e6:.0f}M",\n            f"  память    : {self.memory_bytes() / MB:.0f} МБ"\n            + (f" из {self.total_budget() / MB:.0f} МБ бюджета роя"\n               if self.profile else ""),\n            f"  узлов роя : {self.state.nodes} ({\', \'.join(self.nodes) or \'—\'})",\n            f"  умеет     : {s.can_do}",\n            f"  железо    : {s.hardware}",\n            f"  влезает   : {\'да\' if self.fits_hardware() else \'НЕТ\'}",\n        ]\n        if nxt:\n            lines.append(f"  следующая : {nxt.pct}% — {nxt.title}")\n        return "\\n".join(lines)\n\n    def axes_bar(self, width: int = 22) -> str:\n        out = []\n        for name, val in self.state.axes().items():\n            filled = int(round(val * width))\n            out.append(f"  {name:<16}[{\'█\' * filled}{\'·\' * (width - filled)}] "\n                       f"{val * 100:>3.0f}%")\n        return "\\n".join(out)\n\n    def timeline(self) -> str:\n        return "\\n".join(f"  {p:>5.0f}%  {w}" for p, w in self.history)\n\n\ndef ladder_table() -> str:\n    """Сводная таблица пути 0→100% — как в спецификации."""\n    rows = [f"{\'%\':>4}  {\'капсул\':>7}{\'параметров\':>13}{\'память\':>11}  что умеет"]\n    for s in LADDER:\n        p = "максимум" if s.pct == 100 else (\n            f"{s.params / 1e9:.0f}B" if s.params >= 1e9 else\n            (f"{s.params / 1e6:.0f}M" if s.params >= 1e6 else\n             (f"{s.params / 1e3:.0f}K" if s.params else "0")))\n        rows.append(f"{s.pct:>3}%  {s.capsules:>7}{p:>13}{s.memory:>11}  {s.can_do[:44]}")\n    return "\\n".join(rows)\n'

_SOURCES['ultranet.proteus.matformer'] = '"""MatFormer — вложенная модель: одни веса, много размеров.\n\nРеализует ключевое заявление Протея: «Вложенность. Одна модель — все размеры.\nНе нужно хранить разные версии».\n\nПодмодель ширины w использует левый верхний угол каждой матрицы:\nW[:in*w, :out*w]. Обучение идёт сразу на нескольких ширинах (matryoshka\ntraining), поэтому любой срез остаётся рабочей моделью.\n\nДополнительно: ранний выход (early exit) — простые входы не проходят всю сеть.\n"""\nfrom __future__ import annotations\n\nimport math\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\nfrom .. import nn\nfrom ..nn import Parameter\nfrom ..tensor import Tensor, get_rng, no_grad\n\n\n@dataclass\nclass MatConfig:\n    """Конфигурация вложенной модели."""\n\n    vocab_size: int = 260          # байты + спецтокены\n    block_size: int = 128\n    n_layer: int = 6\n    n_embd: int = 128\n    head_dim: int = 32\n    mlp_ratio: int = 4\n    dropout: float = 0.0\n    widths: Tuple[float, ...] = (0.25, 0.5, 1.0)   # обучаемые срезы\n    exit_layers: Tuple[int, ...] = ()              # индексы слоёв с ранним выходом\n    n_experts: int = 0            # 0 = обычный MLP; >1 включает MoE\n    top_k_experts: int = 2        # сколько экспертов активно на токен\n\n    @property\n    def n_head(self) -> int:\n        return self.n_embd // self.head_dim\n\n\ndef _round_to(d: int, mult: int) -> int:\n    return max(mult, int(round(d / mult)) * mult)\n\n\ndef _rmsnorm(x: Tensor, gamma: Tensor, eps: float = 1e-6) -> Tensor:\n    rms = ((x ** 2).mean(axis=-1, keepdims=True) + eps).sqrt()\n    return x / rms * gamma\n\n\nclass ElasticLinear(nn.Module):\n    """Линейный слой, из которого можно взять любой под-блок весов."""\n\n    def __init__(self, in_f: int, out_f: int, bias: bool = False) -> None:\n        super().__init__()\n        self.in_f, self.out_f = in_f, out_f\n        self.weight = Parameter(\n            get_rng().standard_normal((in_f, out_f)).astype(np.float32) * math.sqrt(2.0 / in_f)\n        )\n        self.bias = Parameter(np.zeros(out_f, dtype=np.float32)) if bias else None\n\n    def forward(self, x: Tensor, in_d: Optional[int] = None, out_d: Optional[int] = None) -> Tensor:\n        in_d = in_d or self.in_f\n        out_d = out_d or self.out_f\n        w = self.weight[:in_d, :out_d]\n        out = x @ w\n        if self.bias is not None:\n            out = out + self.bias[:out_d]\n        return out\n\n    def active_params(self, in_d: int, out_d: int) -> int:\n        return in_d * out_d + (out_d if self.bias is not None else 0)\n\n\nclass MatBlock(nn.Module):\n    """Блок трансформера с эластичной шириной (RMSNorm + RoPE + SwiGLU)."""\n\n    def __init__(self, dim: int, head_dim: int, mlp_ratio: int = 4, dropout: float = 0.0,\n                 n_experts: int = 0, top_k: int = 2) -> None:\n        super().__init__()\n        self.dim, self.head_dim = dim, head_dim\n        self.mlp_dim = mlp_ratio * dim\n        self.g1 = Parameter(np.ones(dim, dtype=np.float32))\n        self.g2 = Parameter(np.ones(dim, dtype=np.float32))\n        self.wq = ElasticLinear(dim, dim)\n        self.wk = ElasticLinear(dim, dim)\n        self.wv = ElasticLinear(dim, dim)\n        self.wo = ElasticLinear(dim, dim)\n        self.n_experts = n_experts\n        if n_experts and n_experts > 1:\n            from .experts import MoE\n            self.moe = MoE(dim, n_experts, top_k, mlp_ratio)\n            self.w_gate = self.w_up = self.w_down = None\n        else:\n            self.moe = None\n            self.w_gate = ElasticLinear(dim, self.mlp_dim)\n            self.w_up = ElasticLinear(dim, self.mlp_dim)\n            self.w_down = ElasticLinear(self.mlp_dim, dim)\n        self.drop = nn.Dropout(dropout)\n\n    def forward(self, x: Tensor, d_act: int, rope: nn.RotaryEmbedding,\n                offset: int = 0, n_active_experts: Optional[int] = None) -> Tensor:\n        b, t, _ = x.shape\n        hd = self.head_dim\n        n_h = d_act // hd\n\n        h = _rmsnorm(x, self.g1[:d_act])\n        q = self.wq(h, d_act, d_act).reshape(b, t, n_h, hd).transpose(0, 2, 1, 3)\n        k = self.wk(h, d_act, d_act).reshape(b, t, n_h, hd).transpose(0, 2, 1, 3)\n        v = self.wv(h, d_act, d_act).reshape(b, t, n_h, hd).transpose(0, 2, 1, 3)\n        q, k = rope(q, offset), rope(k, offset)\n\n        att = (q @ k.transpose(0, 1, 3, 2)) * (1.0 / math.sqrt(hd))\n        mask = np.triu(np.ones((t, t), dtype=bool), k=1)[None, None]\n        att = att.masked_fill(np.broadcast_to(mask, att.shape), -1e9).softmax(axis=-1)\n        y = (att @ v).transpose(0, 2, 1, 3).reshape(b, t, d_act)\n        x = x + self.drop(self.wo(y, d_act, d_act))\n\n        h2 = _rmsnorm(x, self.g2[:d_act])\n        if self.moe is not None:\n            return x + self.drop(self.moe(h2, d_act, n_active_experts))\n        m_act = _round_to(self.mlp_dim * d_act // self.dim, 8)\n        gated = self.w_gate(h2, d_act, m_act).silu() * self.w_up(h2, d_act, m_act)\n        return x + self.drop(self.w_down(gated, m_act, d_act))\n\n    def active_params(self, d_act: int, n_active_experts: Optional[int] = None) -> int:\n        attn = 4 * d_act * d_act + 2 * d_act\n        if self.moe is not None:\n            return attn + self.moe.active_params(d_act, n_active_experts)\n        m_act = _round_to(self.mlp_dim * d_act // self.dim, 8)\n        return attn + 3 * d_act * m_act\n\n\nclass MatFormer(nn.Module):\n    """Вложенный байтовый трансформер: одна модель — все размеры.\n\n    >>> m = MatFormer(MatConfig(n_layer=2, n_embd=64))\n    >>> m(np.array([[1, 2, 3]]), width=0.5).shape      # четверть весов\n    (1, 3, 260)\n    """\n\n    def __init__(self, cfg: MatConfig) -> None:\n        super().__init__()\n        self.cfg = cfg\n        self.tok_emb = nn.Embedding(cfg.vocab_size, cfg.n_embd)\n        self.rope = nn.RotaryEmbedding(cfg.head_dim, max_seq=cfg.block_size * 8)\n        self.blocks = [MatBlock(cfg.n_embd, cfg.head_dim, cfg.mlp_ratio, cfg.dropout,\n                                cfg.n_experts, cfg.top_k_experts)\n                       for _ in range(cfg.n_layer)]\n        for i, b in enumerate(self.blocks):\n            self._modules[f"block{i}"] = b\n        self.g_out = Parameter(np.ones(cfg.n_embd, dtype=np.float32))\n        # нормы для ранних выходов\n        self.exit_norms = {i: Parameter(np.ones(cfg.n_embd, dtype=np.float32))\n                           for i in cfg.exit_layers}\n        for i, p in self.exit_norms.items():\n            self._params[f"exit_norm{i}"] = p\n        scale = 1.0 / math.sqrt(2 * cfg.n_layer)\n        for blk in self.blocks:\n            blk.wo.weight.data *= scale\n        # активные steering-векторы: слой -> (вектор, сила)\n        self._steering: Dict[int, Tuple[np.ndarray, float]] = {}\n        self._n_active_experts: Optional[int] = None\n\n    # ------------------------------------------------------------- размерность\n    def width_dim(self, width: float) -> int:\n        """Активная ширина скрытого состояния для доли width."""\n        w = float(np.clip(width, 1e-3, 1.0))\n        return min(self.cfg.n_embd, _round_to(int(self.cfg.n_embd * w), self.cfg.head_dim))\n\n    def active_params(self, width: float = 1.0, n_layers: Optional[int] = None) -> int:\n        """Сколько параметров реально участвует в вычислении."""\n        d = self.width_dim(width)\n        n_layers = self.cfg.n_layer if n_layers is None else n_layers\n        total = self.cfg.vocab_size * d + d          # эмбеддинги (голова связана) + норма\n        for blk in self.blocks[:n_layers]:\n            total += blk.active_params(d, self._n_active_experts)\n        return total\n\n    def total_params_dense(self) -> int:\n        """Все параметры, включая спящих экспертов."""\n        return self.num_params()\n\n    # ------------------------------------------------- пошаговый API (для роя)\n    def embed(self, idx, d_act: int) -> Tensor:\n        idx = np.asarray(idx.data if isinstance(idx, Tensor) else idx).astype(int)\n        if idx.ndim == 1:\n            idx = idx[None]\n        if idx.ndim != 2:\n            raise ValueError(f"ожидались индексы (batch, seq), получено {idx.shape}")\n        lo, hi = int(idx.min()), int(idx.max())\n        if lo < 0 or hi >= self.cfg.vocab_size:\n            raise IndexError(\n                f"байтовые id должны быть в [0, {self.cfg.vocab_size - 1}], получено [{lo}, {hi}]"\n            )\n        return self.tok_emb.weight[:, :d_act][idx]\n\n    def run_block(self, i: int, x: Tensor, d_act: int, offset: int = 0) -> Tensor:\n        x = self.blocks[i](x, d_act, self.rope, offset, self._n_active_experts)\n        sv = self._steering.get(i)\n        if sv is not None:\n            vec, alpha = sv\n            x = x + Tensor(vec[:d_act].astype(np.float32) * alpha)\n        return x\n\n    # ------------------------------------------------------ steering-векторы\n    def set_steering(self, layer: int, vector: np.ndarray, strength: float = 1.0) -> None:\n        """Сдвинуть активации слоя в заданном направлении (без смены весов)."""\n        self._steering[int(layer)] = (np.asarray(vector, dtype=np.float32), float(strength))\n\n    def clear_steering(self) -> None:\n        self._steering = {}\n\n    @property\n    def steering_active(self) -> bool:\n        return bool(self._steering)\n\n    def set_active_experts(self, k: Optional[int]) -> None:\n        """Сколько экспертов активировать (мета-контроллер крутит эту ручку)."""\n        self._n_active_experts = k\n\n    def norm_for_moe(self, x: Tensor, layer: int, d_act: int) -> Tensor:\n        """Нормированный вход MoE слоя — для анализа специализации."""\n        return _rmsnorm(x, self.blocks[layer].g2[:d_act])\n\n    def readout(self, x: Tensor, d_act: int, gamma: Optional[Tensor] = None) -> Tensor:\n        g = self.g_out[:d_act] if gamma is None else gamma[:d_act]\n        h = _rmsnorm(x, g)\n        return h @ self.tok_emb.weight[:, :d_act].transpose()   # связанные веса\n\n    # --------------------------------------------------------------- forward\n    def forward(self, idx, width: float = 1.0, n_layers: Optional[int] = None,\n                return_exits: bool = False):\n        d = self.width_dim(width)\n        n_layers = self.cfg.n_layer if n_layers is None else n_layers\n        x = self.embed(idx, d)\n        exits: List[Tuple[int, Tensor]] = []\n        for i in range(n_layers):\n            x = self.run_block(i, x, d)\n            if return_exits and i in self.exit_norms and i < n_layers - 1:\n                exits.append((i, self.readout(x, d, self.exit_norms[i])))\n        logits = self.readout(x, d)\n        return (logits, exits) if return_exits else logits\n\n    # ------------------------------------------------------------ ранний выход\n    @staticmethod\n    def confidence(logits: Tensor) -> float:\n        """Уверенность = max softmax по последней позиции."""\n        z = logits.data[0, -1]\n        p = np.exp(z - z.max())\n        return float((p / p.sum()).max())\n\n    @no_grad()\n    def forward_early_exit(self, idx, width: float = 1.0, threshold: float = 0.9):\n        """Идти по слоям, пока ответ не станет уверенным.\n\n        Возвращает (logits, использовано_слоёв).\n        """\n        d = self.width_dim(width)\n        x = self.embed(idx, d)\n        for i in range(self.cfg.n_layer):\n            x = self.run_block(i, x, d)\n            if i in self.exit_norms and i < self.cfg.n_layer - 1:\n                logits = self.readout(x, d, self.exit_norms[i])\n                if self.confidence(logits) >= threshold:\n                    return logits, i + 1\n        return self.readout(x, d), self.cfg.n_layer\n\n    # -------------------------------------------------------------- генерация\n    @no_grad()\n    def generate(self, prompt: Sequence[int], max_new_tokens: int = 64, width: float = 1.0,\n                 temperature: float = 0.8, top_k: Optional[int] = None,\n                 n_layers: Optional[int] = None, seed: Optional[int] = None) -> List[int]:\n        rng = np.random.default_rng(seed)\n        was = self.training\n        self.eval()\n        seq = list(prompt)\n        for _ in range(max_new_tokens):\n            ctx = np.array([seq[-self.cfg.block_size:]], dtype=int)\n            z = self(ctx, width=width, n_layers=n_layers).data[0, -1].astype(np.float64)\n            if temperature <= 1e-6:\n                nxt = int(z.argmax())\n            else:\n                z = z / temperature\n                if top_k:\n                    thr = np.partition(z, -top_k)[-top_k]\n                    z = np.where(z < thr, -np.inf, z)\n                p = np.exp(z - z.max())\n                nxt = int(rng.choice(len(p), p=p / p.sum()))\n            seq.append(nxt)\n        self.train(was)\n        return seq\n'

_SOURCES['ultranet.proteus.memory'] = '"""RAG: знание живёт вне весов.\n\nРеализует заявление: «RAG вместо параметров. Крошечная модель знает больше,\nчем большая без памяти». Здесь это проверяемо: индекс хранит факты локально,\nпоиск идёт по символьным n-граммам (не требует эмбеддинг-модели),\nвсё остаётся на устройстве.\n"""\nfrom __future__ import annotations\n\nimport json\nimport math\nimport re\nfrom collections import Counter, defaultdict\nfrom dataclasses import dataclass, field\nfrom typing import Dict, Iterable, List, Optional, Sequence, Tuple\n\n\ndef _ngrams(text: str, n: int = 3) -> List[str]:\n    """Символьные n-граммы нескольких длин.\n\n    Индексируются длины 2..n: короткие запросы (например, CJK «東京» —\n    всего 2 символа) иначе не находились бы в индексе из 3-грамм.\n    """\n    t = re.sub(r"\\s+", " ", text.lower().strip())\n    if not t:\n        return []\n    out: List[str] = []\n    for size in range(2, n + 1):\n        if len(t) < size:\n            continue\n        out.extend(t[i:i + size] for i in range(len(t) - size + 1))\n    # Целые слова как отдельные термы: иначе запрос «137» матчится\n    # на «1372» через общие n-граммы. Слово даёт точное совпадение\n    # с высоким весом и разводит такие случаи.\n    out.extend(f"\\u0000w:{w}" for w in re.findall(r"\\w+", t))\n    return out or [t]\n\n\n@dataclass\nclass Doc:\n    id: int\n    text: str\n    meta: Dict = field(default_factory=dict)\n\n\nclass LocalMemory:\n    """Локальный RAG-индекс: BM25 по символьным n-граммам.\n\n    Не покидает устройство, не требует сети и эмбеддинг-модели.\n\n    >>> mem = LocalMemory()\n    >>> mem.add("Столица Франции — Париж.")\n    >>> mem.search("париж")[0].text\n    \'Столица Франции — Париж.\'\n    """\n\n    def __init__(self, n: int = 3, k1: float = 1.5, b: float = 0.75) -> None:\n        self.n, self.k1, self.b = n, k1, b\n        self.docs: List[Doc] = []\n        self.postings: Dict[str, List[Tuple[int, int]]] = defaultdict(list)\n        self.doc_len: List[int] = []\n\n    def __len__(self) -> int:\n        return len(self.docs)\n\n    def add(self, text: str, **meta) -> int:\n        doc_id = len(self.docs)\n        self.docs.append(Doc(doc_id, text, meta))\n        counts = Counter(_ngrams(text, self.n))\n        for gram, c in counts.items():\n            self.postings[gram].append((doc_id, c))\n        self.doc_len.append(sum(counts.values()) or 1)\n        return doc_id\n\n    def add_many(self, texts: Iterable[str]) -> None:\n        for t in texts:\n            self.add(t)\n\n    def search(self, query: str, top_k: int = 3) -> List[Doc]:\n        return [d for d, _ in self.search_scored(query, top_k)]\n\n    def search_scored(self, query: str, top_k: int = 3) -> List[Tuple[Doc, float]]:\n        if not self.docs:\n            return []\n        avgdl = sum(self.doc_len) / len(self.doc_len)\n        N = len(self.docs)\n        scores: Dict[int, float] = defaultdict(float)\n        for gram in set(_ngrams(query, self.n)):\n            posting = self.postings.get(gram)\n            if not posting:\n                continue\n            idf = math.log(1 + (N - len(posting) + 0.5) / (len(posting) + 0.5))\n            for doc_id, tf in posting:\n                dl = self.doc_len[doc_id]\n                denom = tf + self.k1 * (1 - self.b + self.b * dl / avgdl)\n                scores[doc_id] += idf * (tf * (self.k1 + 1)) / denom\n        ranked = sorted(scores.items(), key=lambda kv: -kv[1])[:top_k]\n        return [(self.docs[i], s) for i, s in ranked]\n\n    def context_for(self, query: str, top_k: int = 3, max_chars: int = 400) -> str:\n        """Собрать контекст для подстановки в промпт."""\n        parts, total = [], 0\n        for doc in self.search(query, top_k):\n            if total + len(doc.text) > max_chars:\n                break\n            parts.append(doc.text)\n            total += len(doc.text)\n        return "\\n".join(parts)\n\n    # ------------------------------------------------------------ размер/IO\n    def size_bytes(self) -> int:\n        """Сколько памяти занимает знание — сравнимо с весами модели."""\n        return sum(len(d.text.encode("utf-8")) for d in self.docs)\n\n    def save(self, path: str) -> None:\n        with open(path, "w", encoding="utf-8") as f:\n            json.dump([{"text": d.text, "meta": d.meta} for d in self.docs],\n                      f, ensure_ascii=False)\n\n    @classmethod\n    def load(cls, path: str, n: int = 3) -> "LocalMemory":\n        mem = cls(n=n)\n        with open(path, encoding="utf-8") as f:\n            for row in json.load(f):\n                mem.add(row["text"], **row.get("meta", {}))\n        return mem\n'

_SOURCES['ultranet.proteus.quant'] = '"""Тернарное квантование 1.58 бит: веса в {-1, 0, +1} со скейлом (BitNet b1.58).\n\nРеализует заявление: «Квантование до 1.58-bit. Веса в {-1, 0, 1}.\n10-кратная экономия против FP16».\n\nЗдесь считается РЕАЛЬНЫЙ размер упакованных весов, а не теоретическая оценка.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Tuple\n\nimport math\n\nimport numpy as np\n\nfrom ..nn import Module, Parameter\nfrom ..tensor import Tensor\n\n\ndef ternary_quantize(w: np.ndarray) -> Tuple[np.ndarray, float]:\n    """W -> (Q, scale), где Q ∈ {-1,0,1}. Скейл = среднее |W| (absmean, BitNet)."""\n    scale = float(np.abs(w).mean()) + 1e-8\n    q = np.clip(np.round(w / scale), -1, 1).astype(np.int8)\n    return q, scale\n\n\ndef pack_ternary(q: np.ndarray) -> np.ndarray:\n    """Упаковать {-1,0,1} по 2 бита на вес — 4 веса в байт."""\n    flat = (q.reshape(-1) + 1).astype(np.uint8)       # -1,0,1 -> 0,1,2\n    pad = (-flat.size) % 4\n    if pad:\n        flat = np.concatenate([flat, np.zeros(pad, dtype=np.uint8)])\n    g = flat.reshape(-1, 4)\n    return (g[:, 0] | (g[:, 1] << 2) | (g[:, 2] << 4) | (g[:, 3] << 6)).astype(np.uint8)\n\n\ndef unpack_ternary(packed: np.ndarray, shape: Tuple[int, ...]) -> np.ndarray:\n    n = int(np.prod(shape))\n    b = packed.astype(np.uint8)\n    vals = np.stack([b & 3, (b >> 2) & 3, (b >> 4) & 3, (b >> 6) & 3], axis=1).reshape(-1)\n    return (vals[:n].astype(np.int8) - 1).reshape(shape)\n\n\n@dataclass\nclass QuantStats:\n    """Отчёт о сжатии модели."""\n\n    n_params: int\n    fp32_bytes: int\n    packed_bytes: int\n    bits_per_weight: float\n    entropy_bits: float          # реальная энтропия распределения {-1,0,1}\n    zero_fraction: float\n\n    @property\n    def ratio_vs_fp32(self) -> float:\n        return self.fp32_bytes / max(self.packed_bytes, 1)\n\n    @property\n    def ratio_vs_fp16(self) -> float:\n        return (self.fp32_bytes / 2) / max(self.packed_bytes, 1)\n\n    def __str__(self) -> str:\n        return (\n            f"параметров {self.n_params:,} | fp32 {self.fp32_bytes / 1024:.1f} КБ -> "\n            f"упаковано {self.packed_bytes / 1024:.1f} КБ | {self.bits_per_weight:.2f} бит/вес "\n            f"(энтропия {self.entropy_bits:.2f}) | x{self.ratio_vs_fp32:.1f} к fp32, "\n            f"x{self.ratio_vs_fp16:.1f} к fp16 | нулей {self.zero_fraction * 100:.0f}%"\n        )\n\n\nclass TernaryModel:\n    """Квантованная копия модели: хранит упакованные веса и скейлы."""\n\n    def __init__(self, model: Module, skip_1d: bool = True) -> None:\n        self.shapes: Dict[str, Tuple[int, ...]] = {}\n        self.packed: Dict[str, np.ndarray] = {}\n        self.scales: Dict[str, float] = {}\n        self.kept_fp: Dict[str, np.ndarray] = {}\n        n_params = fp32_bytes = packed_bytes = 0\n        zeros = total_q = 0\n        hist = np.zeros(3, dtype=np.int64)\n\n        for name, p in model.named_parameters():\n            n_params += p.size\n            fp32_bytes += p.size * 4\n            # нормы/биасы (1-D) оставляем во fp32 — их доля ничтожна, а точность важна\n            if skip_1d and p.data.ndim == 1:\n                self.kept_fp[name] = p.data.copy()\n                packed_bytes += p.size * 4\n                continue\n            q, s = ternary_quantize(p.data)\n            self.shapes[name] = p.data.shape\n            self.packed[name] = pack_ternary(q)\n            self.scales[name] = s\n            packed_bytes += self.packed[name].nbytes + 4\n            zeros += int((q == 0).sum())\n            total_q += q.size\n            hist += np.bincount((q.reshape(-1) + 1), minlength=3)\n\n        probs = hist / max(hist.sum(), 1)\n        entropy = float(-(probs[probs > 0] * np.log2(probs[probs > 0])).sum())\n        self.stats = QuantStats(\n            n_params=n_params,\n            fp32_bytes=fp32_bytes,\n            packed_bytes=packed_bytes,\n            bits_per_weight=packed_bytes * 8 / max(n_params, 1),\n            entropy_bits=entropy,\n            zero_fraction=zeros / max(total_q, 1),\n        )\n\n    def dequantize_into(self, model: Module) -> Module:\n        """Записать деквантованные веса обратно в модель (fake-quant инференс)."""\n        params = dict(model.named_parameters())\n        for name, packed in self.packed.items():\n            q = unpack_ternary(packed, self.shapes[name])\n            params[name].data = (q.astype(np.float32) * self.scales[name])\n        for name, w in self.kept_fp.items():\n            params[name].data = w.copy()\n        return model\n\n\ndef quantization_error(model: Module) -> Dict[str, float]:\n    """Относительная ошибка восстановления весов после тернаризации."""\n    errs = {}\n    for name, p in model.named_parameters():\n        if p.data.ndim == 1:\n            continue\n        q, s = ternary_quantize(p.data)\n        approx = q.astype(np.float32) * s\n        errs[name] = float(np.linalg.norm(approx - p.data) / (np.linalg.norm(p.data) + 1e-9))\n    return errs\n\n\n# ═══════════════════════════════════ обучение квантованной сети (STE)\nclass TernaryLinear(Module):\n    """Слой, который обучается сразу в тернарном виде через STE.\n\n    Straight-Through Estimator: в forward веса округляются до {-1, 0, 1},\n    а градиент проходит сквозь округление к теневым FP-весам. Так сеть\n    учится жить с тем квантованием, с которым будет работать.\n    """\n\n    def __init__(self, in_f: int, out_f: int, bias: bool = False) -> None:\n        super().__init__()\n        from ..tensor import get_rng\n        self.in_f, self.out_f = in_f, out_f\n        # теневые веса высокой точности — обучаются, но не используются напрямую\n        self.weight = Parameter(get_rng().standard_normal((in_f, out_f)).astype(np.float32)\n                                / math.sqrt(in_f))\n        self.bias = Parameter(np.zeros(out_f, dtype=np.float32)) if bias else None\n\n    def quantized_weight(self) -> Tensor:\n        """w_q = round(clip(w/scale)) * scale, градиент идёт мимо round."""\n        w = self.weight\n        scale = float(np.abs(w.data).mean()) or 1.0\n        q = np.clip(np.rint(w.data / scale), -1.0, 1.0) * scale\n        # STE: значение квантованное, градиент — как у исходного веса\n        return w + Tensor(q - w.data)\n\n    def forward(self, x: Tensor) -> Tensor:\n        out = x @ self.quantized_weight()\n        return out + self.bias if self.bias is not None else out\n\n    def ternary_fraction(self) -> float:\n        scale = float(np.abs(self.weight.data).mean()) or 1.0\n        q = np.clip(np.rint(self.weight.data / scale), -1.0, 1.0)\n        return float(np.isin(q, (-1.0, 0.0, 1.0)).mean())\n\n    def bits_per_weight(self) -> float:\n        return math.log2(3)\n\n\ndef ste_round(x: Tensor, levels: int = 3) -> Tensor:\n    """Округление с прохождением градиента насквозь (для любых схем)."""\n    half = (levels - 1) / 2.0\n    q = np.clip(np.rint(x.data * half), -half, half) / half\n    return x + Tensor(q - x.data)\n'

_SOURCES['ultranet.proteus.shards'] = '"""Шарды и рой без лидера.\n\n«Каждое устройство хранит свой шард — не копию модели, а кусок одного\nорганизма. Шарды пересекаются: маленькие устройства хранят только маленькие\nуровни вложенности, большие — все».\n\nЧетыре правила консенсуса из спецификации:\n  1. Кто ближе — тот и роутер.   2. Кто свободнее — тот и считает.\n  3. Кто голоднее — тот и отдаёт. 4. Кто умнее — тот и решает сложное.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional, Sequence, Set, Tuple\n\nimport numpy as np\n\nfrom .devices import Device, DeviceState\n\n\n@dataclass\nclass Shard:\n    """Кусок Протея, живущий на узле.\n\n    Шард описывается диапазоном уровней вложенности [0, max_width] и\n    множеством слоёв. Маленькое устройство хранит только узкие уровни.\n    """\n\n    layers: Set[int] = field(default_factory=set)\n    max_width: float = 1.0\n    skills: Set[str] = field(default_factory=set)\n    bytes_stored: int = 0\n\n    def covers(self, layer: int, width: float) -> bool:\n        return layer in self.layers and width <= self.max_width + 1e-9\n\n    def __str__(self) -> str:\n        ls = f"{min(self.layers)}–{max(self.layers)}" if self.layers else "—"\n        return f"слои {ls}, ширина ≤{self.max_width:.2f}, {self.bytes_stored / 1024:.0f} КБ"\n\n\n@dataclass\nclass SwarmNode:\n    """Узел роя со своим шардом и состоянием."""\n\n    state: DeviceState\n    shard: Shard = field(default_factory=Shard)\n    online: bool = True\n    router_score: float = 0.0\n\n    @property\n    def name(self) -> str:\n        return self.state.device.name\n\n    @property\n    def power(self) -> float:\n        return self.state.device.gflops * self.state.throttle\n\n    @property\n    def hunger(self) -> float:\n        """Насколько узел «голоден» (мало батареи) — тем меньше берёт работы."""\n        if not self.state.device.battery:\n            return 0.0\n        return max(0.0, (100.0 - self.state.battery_pct) / 100.0)\n\n\nclass ShardedSwarm:\n    """Рой без лидера: шарды, консенсус по правилам, отказоустойчивость.\n\n    >>> sw = ShardedSwarm(model, states)\n    >>> sw.elect_router(["код"])      # роутером станет узел с кодовым шардом\n    >>> sw.forward(ids)               # результат равен монолиту\n    """\n\n    def __init__(self, model, states: Sequence[DeviceState],\n                 width: float = 1.0, skills_by_layer: Optional[Dict[int, Set[str]]] = None) -> None:\n        self.model = model\n        self.width = width\n        self.skills_by_layer = skills_by_layer or {}\n        self.nodes: List[SwarmNode] = [SwarmNode(s) for s in states]\n        self.hops = 0\n        self.bytes_moved = 0\n        self.rebuilds = 0\n        self.current_router: Optional[str] = None\n        self.rebalance()\n\n    # --------------------------------------------------------- распределение\n    def rebalance(self) -> None:\n        """Пересобрать карту роя. Вызывается при любом изменении состава."""\n        live = [n for n in self.nodes if n.online]\n        if not live:\n            raise ValueError("рой пуст: нет онлайн-узлов")\n        n_layers = self.model.cfg.n_layer\n\n        # вес узла: мощность, уменьшенная голодом (правило 3)\n        weights = np.array([n.power * (1.0 - 0.5 * n.hunger) for n in live], dtype=float)\n        weights = np.clip(weights, 1e-6, None)\n        share = weights / weights.sum()\n\n        counts = np.floor(share * n_layers).astype(int)\n        if n_layers >= len(live):\n            counts = np.maximum(counts, 1)\n        while counts.sum() < n_layers:\n            counts[int(np.argmax(share - counts / max(n_layers, 1)))] += 1\n        while counts.sum() > n_layers:\n            floor = 1 if n_layers >= len(live) else 0\n            cand = np.where(counts > floor)[0]\n            counts[cand[int(np.argmax(counts[cand]))]] -= 1\n\n        # слабые узлы идут первыми (вход), мощные — в конце (тяжёлые слои)\n        order = np.argsort(weights)\n        cursor = 0\n        for i in order:\n            node = live[i]\n            take = int(counts[i])\n            layers = set(range(cursor, cursor + take))\n            cursor += take\n            # ширина шарда ограничена памятью устройства\n            max_w = self._max_width_for(node, len(layers))\n            skills: Set[str] = set()\n            for l in layers:\n                skills |= self.skills_by_layer.get(l, set())\n            node.shard = Shard(layers, max_w, skills,\n                               self._shard_bytes(len(layers), max_w))\n        for n in self.nodes:\n            if not n.online:\n                n.shard = Shard()\n        self.rebuilds += 1\n\n    def _max_width_for(self, node: SwarmNode, n_layers: int) -> float:\n        """Какую ширину узел способен хранить в своей памяти."""\n        budget = node.state.available_bytes\n        for w in (1.0, 0.75, 0.5, 0.25, 0.125):\n            if self._shard_bytes(n_layers, w) <= budget:\n                return w\n        return 0.125\n\n    def _shard_bytes(self, n_layers: int, width: float) -> int:\n        d = self.model.width_dim(width)\n        per_layer = self.model.blocks[0].active_params(d)\n        return int((per_layer * n_layers + self.model.cfg.vocab_size * d) * 2 / 8)\n\n    # ------------------------------------------------------------- консенсус\n    def elect_router(self, need_skills: Sequence[str] = (),\n                     complexity: float = 0.5) -> SwarmNode:\n        """Выбрать временного роутера по четырём правилам. Лидера нет."""\n        live = [n for n in self.nodes if n.online]\n        best, best_score = None, -np.inf\n        for n in live:\n            # правило 1: кто ближе к задаче (есть нужные навыки в шарде)\n            skill = n.shard.skills & set(need_skills)\n            s_skill = len(skill) / max(len(set(need_skills)), 1) if need_skills else 0.0\n            # правило 2: кто свободнее\n            s_free = n.state.ram_free_frac\n            # правило 3: кто голоднее — тот меньше хочет быть роутером\n            s_hunger = -n.hunger\n            # правило 4: кто умнее — для сложных задач\n            s_power = np.log1p(n.power) / 5.0 * complexity\n            score = 2.0 * s_skill + 0.5 * s_free + 0.5 * s_hunger + s_power\n            n.router_score = float(score)\n            if score > best_score:\n                best, best_score = n, score\n        self.current_router = best.name\n        return best\n\n    def consensus(self, proposal: str, votes_needed: float = 0.5) -> bool:\n        """Резонанс вместо голосования: изменение проходит при поддержке большинства.\n\n        Узел «за», если у него есть ресурс (не голодает и не перегрет).\n        """\n        live = [n for n in self.nodes if n.online]\n        if not live:\n            return False\n        agree = sum(1 for n in live if n.state.throttle > 0.5)\n        return agree / len(live) > votes_needed\n\n    # ---------------------------------------------------------------- жизнь\n    def join(self, state: DeviceState) -> SwarmNode:\n        node = SwarmNode(state)\n        self.nodes.append(node)\n        self.rebalance()\n        return node\n\n    def leave(self, name: str, permanent: bool = False) -> None:\n        """Узел ушёл. Шарды перераспределяются, ничего не теряется."""\n        found = [n for n in self.nodes if n.name == name]\n        if not found:\n            raise KeyError(f"узел \'{name}\' не найден")\n        if len([n for n in self.nodes if n.online]) <= 1:\n            raise ValueError("нельзя отключить последний узел роя")\n        if permanent:\n            self.nodes = [n for n in self.nodes if n.name != name]\n        else:\n            found[0].online = False\n        self.rebalance()\n\n    def rejoin(self, name: str) -> None:\n        """Узел вернулся — Протей растекается обратно."""\n        for n in self.nodes:\n            if n.name == name:\n                n.online = True\n        self.rebalance()\n\n    # -------------------------------------------------------------- инференс\n    def forward(self, idx):\n        """Прогон по цепочке шардов. По сети идут активации, не веса."""\n        from ..tensor import no_grad\n\n        with no_grad():\n            d = self.model.width_dim(self.width)\n            x = self.model.embed(idx, d)\n            self.hops = 0\n            self.bytes_moved = 0\n            chain = sorted([n for n in self.nodes if n.online and n.shard.layers],\n                           key=lambda n: min(n.shard.layers))\n            for i, node in enumerate(chain):\n                for li in sorted(node.shard.layers):\n                    x = self.model.run_block(li, x, d)\n                if i < len(chain) - 1:\n                    payload = int(np.prod(x.shape)) * 4\n                    self.bytes_moved += payload\n                    self.hops += 1\n            return self.model.readout(x, d)\n\n    # --------------------------------------------------------------- отчёты\n    def topology(self) -> str:\n        rows = []\n        for n in sorted(self.nodes, key=lambda x: (min(x.shard.layers) if x.shard.layers else 99)):\n            status = "●" if n.online else "○ offline"\n            rows.append(f"  {status} {n.name:<20} {n.shard}"\n                        + (f"  [{\', \'.join(sorted(n.shard.skills))}]" if n.shard.skills else ""))\n        return "\\n".join(rows)\n\n    def coverage(self) -> bool:\n        """Все ли слои модели покрыты живыми шардами."""\n        covered: Set[int] = set()\n        for n in self.nodes:\n            if n.online:\n                covered |= n.shard.layers\n        return covered == set(range(self.model.cfg.n_layer))\n'

_SOURCES['ultranet.proteus.steering'] = '"""Test-time steering vectors: направление мышления без изменения весов.\n\n«Активировать вектор "математика" — значит сдвинуть все активации\nв сторону математического мышления. Без изменения весов».\n\nВектор строится как разность средних активаций на двух наборах примеров\n(контрастная пара), затем прибавляется к активациям нужного слоя.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional, Sequence\n\nimport numpy as np\n\nfrom ..tensor import Tensor, no_grad\nfrom .bytes import ByteTokenizer\n\n\n@dataclass\nclass SteeringVector:\n    """Направление в пространстве активаций."""\n\n    name: str\n    layer: int\n    vector: np.ndarray          # (dim,)\n    strength: float = 1.0\n\n    @property\n    def dim(self) -> int:\n        return int(self.vector.shape[0])\n\n    @property\n    def direction(self) -> np.ndarray:\n        """Единичный вектор направления."""\n        n = float(np.linalg.norm(self.vector))\n        return self.vector / n if n > 1e-9 else self.vector\n\n    def scaled(self, d_act: int, alpha: Optional[float] = None) -> np.ndarray:\n        a = self.strength if alpha is None else alpha\n        return self.vector[:d_act] * a\n\n    def __str__(self) -> str:\n        return (f"«{self.name}» слой {self.layer} dim={self.dim} "\n                f"|v|={np.linalg.norm(self.vector):.3f} сила={self.strength:.2f}")\n\n\nclass SteeringLibrary:\n    """Набор векторов: «математика», «поэзия», «простота», «детальность»…\n\n    >>> lib = SteeringLibrary(model)\n    >>> lib.learn("простота", positive=[...], negative=[...], layer=2)\n    >>> with lib.active("простота", 1.5):\n    ...     out = model(ids)\n    """\n\n    def __init__(self, model, tokenizer: Optional[ByteTokenizer] = None) -> None:\n        self.model = model\n        self.tok = tokenizer or ByteTokenizer()\n        self.vectors: Dict[str, SteeringVector] = {}\n\n    def _as_ids(self, sample) -> List[int]:\n        """Принимаем и текст, и байты, и готовые id — так пользоваться удобнее."""\n        if isinstance(sample, str):\n            return self.tok.encode(sample)\n        if isinstance(sample, (bytes, bytearray)):\n            return [int(b) for b in sample]\n        return [int(t) for t in sample]\n\n    @staticmethod\n    def _check_batch(samples, argname: str) -> Sequence:\n        """Отсечь голую строку, переданную вместо списка примеров.\n\n        `learn(positive="текст")` — частая опечатка: строка итерируется\n        посимвольно, вектор получается бессмысленным, и никто об этом не\n        узнаёт. Молча неверный результат хуже падения, поэтому падаем.\n        """\n        if isinstance(samples, (str, bytes, bytearray)):\n            raise TypeError(\n                f"{argname} должен быть списком примеров, а не одной строкой: "\n                f"строка будет разобрана посимвольно. "\n                f"Передайте [{argname}] — список из одного элемента.")\n        if not isinstance(samples, Sequence) and not hasattr(samples, "__iter__"):\n            raise TypeError(f"{argname}: ожидается последовательность примеров, "\n                            f"получено {type(samples).__name__}")\n        return samples\n\n    def _resolve_layer(self, layer: int) -> int:\n        """Отрицательный индекс считается от конца, как в Python."""\n        n = self.model.cfg.n_layer\n        li = layer + n if layer < 0 else layer\n        return int(np.clip(li, 0, n - 1))\n\n    # ----------------------------------------------------------- построение\n    @no_grad()\n    def _mean_activation(self, samples: Sequence[Sequence[int]], layer: int,\n                         d_act: int) -> np.ndarray:\n        acc = np.zeros(d_act, dtype=np.float64)\n        n = 0\n        for sample in samples:\n            ids = self._as_ids(sample)\n            if not ids:\n                continue\n            arr = np.array([ids[:self.model.cfg.block_size]], dtype=int)\n            x = self.model.embed(arr, d_act)\n            for i in range(layer + 1):\n                x = self.model.run_block(i, x, d_act)\n            acc += x.data[0].mean(axis=0).astype(np.float64)\n            n += 1\n        return (acc / max(n, 1)).astype(np.float32)\n\n    def learn(self, name: str, positive: Sequence[Sequence[int]],\n              negative: Sequence[Sequence[int]], layer: int = 2,\n              strength: float = 1.0, normalize: bool = True) -> SteeringVector:\n        """Контрастный вектор: среднее(positive) − среднее(negative)."""\n        positive = self._check_batch(positive, "positive")\n        negative = self._check_batch(negative, "negative")\n        if len(positive) == 0 or len(negative) == 0:\n            raise ValueError("positive и negative не должны быть пустыми: "\n                             "контрастный вектор строится как разность средних")\n        d = self.model.width_dim(1.0)\n        layer = self._resolve_layer(layer)\n        pos = self._mean_activation(positive, layer, d)\n        neg = self._mean_activation(negative, layer, d)\n        v = pos - neg\n        if normalize:\n            norm = float(np.linalg.norm(v))\n            if norm > 1e-9:\n                v = v / norm\n        sv = SteeringVector(name, layer, v.astype(np.float32), strength)\n        self.vectors[name] = sv\n        return sv\n\n    def add(self, sv: SteeringVector) -> None:\n        self.vectors[sv.name] = sv\n\n    def names(self) -> List[str]:\n        return list(self.vectors)\n\n    def __getitem__(self, name: str) -> SteeringVector:\n        return self.vectors[name]\n\n    def __contains__(self, name: str) -> bool:\n        return name in self.vectors\n\n    def __len__(self) -> int:\n        return len(self.vectors)\n\n    # ------------------------------------------------------------ применение\n    def apply(self, name: str, strength: Optional[float] = None) -> None:\n        """Включить вектор для последующих forward."""\n        if name not in self.vectors:\n            raise KeyError(f"вектор «{name}» не выучен. Есть: {\', \'.join(self.vectors) or \'—\'}")\n        sv = self.vectors[name]\n        self.model.set_steering(sv.layer, sv.vector,\n                                sv.strength if strength is None else strength)\n\n    def clear(self) -> None:\n        self.model.clear_steering()\n\n    def active(self, name: str, strength: Optional[float] = None):\n        """Контекстный менеджер: вектор действует только внутри блока."""\n        lib = self\n\n        class _Ctx:\n            def __enter__(self):\n                lib.apply(name, strength)\n                return lib\n\n            def __exit__(self, *exc):\n                lib.clear()\n                return False\n\n        return _Ctx()\n\n    # -------------------------------------------------------------- эффект\n    @no_grad()\n    def effect_size(self, name: str, probe: Optional[Sequence] = None,\n                    strength: Optional[float] = None) -> float:\n        """Насколько сильно вектор меняет распределение на выходе (L1, 0..2)."""\n        if probe is None:\n            probe = [1, 2, 3, 4, 5, 6, 7, 8]\n        ids = self._as_ids(probe)\n        arr = np.array([ids[:self.model.cfg.block_size]], dtype=int)\n        base = self.model(arr).softmax(axis=-1).data[0, -1]\n        self.apply(name, strength)\n        steered = self.model(arr).softmax(axis=-1).data[0, -1]\n        self.clear()\n        return float(np.abs(base - steered).sum())\n'

_SOURCES['ultranet.proteus.swarm'] = '"""Рой: один Протей, разлитый по нескольким устройствам.\n\nРеализует Часть 4: «Наушники слышат, часы думают, телефон помнит,\nноутбук считает. Inference идёт по цепочке. Нет центра».\n\nСлои трансформера распределяются между узлами пропорционально их мощности;\nактивация передаётся по цепочке. Отключение узла вызывает перераспределение\n(«Протей отступает»), подключение — расширение («растекается»).\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\nfrom ..tensor import Tensor, no_grad\nfrom .controller import MetaController\nfrom .devices import Device, DeviceState\nfrom .matformer import MatFormer\n\n\n@dataclass\nclass Node:\n    """Узел роя — устройство с его состоянием."""\n\n    state: DeviceState\n    layers: List[int] = field(default_factory=list)\n    bytes_moved: int = 0\n\n    @property\n    def name(self) -> str:\n        return self.state.device.name\n\n    @property\n    def capacity(self) -> float:\n        """Пропускная способность с учётом троттлинга."""\n        return max(self.state.device.gflops * self.state.throttle, 1e-6)\n\n\nclass Swarm:\n    """Инференс по цепочке устройств без центра и облака.\n\n    >>> sw = Swarm(model, [DeviceState(get_device("earbuds")),\n    ...                    DeviceState(get_device("phone"))])\n    >>> logits = sw.forward(np.array([[1, 2, 3]]))\n    """\n\n    def __init__(self, model: MatFormer, states: Sequence[DeviceState],\n                 width: float = 1.0) -> None:\n        self.model = model\n        self.width = width\n        self.nodes: List[Node] = [Node(s) for s in states]\n        self.hops = 0\n        self.bytes_total = 0\n        self._assign()\n\n    # ----------------------------------------------------------- топология\n    def _assign(self) -> None:\n        """Распределить слои пропорционально мощности узлов."""\n        n_layers = self.model.cfg.n_layer\n        for n in self.nodes:\n            n.layers = []\n        if not self.nodes:\n            raise ValueError("рой пуст — некому считать")\n        caps = np.array([n.capacity for n in self.nodes], dtype=float)\n        share = caps / caps.sum()\n        counts = np.floor(share * n_layers).astype(int)\n        # каждый узел получает хотя бы один слой, если слоёв хватает:\n        # даже слабые наушники участвуют в общем организме\n        if n_layers >= len(self.nodes):\n            counts = np.maximum(counts, 1)\n        while counts.sum() < n_layers:\n            counts[int(np.argmax(share - counts / max(n_layers, 1)))] += 1\n        while counts.sum() > n_layers:\n            # забираем у самых мощных, не опуская никого ниже минимума\n            floor = 1 if n_layers >= len(self.nodes) else 0\n            cand = np.where(counts > floor)[0]\n            counts[cand[int(np.argmax(counts[cand]))]] -= 1\n        # узлы идут от слабого к сильному: слышит -> думает -> считает\n        order = np.argsort(caps)\n        layer = 0\n        for idx in order:\n            take = int(counts[idx])\n            self.nodes[idx].layers = list(range(layer, layer + take))\n            layer += take\n\n    @property\n    def active_nodes(self) -> List[Node]:\n        return [n for n in self.nodes if n.layers]\n\n    def topology(self) -> str:\n        rows = []\n        for n in sorted(self.nodes, key=lambda x: (x.layers or [99])[0]):\n            span = f"{n.layers[0]}–{n.layers[-1]}" if n.layers else "—"\n            rows.append(f"  {n.name:<22} слои {span:<8} мощность {n.capacity:>7.2f}")\n        return "\\n".join(rows)\n\n    # -------------------------------------------------------------- события\n    def join(self, state: DeviceState) -> None:\n        """Появилось новое устройство — Протей растекается."""\n        self.nodes.append(Node(state))\n        self._assign()\n\n    def leave(self, name: str) -> None:\n        """Устройство исчезло — Протей стягивается, ничего не теряя."""\n        before = len(self.nodes)\n        self.nodes = [n for n in self.nodes if n.name != name]\n        if len(self.nodes) == before:\n            raise KeyError(f"узел \'{name}\' не найден в рое")\n        if not self.nodes:\n            raise ValueError("нельзя удалить последний узел роя")\n        self._assign()\n\n    # ------------------------------------------------------------- инференс\n    @no_grad()\n    def forward(self, idx) -> Tensor:\n        """Прогон по цепочке узлов; между узлами передаётся только активация."""\n        d = self.model.width_dim(self.width)\n        x = self.model.embed(idx, d)\n        self.hops = 0\n        self.bytes_total = 0\n        chain = sorted(self.active_nodes, key=lambda n: n.layers[0])\n        for i, node in enumerate(chain):\n            for li in node.layers:\n                x = self.model.run_block(li, x, d)\n            if i < len(chain) - 1:\n                payload = int(np.prod(x.shape)) * 4      # fp32-активация\n                node.bytes_moved += payload\n                self.bytes_total += payload\n                self.hops += 1\n        return self.model.readout(x, d)\n\n    def transfer_report(self, idx) -> str:\n        """Сколько данных ушло по сети против размера самой модели."""\n        self.forward(idx)\n        weights = self.model.active_params(self.width) * 2 // 8   # 1.58-bit упаковка\n        return (f"прыжков между устройствами: {self.hops}, "\n                f"передано {self.bytes_total / 1024:.1f} КБ активаций "\n                f"(веса модели: {weights / 1024:.1f} КБ — они НЕ передаются)")\n'

_SOURCES['ultranet.proteus.train'] = '"""Matryoshka-обучение: один проход учит сразу все вложенные размеры.\n\nБез этого срез весов — просто обрезанная матрица, которая ничего не умеет.\nСмысл MatFormer именно в том, что каждый размер обучается явно.\n"""\nfrom __future__ import annotations\n\nimport time\nfrom typing import Dict, List, Optional, Sequence\n\nimport numpy as np\n\nfrom ..functional import cross_entropy, perplexity\nfrom ..optim import AdamW, CosineWarmup, Optimizer\nfrom .bytes import make_byte_batches\nfrom .matformer import MatFormer\n\n\ndef train_matryoshka(model: MatFormer, ids: Sequence[int], steps: int = 300,\n                     batch_size: int = 8, lr: float = 3e-3,\n                     widths: Optional[Sequence[float]] = None,\n                     exit_loss_weight: float = 0.3,\n                     grad_clip: float = 1.0, log_every: int = 50,\n                     verbose: bool = True) -> Dict[str, List[float]]:\n    """Обучить все вложенные размеры одновременно.\n\n    На каждом шаге считается loss для каждой ширины и суммируется, поэтому\n    градиент получают и малые срезы (они входят во все большие), и полная модель.\n    Ранние выходы обучаются вспомогательным loss — иначе early exit бесполезен.\n    """\n    widths = list(widths or model.cfg.widths)\n    block = model.cfg.block_size\n    opt = AdamW(model.parameters(), lr=lr, weight_decay=0.01)\n    sched = CosineWarmup(opt, warmup=max(10, steps // 10), total=steps)\n    history: Dict[str, List[float]] = {f"w{w}": [] for w in widths}\n    history["total"] = []\n\n    t0 = time.time()\n    for step in range(1, steps + 1):\n        xb, yb = make_byte_batches(ids, block, batch_size)\n        opt.zero_grad()\n        total = None\n        per_width = {}\n        for w in widths:\n            use_exits = exit_loss_weight > 0 and bool(model.cfg.exit_layers)\n            out = model(xb, width=w, return_exits=use_exits)\n            logits, exits = out if use_exits else (out, [])\n            loss = cross_entropy(logits, yb)\n            per_width[w] = loss.item()\n            term = loss\n            for _, ex_logits in exits:\n                term = term + cross_entropy(ex_logits, yb) * exit_loss_weight\n            total = term if total is None else total + term\n        total.backward()\n        opt.clip_grad_norm(grad_clip)\n        opt.step()\n        sched.step()\n\n        for w in widths:\n            history[f"w{w}"].append(per_width[w])\n        history["total"].append(float(total.item()))\n\n        if verbose and (step % log_every == 0 or step == 1):\n            parts = " | ".join(f"w{w}: {per_width[w]:.3f}" for w in widths)\n            print(f"  шаг {step:4d}/{steps} | {parts} | {time.time() - t0:.1f}s")\n\n    return history\n\n\ndef evaluate_widths(model: MatFormer, ids: Sequence[int], widths: Sequence[float],\n                    n_batches: int = 8, batch_size: int = 8,\n                    seed: int = 0) -> Dict[float, Dict[str, float]]:\n    """Замерить loss/перплексию каждого вложенного размера на одних данных."""\n    from ..tensor import no_grad\n\n    block = model.cfg.block_size\n    was = model.training\n    model.eval()\n    out: Dict[float, Dict[str, float]] = {}\n    with no_grad():\n        for w in widths:\n            losses = []\n            for i in range(n_batches):\n                xb, yb = make_byte_batches(ids, block, batch_size, seed=seed + i)\n                losses.append(cross_entropy(model(xb, width=w), yb).item())\n            mean = float(np.mean(losses))\n            out[w] = {\n                "loss": mean,\n                "ppl": perplexity(mean),\n                "bpb": mean / np.log(2),          # бит на байт — метрика байтовых LM\n                "active_params": float(model.active_params(w)),\n            }\n    model.train(was)\n    return out\n'

_SOURCES['ultranet.proteus.weights'] = '"""Идеальные веса Протея: семь техник вместо «просто чисел».\n\nКаждая техника убирает свой источник неидеальности и **измеряется**:\nотносительная ошибка `||w - ŵ|| / ||w||` и реальная цена в битах на вес.\n\n  1. Гиперсферическая нормализация — направление + масштаб.\n  2. Лог-полярное квантование — sign × 2^e × (1 + m/4), 7 бит, умножение = сдвиг.\n  3. RVQ — остаточные кодбуки, вложенная точность из одного хранилища.\n  4. Fisher-важность — важным весам больше бит, остальным меньше.\n  5. Фрактальная структура — слои порождаются из базового.\n  6. Комплексные веса — амплитуда + фаза.\n  7. Гиперсеть — веса порождаются из эмбеддинга задачи.\n"""\nfrom __future__ import annotations\n\nimport math\nfrom dataclasses import dataclass, field\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\nfrom ..nn import Module, Parameter\nfrom ..tensor import Tensor, get_rng\n\n\ndef rel_error(w: np.ndarray, hat: np.ndarray) -> float:\n    """Относительная ошибка восстановления: главная метрика качества весов."""\n    denom = float(np.linalg.norm(w))\n    if denom < 1e-12:\n        return 0.0\n    return float(np.linalg.norm(w - hat) / denom)\n\n\ndef cosine(w: np.ndarray, hat: np.ndarray) -> float:\n    a, b = w.ravel(), hat.ravel()\n    na, nb = np.linalg.norm(a), np.linalg.norm(b)\n    if na < 1e-12 or nb < 1e-12:\n        return 0.0\n    return float(np.dot(a, b) / (na * nb))\n\n\n# ═══════════════════════════════════ 1. Гиперсферическая нормализация\n@dataclass\nclass SphericalWeight:\n    """Вес = направление на единичной сфере + масштаб.\n\n    «Все веса имеют длину 1. Их различие — только в направлении».\n    Масштаб хранится отдельно в FP16 — по одному числу на строку.\n    """\n\n    directions: np.ndarray        # (rows, cols), каждая строка — единичная\n    scales: np.ndarray            # (rows,) в fp16\n\n    @classmethod\n    def from_weight(cls, w: np.ndarray, per_row: bool = True) -> "SphericalWeight":\n        w = np.asarray(w, dtype=np.float32)\n        if w.ndim == 1:\n            w = w[None, :]\n        axis = 1 if per_row else None\n        norms = np.linalg.norm(w, axis=axis, keepdims=True)\n        norms = np.maximum(norms, 1e-12)\n        dirs = (w / norms).astype(np.float32)\n        return cls(dirs, norms.squeeze(-1).astype(np.float16))\n\n    def to_weight(self) -> np.ndarray:\n        return (self.directions * self.scales.astype(np.float32)[:, None]).astype(np.float32)\n\n    def bits_per_weight(self, direction_bits: float) -> float:\n        n = self.directions.size\n        return direction_bits + (16.0 * self.scales.size / max(n, 1))\n\n    @property\n    def is_unit(self) -> bool:\n        return bool(np.allclose(np.linalg.norm(self.directions, axis=1), 1.0, atol=1e-5))\n\n\ndef slerp(a: np.ndarray, b: np.ndarray, t: float) -> np.ndarray:\n    """Плавный переход по дуге сферы между двумя направлениями."""\n    a = a / max(np.linalg.norm(a), 1e-12)\n    b = b / max(np.linalg.norm(b), 1e-12)\n    dot = float(np.clip(np.dot(a, b), -1.0, 1.0))\n    theta = math.acos(dot)\n    if theta < 1e-6:\n        return a.copy()\n    s = math.sin(theta)\n    return (math.sin((1 - t) * theta) / s) * a + (math.sin(t * theta) / s) * b\n\n\ndef angular_distance(a: np.ndarray, b: np.ndarray) -> float:\n    """Угол между весами = их семантическая близость."""\n    a = a / max(np.linalg.norm(a), 1e-12)\n    b = b / max(np.linalg.norm(b), 1e-12)\n    return float(math.acos(float(np.clip(np.dot(a, b), -1.0, 1.0))))\n\n\n# ═══════════════════════════════════════ 2. Лог-полярное квантование\n#: экспонента 4 бита (16 значений), мантисса 2 бита, знак 1 бит = 7 бит\nLOGPOLAR_BITS = 7\n_E_MIN, _E_MAX = -8, 7\n_M_LEVELS = 4\n\n\n@dataclass\nclass LogPolarWeight:\n    """w = sign × 2^e × (1 + m/4).\n\n    Умножение на 2^e — сдвиг. Умножение на (1 + m/4) — сдвиг и сложение.\n    Ни одного настоящего умножения.\n    """\n\n    sign: np.ndarray              # int8 {-1, +1}\n    exponent: np.ndarray          # int8 в [-8, 7] (относительно bias)\n    mantissa: np.ndarray          # uint8 в [0, 3]\n    zero_mask: np.ndarray         # bool: точные нули\n    shape: Tuple[int, ...]\n    bias: int = 0                 # общий сдвиг экспоненты на тензор\n\n    BITS = LOGPOLAR_BITS\n\n    @classmethod\n    def quantize(cls, w: np.ndarray) -> "LogPolarWeight":\n        w = np.asarray(w, dtype=np.float32)\n        a = np.abs(w)\n        zero = a < 1e-20\n        sign = np.where(w < 0, -1, 1).astype(np.int8)\n\n        safe = np.where(zero, 1.0, a)\n        # Окно экспоненты всего 16 значений. Без привязки к масштабу тензора\n        # веса мельче 2^-8 обнулялись целиком — сдвигаем окно под данные.\n        nz = a[~zero]\n        bias = 0\n        if nz.size:\n            top = int(np.floor(math.log2(float(nz.max()))))\n            bias = int(top - _E_MAX)\n        safe = safe / (2.0 ** bias)\n        e = np.floor(np.log2(safe)).astype(np.int32)\n        frac = safe / np.exp2(e.astype(np.float32)) - 1.0      # в [0, 1)\n        m = np.rint(frac * _M_LEVELS).astype(np.int32)\n        # мантисса переполнилась — переносим в экспоненту\n        carry = m >= _M_LEVELS\n        e = np.where(carry, e + 1, e)\n        m = np.where(carry, 0, m)\n        # выход за диапазон экспоненты — насыщаем, слишком малое считаем нулём\n        zero = zero | (e < _E_MIN)\n        e = np.clip(e, _E_MIN, _E_MAX)\n        return cls(sign, e.astype(np.int8), m.astype(np.uint8), zero, w.shape, bias)\n\n    def dequantize(self) -> np.ndarray:\n        val = (np.exp2(self.exponent.astype(np.float32) + self.bias)\n               * (1.0 + self.mantissa.astype(np.float32) / _M_LEVELS)\n               * self.sign.astype(np.float32))\n        return np.where(self.zero_mask, 0.0, val).astype(np.float32)\n\n    @property\n    def n_weights(self) -> int:\n        return int(np.prod(self.shape))\n\n    def nbytes(self) -> int:\n        return int(math.ceil(self.n_weights * self.BITS / 8))\n\n    def shift_multiply(self, x: np.ndarray) -> np.ndarray:\n        """Умножение через сдвиги: x * w = ((x << e) + (x << e) * m/4) * sign.\n\n        Демонстрирует, что настоящего умножения не требуется.\n        """\n        base = np.ldexp(x, self.exponent.astype(np.int32) + self.bias)   # сдвиг\n        acc = base.copy()\n        m = self.mantissa.astype(np.int32)\n        for bit, frac in ((1, 0.25), (2, 0.5)):                 # m/4 = биты m\n            acc = acc + np.where((m & bit) != 0, base * frac, 0.0)\n        out = acc * self.sign.astype(np.float32)\n        return np.where(self.zero_mask, 0.0, out).astype(np.float32)\n\n\n# ═══════════════════════════ 3. Остаточное векторное квантование (RVQ)\nclass RVQ:\n    """w ≈ c₁ + c₂ + c₃ + … — каждый кодбук уточняет остаток предыдущего.\n\n    Главное свойство — вложенность: можно взять только c₁ и получить\n    грубые, но рабочие веса; добавить c₂ — точнее. Одно хранилище, много\n    точностей, без отдельных версий модели.\n    """\n\n    def __init__(self, dim: int = 4, size: int = 256, stages: int = 3,\n                 iters: int = 12, seed: int = 0) -> None:\n        self.dim, self.size, self.stages, self.iters = dim, size, stages, iters\n        self.rng = np.random.default_rng(seed)\n        self.codebooks: List[np.ndarray] = []\n        self.shape: Optional[Tuple[int, ...]] = None\n        self.pad = 0\n\n    # ----------------------------------------------------------- обучение\n    def _to_vectors(self, w: np.ndarray) -> np.ndarray:\n        flat = np.asarray(w, dtype=np.float32).ravel()\n        self.pad = (-flat.size) % self.dim\n        if self.pad:\n            flat = np.concatenate([flat, np.zeros(self.pad, dtype=np.float32)])\n        return flat.reshape(-1, self.dim)\n\n    def _kmeans(self, x: np.ndarray) -> np.ndarray:\n        k = min(self.size, len(x))\n        idx = self.rng.choice(len(x), size=k, replace=False)\n        cb = x[idx].copy()\n        for _ in range(self.iters):\n            d = ((x[:, None, :] - cb[None, :, :]) ** 2).sum(-1)\n            assign = d.argmin(1)\n            for j in range(k):\n                sel = x[assign == j]\n                if len(sel):\n                    cb[j] = sel.mean(0)\n        if k < self.size:                       # добить кодбук до размера\n            cb = np.concatenate([cb, np.zeros((self.size - k, self.dim), np.float32)])\n        return cb.astype(np.float32)\n\n    def fit(self, w: np.ndarray, sample: int = 4096) -> "RVQ":\n        self.shape = np.asarray(w).shape\n        vecs = self._to_vectors(w)\n        residual = vecs.copy()\n        self.codebooks = []\n        for _ in range(self.stages):\n            sub = residual\n            if len(sub) > sample:\n                sub = residual[self.rng.choice(len(residual), sample, replace=False)]\n            cb = self._kmeans(sub)\n            self.codebooks.append(cb)\n            idx = self._assign(residual, cb)\n            residual = residual - cb[idx]\n        return self\n\n    @staticmethod\n    def _assign(x: np.ndarray, cb: np.ndarray, chunk: int = 8192) -> np.ndarray:\n        out = np.empty(len(x), dtype=np.int32)\n        for s in range(0, len(x), chunk):\n            part = x[s:s + chunk]\n            d = ((part[:, None, :] - cb[None, :, :]) ** 2).sum(-1)\n            out[s:s + chunk] = d.argmin(1)\n        return out\n\n    # -------------------------------------------------------------- коды\n    def encode(self, w: np.ndarray) -> List[np.ndarray]:\n        vecs = self._to_vectors(w)\n        residual = vecs.copy()\n        codes = []\n        for cb in self.codebooks:\n            idx = self._assign(residual, cb)\n            codes.append(idx)\n            residual = residual - cb[idx]\n        return codes\n\n    def decode(self, codes: Sequence[np.ndarray], stages: Optional[int] = None\n               ) -> np.ndarray:\n        n = len(codes) if stages is None else min(stages, len(codes))\n        total = np.zeros((len(codes[0]), self.dim), dtype=np.float32)\n        for i in range(n):\n            total += self.codebooks[i][codes[i]]\n        flat = total.ravel()\n        if self.pad:\n            flat = flat[:-self.pad]\n        return flat.reshape(self.shape).astype(np.float32)\n\n    # -------------------------------------------------------------- цена\n    def bits_per_weight(self, stages: Optional[int] = None) -> float:\n        n = self.stages if stages is None else stages\n        return n * math.log2(self.size) / self.dim\n\n    def codebook_bytes(self) -> int:\n        return sum(cb.size * 2 for cb in self.codebooks)   # fp16\n\n    def error_by_stage(self, w: np.ndarray) -> List[Tuple[int, float, float]]:\n        """(число кодбуков, бит/вес, относительная ошибка) — вложенность в цифрах."""\n        codes = self.encode(w)\n        out = []\n        for s in range(1, len(codes) + 1):\n            out.append((s, self.bits_per_weight(s), rel_error(w, self.decode(codes, s))))\n        return out\n\n\n# ═══════════════════════════════════ 4. Важность через Fisher Information\n@dataclass\nclass FisherPlan:\n    """Сколько бит дать каждой группе весов."""\n\n    bits: np.ndarray              # бит на элемент\n    thresholds: Tuple[float, ...]\n    mean_bits: float\n\n\nclass FisherImportance:\n    """F_i = E[(∂ log p / ∂ w_i)²] — мера важности веса для задачи.\n\n    Важные веса защищены от квантования, неважные дёшевы.\n    """\n\n    def __init__(self, levels: Sequence[int] = (2, 4, 8, 16)) -> None:\n        self.levels = tuple(sorted(levels))\n        self.fisher: Dict[str, np.ndarray] = {}\n\n    def accumulate(self, model: Module) -> None:\n        """Накопить квадраты градиентов после backward()."""\n        for name, p in model.named_parameters():\n            if p.grad is None:\n                continue\n            self.fisher[name] = self.fisher.get(name, 0.0) + p.grad ** 2\n\n    def plan_for(self, name: str, quantiles: Sequence[float] = (0.5, 0.8, 0.95)\n                 ) -> Optional[FisherPlan]:\n        """Раздать биты по квантилям важности."""\n        f = self.fisher.get(name)\n        if f is None:\n            return None\n        qs = np.quantile(f, quantiles)\n        bits = np.full(f.shape, self.levels[0], dtype=np.int32)\n        for lvl, thr in zip(self.levels[1:], qs):\n            bits = np.where(f > thr, lvl, bits)\n        return FisherPlan(bits, tuple(float(q) for q in qs), float(bits.mean()))\n\n    @staticmethod\n    def quantize_adaptive(w: np.ndarray, bits: np.ndarray) -> np.ndarray:\n        """Квантование с индивидуальной разрядностью на элемент.\n\n        Масштаб считается ОТДЕЛЬНО для каждой битовой группы: общий масштаб\n        по всей матрице уничтожал 2-битную группу (шаг оказывался больше\n        самих весов) и адаптивность проигрывала равномерной сетке.\n        """\n        w = np.asarray(w, dtype=np.float32)\n        out = np.empty_like(w)\n        for b in np.unique(bits):\n            mask = bits == b\n            part = w[mask]\n            if not part.size:\n                continue\n            scale = float(np.abs(part).max()) or 1.0\n            levels = max(2 ** int(b) - 1, 1)\n            step = 2.0 * scale / levels\n            out[mask] = np.clip(np.rint(part / step) * step, -scale, scale)\n        return out\n\n    def uniform_baseline(self, w: np.ndarray, bits: float) -> np.ndarray:\n        """Равномерная сетка той же средней стоимости — честный конкурент."""\n        return self.quantize_adaptive(w, np.full(w.shape, int(round(bits))))\n\n    @staticmethod\n    def weighted_error(w: np.ndarray, hat: np.ndarray, fisher: np.ndarray) -> float:\n        """Fisher-взвешенная ошибка ≈ реальный прирост loss (2-й порядок).\n\n        Именно она определяет «качество», а не голая L2: ошибка в неважном\n        весе почти бесплатна, ошибка в важном — дорога.\n        """\n        num = float(np.sum(fisher * (w - hat) ** 2))\n        den = float(np.sum(fisher * w ** 2))\n        return math.sqrt(num / den) if den > 0 else 0.0\n\n\n# ═══════════════════════════════════════════ 5. Фрактальная структура\nclass FractalStack:\n    """W_n = f(W_{n-1}): слои порождаются из базового рекурсивно.\n\n    Храним базовый слой и маленькое преобразование — вместо N слоёв.\n    Можно дорастить новые слои, применив f ещё раз.\n    """\n\n    def __init__(self, base: np.ndarray, n_layers: int, seed: int = 0) -> None:\n        self.base = np.asarray(base, dtype=np.float32)\n        self.n_layers = n_layers\n        r, c = self.base.shape\n        rng = np.random.default_rng(seed)\n        # f(W) = A @ W @ B + g — компактное обучаемое преобразование\n        self.A = np.eye(r, dtype=np.float32) + rng.normal(0, 0.01, (r, r)).astype(np.float32)\n        self.B = np.eye(c, dtype=np.float32) + rng.normal(0, 0.01, (c, c)).astype(np.float32)\n        self.gain = np.ones(n_layers, dtype=np.float32)\n\n    def generate(self, n: Optional[int] = None) -> List[np.ndarray]:\n        n = self.n_layers if n is None else n\n        out, w = [], self.base.copy()\n        for i in range(n):\n            g = self.gain[i] if i < len(self.gain) else 1.0\n            out.append((w * g).astype(np.float32))\n            w = self.A @ w @ self.B\n        return out\n\n    def fit(self, targets: Sequence[np.ndarray], steps: int = 300,\n            lr: float = 0.02) -> List[float]:\n        """Подогнать A, B, gain под реальный стек слоёв (градиентный спуск)."""\n        hist: List[float] = []\n        self.gain = np.ones(len(targets), dtype=np.float32)\n        for _ in range(steps):\n            gen = self.generate(len(targets))\n            loss = float(np.mean([np.mean((g - t) ** 2) for g, t in zip(gen, targets)]))\n            hist.append(loss)\n            # численный градиент по gain (дёшево и устойчиво)\n            for i, (g, t) in enumerate(zip(gen, targets)):\n                raw = g / max(self.gain[i], 1e-8)\n                denom = float(np.sum(raw * raw)) + 1e-8\n                self.gain[i] = float(np.sum(raw * t) / denom)\n            # шаг по A и B в сторону уменьшения ошибки\n            gen = self.generate(len(targets))\n            dA = np.zeros_like(self.A)\n            dB = np.zeros_like(self.B)\n            w = self.base.copy()\n            for i in range(1, len(targets)):\n                prev = w\n                w = self.A @ w @ self.B\n                err = (w * self.gain[i] - targets[i]) * self.gain[i]\n                dA += err @ (prev @ self.B).T\n                dB += (self.A @ prev).T @ err\n            n = max(len(targets) - 1, 1)\n            self.A -= lr * dA / n\n            self.B -= lr * dB / n\n        return hist\n\n    # -------------------------------------------------------------- цена\n    def stored_params(self) -> int:\n        return self.base.size + self.A.size + self.B.size + self.gain.size\n\n    def generated_params(self) -> int:\n        return self.base.size * self.n_layers\n\n    def compression(self) -> float:\n        return self.generated_params() / max(self.stored_params(), 1)\n\n    def error_vs(self, targets: Sequence[np.ndarray]) -> float:\n        gen = self.generate(len(targets))\n        return float(np.mean([rel_error(t, g) for t, g in zip(gen, targets)]))\n\n\n# ═══════════════════════════════════════ 6. Комплексные веса с фазой\n@dataclass\nclass ComplexWeight:\n    """w = r·e^{iθ}: амплитуда (важность) + фаза (отношение).\n\n    Фазу квантуем грубо (3 бита = 8 направлений), амплитуду точнее (4 бита).\n    Итого 7 бит на комплексное число = 3.5 бита на действительный вес.\n    """\n\n    amp_code: np.ndarray          # uint8, amp_bits\n    phase_code: np.ndarray        # uint8, phase_bits\n    scale: float\n    shape: Tuple[int, ...]\n    amp_bits: int = 4\n    phase_bits: int = 3\n\n    @classmethod\n    def from_pairs(cls, w: np.ndarray, amp_bits: int = 4, phase_bits: int = 3\n                   ) -> "ComplexWeight":\n        """Пары соседних весов -> комплексные числа."""\n        flat = np.asarray(w, dtype=np.float32).ravel()\n        if flat.size % 2:\n            flat = np.concatenate([flat, np.zeros(1, np.float32)])\n        z = flat[0::2] + 1j * flat[1::2]\n        amp = np.abs(z)\n        phase = np.angle(z) % (2 * np.pi)\n        scale = float(amp.max()) or 1.0\n        a_levels = 2 ** amp_bits - 1\n        p_levels = 2 ** phase_bits\n        amp_code = np.rint(amp / scale * a_levels).astype(np.uint8)\n        phase_code = (np.rint(phase / (2 * np.pi) * p_levels).astype(np.int32)\n                      % p_levels).astype(np.uint8)\n        return cls(amp_code, phase_code, scale, w.shape, amp_bits, phase_bits)\n\n    def to_weight(self) -> np.ndarray:\n        a_levels = 2 ** self.amp_bits - 1\n        p_levels = 2 ** self.phase_bits\n        amp = self.amp_code.astype(np.float32) / a_levels * self.scale\n        phase = self.phase_code.astype(np.float32) / p_levels * 2 * np.pi\n        z = amp * np.exp(1j * phase)\n        flat = np.empty(z.size * 2, dtype=np.float32)\n        flat[0::2] = z.real\n        flat[1::2] = z.imag\n        n = int(np.prod(self.shape))\n        return flat[:n].reshape(self.shape)\n\n    def bits_per_weight(self) -> float:\n        return (self.amp_bits + self.phase_bits) / 2.0\n\n\ndef complex_matmul(xr: np.ndarray, xi: np.ndarray, wr: np.ndarray, wi: np.ndarray\n                   ) -> Tuple[np.ndarray, np.ndarray]:\n    """Комплексное умножение = поворот + масштаб (богаче простого масштаба)."""\n    return xr @ wr - xi @ wi, xr @ wi + xi @ wr\n\n\n# ═══════════════════════════════════════ 7. Гиперсеть для генерации весов\nclass HyperNetwork(Module):\n    """Маленькая сеть порождает веса большой: W = H(task_embedding).\n\n    Ключ к реальной экономии — генерировать веса ПОСТРОЧНО из координат.\n    Наивная схема (hidden × rows × rank) сама весит больше порождаемой\n    матрицы; здесь размер гиперсети не зависит от размеров выхода вообще,\n    поэтому сжатие растёт вместе с моделью.\n\n    Одна гиперсеть — бесконечно много моделей: поменял эмбеддинг —\n    поменял модель, без переобучения. Порождает low-rank факторы,\n    поэтому совместима с LoRA-персонализацией.\n    """\n\n    POS_DIM = 8       # синусоидальные координаты строк/столбцов: 0 параметров\n\n    def __init__(self, embed_dim: int, out_rows: int, out_cols: int,\n                 rank: int = 4, hidden: int = 32) -> None:\n        super().__init__()\n        self.embed_dim, self.rows, self.cols, self.rank = embed_dim, out_rows, out_cols, rank\n        rng = get_rng()\n        d_in = embed_dim + self.POS_DIM\n        self.w1 = Parameter(rng.standard_normal((d_in, hidden)).astype(np.float32)\n                            / math.sqrt(d_in))\n        self.b1 = Parameter(np.zeros(hidden, dtype=np.float32))\n        self.w2 = Parameter(rng.standard_normal((hidden, rank)).astype(np.float32)\n                            / math.sqrt(hidden))\n        self.b2 = Parameter(np.zeros(rank, dtype=np.float32))\n        self.scale = Parameter(np.array([0.1], dtype=np.float32))\n        self.tasks: Dict[str, np.ndarray] = {}\n        self._pos_cache: Dict[int, np.ndarray] = {}\n\n    # --------------------------------------------------------- координаты\n    def _positions(self, n: int) -> np.ndarray:\n        """Синусоидальные координаты — не хранятся, а вычисляются."""\n        if n in self._pos_cache:\n            return self._pos_cache[n]\n        idx = np.arange(n, dtype=np.float32)[:, None]\n        freqs = np.exp2(np.arange(self.POS_DIM // 2, dtype=np.float32))[None, :]\n        ang = idx / max(n, 1) * freqs * np.pi\n        pos = np.concatenate([np.sin(ang), np.cos(ang)], axis=1).astype(np.float32)\n        self._pos_cache[n] = pos\n        return pos\n\n    # ------------------------------------------------------------ задачи\n    def register_task(self, name: str, seed: Optional[int] = None) -> np.ndarray:\n        rng = np.random.default_rng(seed) if seed is not None else get_rng()\n        e = rng.standard_normal(self.embed_dim).astype(np.float32)\n        e /= max(np.linalg.norm(e), 1e-9)\n        self.tasks[name] = e\n        return e\n\n    def embedding(self, task: str) -> np.ndarray:\n        if task not in self.tasks:\n            self.register_task(task, seed=abs(hash(task)) % (2 ** 31))\n        return self.tasks[task]\n\n    # ----------------------------------------------------------- forward\n    def _factor(self, e: np.ndarray, n: int) -> np.ndarray:\n        """Сгенерировать n строк ранга rank из эмбеддинга задачи."""\n        pos = self._positions(n)\n        x = np.concatenate([np.repeat(e[None, :], n, axis=0), pos], axis=1)\n        h = np.tanh(x @ self.w1.data + self.b1.data)\n        return h @ self.w2.data + self.b2.data\n\n    def generate(self, task_or_vec) -> np.ndarray:\n        """Сгенерировать матрицу весов под задачу."""\n        e = (self.embedding(task_or_vec) if isinstance(task_or_vec, str)\n             else np.asarray(task_or_vec, dtype=np.float32))\n        a = self._factor(e, self.rows)                      # (rows, rank)\n        b = self._factor(-e, self.cols).T                   # (rank, cols)\n        return (a @ b * float(self.scale.data[0])).astype(np.float32)\n\n    def forward(self, task_or_vec) -> Tensor:\n        return Tensor(self.generate(task_or_vec))\n\n    # -------------------------------------------------------------- цена\n    def n_params(self) -> int:\n        return sum(p.size for p in self.parameters())\n\n    def generated_params(self) -> int:\n        return self.rows * self.cols\n\n    def compression(self) -> float:\n        return self.generated_params() / max(self.n_params(), 1)\n\n    def interpolate(self, task_a: str, task_b: str, t: float) -> np.ndarray:\n        """Между задачами можно плавно переходить — модель тоже плавная."""\n        return self.generate(slerp(self.embedding(task_a), self.embedding(task_b), t))\n\n\n# ═══════════════════════════════════════════════ сводный пайплайн\n@dataclass\nclass WeightReport:\n    """Результат сжатия одной матрицы весов."""\n\n    method: str\n    bits_per_weight: float\n    rel_error: float\n    cosine: float\n    bytes_used: int\n\n    @property\n    def vs_fp16(self) -> float:\n        return 16.0 / max(self.bits_per_weight, 1e-9)\n\n    def __str__(self) -> str:\n        return (f"{self.method:<28} {self.bits_per_weight:>5.2f} бит/вес  "\n                f"ошибка {self.rel_error * 100:>6.2f}%  cos {self.cosine:.4f}  "\n                f"x{self.vs_fp16:.1f} к FP16")\n\n\ndef compare_methods(w: np.ndarray, rvq_stages: int = 3,\n                    rvq_dim: int = 4) -> List[WeightReport]:\n    """Честное сравнение всех техник на одной матрице."""\n    w = np.asarray(w, dtype=np.float32)\n    n = w.size\n    out: List[WeightReport] = []\n\n    # базовая линия: ternary\n    scale = float(np.abs(w).mean()) or 1.0\n    tern = np.clip(np.rint(w / scale), -1, 1) * scale\n    out.append(WeightReport("ternary (1.58-bit)", 2.0, rel_error(w, tern),\n                            cosine(w, tern), int(n * 2 / 8)))\n\n    # fp16\n    h = w.astype(np.float16).astype(np.float32)\n    out.append(WeightReport("FP16", 16.0, rel_error(w, h), cosine(w, h), n * 2))\n\n    # лог-полярное\n    lp = LogPolarWeight.quantize(w)\n    d = lp.dequantize()\n    out.append(WeightReport("лог-полярное (7 бит)", 7.0, rel_error(w, d),\n                            cosine(w, d), lp.nbytes()))\n\n    # гиперсферическое + лог-полярное\n    sph = SphericalWeight.from_weight(w)\n    lp2 = LogPolarWeight.quantize(sph.directions)\n    rec = (lp2.dequantize() * sph.scales.astype(np.float32)[:, None])\n    out.append(WeightReport("сфера + лог-полярное", sph.bits_per_weight(7.0),\n                            rel_error(w, rec), cosine(w, rec), lp2.nbytes()))\n\n    # RVQ по стадиям\n    rvq = RVQ(dim=rvq_dim, stages=rvq_stages).fit(w)\n    codes = rvq.encode(w)\n    for s in range(1, rvq_stages + 1):\n        rec = rvq.decode(codes, s)\n        out.append(WeightReport(f"RVQ, {s} кодбук(а)", rvq.bits_per_weight(s),\n                                rel_error(w, rec), cosine(w, rec),\n                                int(n * rvq.bits_per_weight(s) / 8) + rvq.codebook_bytes()))\n\n    # комплексные\n    cw = ComplexWeight.from_pairs(w)\n    rec = cw.to_weight()\n    out.append(WeightReport("комплексные (амп+фаза)", cw.bits_per_weight(),\n                            rel_error(w, rec), cosine(w, rec),\n                            int(n * cw.bits_per_weight() / 8)))\n    return out\n'

_SOURCES['ultranet.tensor'] = '"""Автоград-движок: Tensor с обратным распространением по динамическому графу.\n\nЯдро всей библиотеки. Каждая операция строит узел графа и запоминает,\nкак протолкнуть градиент назад (замыкание `_backward`).\n"""\nfrom __future__ import annotations\n\nfrom typing import Iterable, Optional, Sequence, Tuple, Union\n\nimport numpy as np\n\nArrayLike = Union["Tensor", np.ndarray, float, int, list]\n\n# ------------------------------------------------------------------ случайность\n_RNG = np.random.default_rng()\n\n\ndef manual_seed(seed: int) -> None:\n    """Зафиксировать все источники случайности библиотеки (инициализация, dropout).\n\n    >>> un.manual_seed(42)   # два запуска дадут идентичные веса и маски dropout\n    """\n    global _RNG\n    _RNG = np.random.default_rng(seed)\n    np.random.seed(seed)\n\n\ndef get_rng() -> np.random.Generator:\n    """Текущий генератор библиотеки (используется слоями и dropout)."""\n    return _RNG\n\n\n# --------------------------------------------------------------- режим градиентов\n_GRAD_ENABLED = True\n\n\ndef is_grad_enabled() -> bool:\n    return _GRAD_ENABLED\n\n\nclass no_grad:\n    """Контекст/декоратор, отключающий построение графа (быстрый инференс).\n\n    >>> with no_grad():\n    ...     logits = model(x)\n    """\n\n    def __enter__(self) -> "no_grad":\n        global _GRAD_ENABLED\n        self._prev = _GRAD_ENABLED\n        _GRAD_ENABLED = False\n        return self\n\n    def __exit__(self, *exc) -> bool:\n        global _GRAD_ENABLED\n        _GRAD_ENABLED = self._prev\n        return False\n\n    def __call__(self, fn):\n        def wrapper(*a, **kw):\n            with no_grad():\n                return fn(*a, **kw)\n\n        return wrapper\n\n\ndef _unbroadcast(grad: np.ndarray, shape: Tuple[int, ...]) -> np.ndarray:\n    """Свернуть градиент к исходной форме операнда после broadcasting."""\n    if grad.shape == shape:\n        return grad\n    # лишние ведущие оси\n    while grad.ndim > len(shape):\n        grad = grad.sum(axis=0)\n    # оси, растянутые из 1\n    for i, dim in enumerate(shape):\n        if dim == 1 and grad.shape[i] != 1:\n            grad = grad.sum(axis=i, keepdims=True)\n    return grad.reshape(shape)\n\n\ndef _is_basic_index(idx) -> bool:\n    """True, если индекс — базовый (срезы/int/None/Ellipsis) и не дублирует элементы."""\n    items = idx if isinstance(idx, tuple) else (idx,)\n    for i in items:\n        if not (isinstance(i, (slice, int, np.integer)) or i is Ellipsis or i is None):\n            return False\n    return True\n\n\nclass Tensor:\n    """N-мерный массив с автоматическим дифференцированием."""\n\n    __slots__ = ("data", "grad", "requires_grad", "_backward", "_prev", "_op")\n\n    def __init__(\n        self,\n        data: ArrayLike,\n        requires_grad: bool = False,\n        _children: Sequence["Tensor"] = (),\n        _op: str = "",\n    ) -> None:\n        if isinstance(data, Tensor):\n            data = data.data\n        self.data = np.asarray(data, dtype=np.float32)\n        self.requires_grad = requires_grad\n        self.grad: Optional[np.ndarray] = None\n        self._backward = lambda: None\n        self._prev = tuple(_children)\n        self._op = _op\n\n    # ---------------------------------------------------------------- утилиты\n    @property\n    def shape(self) -> Tuple[int, ...]:\n        return self.data.shape\n\n    @property\n    def ndim(self) -> int:\n        return self.data.ndim\n\n    @property\n    def size(self) -> int:\n        return self.data.size\n\n    @property\n    def T(self) -> "Tensor":\n        return self.transpose()\n\n    def __repr__(self) -> str:  # pragma: no cover - косметика\n        return f"Tensor(shape={self.shape}, requires_grad={self.requires_grad})\\n{self.data}"\n\n    def __len__(self) -> int:\n        return self.shape[0]\n\n    def item(self) -> float:\n        return float(self.data.reshape(-1)[0])\n\n    def numpy(self) -> np.ndarray:\n        return self.data\n\n    def detach(self) -> "Tensor":\n        return Tensor(self.data, requires_grad=False)\n\n    def zero_grad(self) -> None:\n        self.grad = None\n\n    @staticmethod\n    def _ensure(x: ArrayLike) -> "Tensor":\n        return x if isinstance(x, Tensor) else Tensor(x)\n\n    def _make(self, data: np.ndarray, parents: Sequence["Tensor"], op: str) -> "Tensor":\n        req = _GRAD_ENABLED and any(p.requires_grad for p in parents)\n        return Tensor(data, requires_grad=req, _children=parents if req else (), _op=op)\n\n    def _accum(self, g: np.ndarray, shared: bool = True) -> None:\n        """Накопить градиент.\n\n        shared=True  — `g` может быть чужим буфером (out.grad или его view),\n                       поэтому при первом присваивании делается копия.\n        shared=False — `g` только что вычислен этой операцией и больше нигде\n                       не используется, копию можно не делать (быстрый путь).\n        """\n        if not self.requires_grad:\n            return\n        # быстрый путь: форма уже совпадает (самый частый случай)\n        if type(g) is np.ndarray and g.shape == self.data.shape:\n            if g.dtype != np.float32:\n                g = g.astype(np.float32, copy=False)\n        else:\n            g = _unbroadcast(np.asarray(g, dtype=np.float32), self.shape)\n        if self.grad is None:\n            # Копия обязательна: некоторые _backward отдают out.grad (или его view)\n            # сразу нескольким родителям — без копии градиенты «слипнутся»,\n            # и внешняя запись вида `p.grad *= s` повредит чужой тензор.\n            self.grad = g.copy() if shared else g\n        else:\n            self.grad += g  # in-place: накопление без лишней аллокации\n\n    # ------------------------------------------------------------- арифметика\n    def __add__(self, other: ArrayLike) -> "Tensor":\n        other = self._ensure(other)\n        out = self._make(self.data + other.data, (self, other), "+")\n\n        def _backward() -> None:\n            self._accum(out.grad)\n            other._accum(out.grad)\n\n        out._backward = _backward\n        return out\n\n    def __mul__(self, other: ArrayLike) -> "Tensor":\n        other = self._ensure(other)\n        out = self._make(self.data * other.data, (self, other), "*")\n\n        def _backward() -> None:\n            self._accum(out.grad * other.data, shared=False)\n            other._accum(out.grad * self.data, shared=False)\n\n        out._backward = _backward\n        return out\n\n    def __pow__(self, p: float) -> "Tensor":\n        out = self._make(self.data ** p, (self,), f"**{p}")\n\n        def _backward() -> None:\n            self._accum(out.grad * p * self.data ** (p - 1), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def __matmul__(self, other: ArrayLike) -> "Tensor":\n        other = self._ensure(other)\n        out = self._make(self.data @ other.data, (self, other), "@")\n\n        def _backward() -> None:\n            g = out.grad\n            a, b = self.data, other.data\n            ga = g @ np.swapaxes(b, -1, -2)\n            self._accum(_unbroadcast(ga, a.shape), shared=False)\n\n            # Частый случай: batched-вход (B, T, K) на 2D-веса (K, N).\n            # Наивно это batched matmul (B, K, N) с последующей суммой по\n            # батчу — восьмикратно лишняя работа и лишний большой буфер.\n            # Свёртка батча в строки даёт ровно тот же результат одним\n            # вызовом BLAS (x2.6 на типичной форме).\n            if b.ndim == 2 and a.ndim > 2:\n                gb = a.reshape(-1, a.shape[-1]).T @ g.reshape(-1, g.shape[-1])\n            else:\n                gb = _unbroadcast(np.swapaxes(a, -1, -2) @ g, b.shape)\n            other._accum(gb, shared=False)\n\n        out._backward = _backward\n        return out\n\n    def __neg__(self) -> "Tensor":\n        return self * -1.0\n\n    def __sub__(self, other: ArrayLike) -> "Tensor":\n        return self + (-self._ensure(other))\n\n    def __truediv__(self, other: ArrayLike) -> "Tensor":\n        return self * (self._ensure(other) ** -1.0)\n\n    def __radd__(self, other: ArrayLike) -> "Tensor":\n        return self + other\n\n    def __rmul__(self, other: ArrayLike) -> "Tensor":\n        return self * other\n\n    def __rsub__(self, other: ArrayLike) -> "Tensor":\n        return self._ensure(other) + (-self)\n\n    def __rtruediv__(self, other: ArrayLike) -> "Tensor":\n        return self._ensure(other) * (self ** -1.0)\n\n    def __rmatmul__(self, other: ArrayLike) -> "Tensor":\n        return self._ensure(other) @ self\n\n    def __getitem__(self, idx) -> "Tensor":\n        out = self._make(self.data[idx], (self,), "getitem")\n        # Базовая индексация (срезы/int/Ellipsis) не может повторять элементы,\n        # поэтому градиент пишется прямым присваиванием — np.add.at на порядок медленнее\n        # и нужен только для «фантазийной» индексации массивами.\n        basic = _is_basic_index(idx)\n\n        def _backward() -> None:\n            g = np.zeros_like(self.data)\n            if basic:\n                g[idx] = out.grad\n            else:\n                np.add.at(g, idx, out.grad)\n            self._accum(g, shared=False)\n\n        out._backward = _backward\n        return out\n\n    # ----------------------------------------------------------------- формы\n    def reshape(self, *shape: int) -> "Tensor":\n        if len(shape) == 1 and isinstance(shape[0], (tuple, list)):\n            shape = tuple(shape[0])\n        out = self._make(self.data.reshape(shape), (self,), "reshape")\n\n        def _backward() -> None:\n            self._accum(out.grad.reshape(self.shape))\n\n        out._backward = _backward\n        return out\n\n    def view(self, *shape: int) -> "Tensor":\n        return self.reshape(*shape)\n\n    def flatten(self, start_dim: int = 1) -> "Tensor":\n        shape = self.shape[:start_dim] + (-1,)\n        return self.reshape(*shape)\n\n    def transpose(self, *axes: int) -> "Tensor":\n        if not axes:\n            axes = tuple(range(self.ndim))[::-1]\n        out = self._make(self.data.transpose(axes), (self,), "transpose")\n        inv = np.argsort(axes)\n\n        def _backward() -> None:\n            self._accum(out.grad.transpose(inv))\n\n        out._backward = _backward\n        return out\n\n    def swapaxes(self, a: int, b: int) -> "Tensor":\n        axes = list(range(self.ndim))\n        axes[a], axes[b] = axes[b], axes[a]\n        return self.transpose(*axes)\n\n    # ---------------------------------------------------------------- редукции\n    def sum(self, axis: Optional[Union[int, Tuple[int, ...]]] = None, keepdims: bool = False) -> "Tensor":\n        out = self._make(self.data.sum(axis=axis, keepdims=keepdims), (self,), "sum")\n\n        def _backward() -> None:\n            g = out.grad\n            if axis is not None and not keepdims:\n                g = np.expand_dims(g, axis)\n            self._accum(np.broadcast_to(g, self.shape).copy(), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def mean(self, axis: Optional[Union[int, Tuple[int, ...]]] = None, keepdims: bool = False) -> "Tensor":\n        n = self.size if axis is None else np.prod([self.shape[a] for a in np.atleast_1d(axis)])\n        return self.sum(axis=axis, keepdims=keepdims) * (1.0 / float(n))\n\n    def var(self, axis: Optional[int] = None, keepdims: bool = False) -> "Tensor":\n        mu = self.mean(axis=axis, keepdims=True)\n        return ((self - mu) ** 2).mean(axis=axis, keepdims=keepdims)\n\n    def max(self, axis: Optional[int] = None, keepdims: bool = False) -> "Tensor":\n        res = self.data.max(axis=axis, keepdims=True)\n        out_data = res if keepdims else res.squeeze(axis) if axis is not None else res.reshape(())\n        out = self._make(out_data, (self,), "max")\n        mask = (self.data == res).astype(np.float32)\n        mask /= mask.sum(axis=axis, keepdims=True)\n\n        def _backward() -> None:\n            g = out.grad\n            if axis is not None and not keepdims:\n                g = np.expand_dims(g, axis)\n            self._accum(mask * g, shared=False)\n\n        out._backward = _backward\n        return out\n\n    # -------------------------------------------------------------- нелинейности\n    def exp(self) -> "Tensor":\n        out = self._make(np.exp(self.data), (self,), "exp")\n\n        def _backward() -> None:\n            self._accum(out.grad * out.data, shared=False)\n\n        out._backward = _backward\n        return out\n\n    def log(self) -> "Tensor":\n        out = self._make(np.log(np.clip(self.data, 1e-12, None)), (self,), "log")\n\n        def _backward() -> None:\n            self._accum(out.grad / np.clip(self.data, 1e-12, None), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def sqrt(self) -> "Tensor":\n        return self ** 0.5\n\n    def relu(self) -> "Tensor":\n        out = self._make(np.maximum(self.data, 0.0), (self,), "relu")\n\n        def _backward() -> None:\n            self._accum(out.grad * (self.data > 0), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def leaky_relu(self, slope: float = 0.01) -> "Tensor":\n        out = self._make(np.where(self.data > 0, self.data, slope * self.data), (self,), "leaky_relu")\n\n        def _backward() -> None:\n            self._accum(out.grad * np.where(self.data > 0, 1.0, slope), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def tanh(self) -> "Tensor":\n        t = np.tanh(self.data)\n        out = self._make(t, (self,), "tanh")\n\n        def _backward() -> None:\n            self._accum(out.grad * (1 - t * t), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def sigmoid(self) -> "Tensor":\n        s = 1.0 / (1.0 + np.exp(-self.data))\n        out = self._make(s, (self,), "sigmoid")\n\n        def _backward() -> None:\n            self._accum(out.grad * s * (1 - s), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def gelu(self) -> "Tensor":\n        """Приближение tanh-GELU (как в GPT-2)."""\n        x = self.data\n        c = np.sqrt(2.0 / np.pi)\n        # x*x*x вместо x**3: NumPy не сворачивает целую степень для float32\n        # и уходит в общий pow — это в ~96 раз медленнее (16.3 мс против 0.17 мс\n        # на массиве 8x64x512). Здесь это было 40% времени шага обучения.\n        x2 = x * x\n        inner = c * (x + 0.044715 * (x2 * x))\n        t = np.tanh(inner)\n        out_data = 0.5 * x * (1 + t)\n        out = self._make(out_data, (self,), "gelu")\n\n        def _backward() -> None:\n            dinner = c * (1 + 3 * 0.044715 * x2)\n            d = 0.5 * (1 + t) + 0.5 * x * (1 - t * t) * dinner\n            self._accum(out.grad * d, shared=False)\n\n        out._backward = _backward\n        return out\n\n    def softmax(self, axis: int = -1) -> "Tensor":\n        """Fused softmax: один узел графа вместо цепочки exp/sum/div."""\n        z = self.data - self.data.max(axis=axis, keepdims=True)\n        e = np.exp(z)\n        p = e / e.sum(axis=axis, keepdims=True)\n        out = self._make(p, (self,), "softmax")\n\n        def _backward() -> None:\n            g = out.grad\n            self._accum(p * (g - (g * p).sum(axis=axis, keepdims=True)), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def log_softmax(self, axis: int = -1) -> "Tensor":\n        """Fused log-softmax — численно устойчив и дешевле по графу."""\n        z = self.data - self.data.max(axis=axis, keepdims=True)\n        lse = np.log(np.exp(z).sum(axis=axis, keepdims=True))\n        logp = z - lse\n        out = self._make(logp, (self,), "log_softmax")\n        p = np.exp(logp)\n\n        def _backward() -> None:\n            g = out.grad\n            self._accum(g - p * g.sum(axis=axis, keepdims=True), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def silu(self) -> "Tensor":\n        """SiLU / Swish: x * sigmoid(x) — используется в LLaMA-style MLP."""\n        s = 1.0 / (1.0 + np.exp(-self.data))\n        out = self._make(self.data * s, (self,), "silu")\n\n        def _backward() -> None:\n            self._accum(out.grad * (s * (1 + self.data * (1 - s))), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def abs(self) -> "Tensor":\n        out = self._make(np.abs(self.data), (self,), "abs")\n\n        def _backward() -> None:\n            self._accum(out.grad * np.sign(self.data), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def sin(self) -> "Tensor":\n        out = self._make(np.sin(self.data), (self,), "sin")\n\n        def _backward() -> None:\n            self._accum(out.grad * np.cos(self.data), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def cos(self) -> "Tensor":\n        out = self._make(np.cos(self.data), (self,), "cos")\n\n        def _backward() -> None:\n            self._accum(-out.grad * np.sin(self.data), shared=False)\n\n        out._backward = _backward\n        return out\n\n    def masked_fill(self, mask: np.ndarray, value: float) -> "Tensor":\n        """mask=True -> подставить value (используется в causal-attention)."""\n        keep = (~mask).astype(np.float32)\n        out = self._make(np.where(mask, value, self.data), (self,), "masked_fill")\n\n        def _backward() -> None:\n            self._accum(out.grad * keep, shared=False)\n\n        out._backward = _backward\n        return out\n\n    def dropout(self, p: float, training: bool = True) -> "Tensor":\n        if p <= 0.0 or not training:\n            return self\n        keep = (_RNG.random(self.shape) >= p).astype(np.float32) / (1.0 - p)\n        out = self._make(self.data * keep, (self,), "dropout")\n\n        def _backward() -> None:\n            self._accum(out.grad * keep, shared=False)\n\n        out._backward = _backward\n        return out\n\n    def clip(self, lo: float, hi: float) -> "Tensor":\n        out = self._make(np.clip(self.data, lo, hi), (self,), "clip")\n        inside = ((self.data >= lo) & (self.data <= hi)).astype(np.float32)\n\n        def _backward() -> None:\n            self._accum(out.grad * inside, shared=False)\n\n        out._backward = _backward\n        return out\n\n    # ------------------------------------------------------------------ backward\n    def backward(self, grad: Optional[np.ndarray] = None) -> None:\n        """Обратный проход в топологическом порядке."""\n        topo: list[Tensor] = []\n        visited: set[int] = set()\n        stack = [(self, False)]\n        while stack:\n            node, processed = stack.pop()\n            if processed:\n                topo.append(node)\n                continue\n            if id(node) in visited:\n                continue\n            visited.add(id(node))\n            stack.append((node, True))\n            for child in node._prev:\n                if id(child) not in visited:\n                    stack.append((child, False))\n\n        if grad is None:\n            if self.size != 1:\n                raise RuntimeError("backward() без grad возможен только для скаляра")\n            grad = np.ones_like(self.data)\n        self.grad = np.asarray(grad, dtype=np.float32)\n\n        for node in reversed(topo):\n            if node.grad is None:\n                continue  # ветка, не получившая градиента (константы, отсечённые пути)\n            node._backward()\n\n\n# --------------------------------------------------------------- конструкторы\ndef tensor(data: ArrayLike, requires_grad: bool = False) -> Tensor:\n    return Tensor(data, requires_grad=requires_grad)\n\n\ndef zeros(*shape: int, requires_grad: bool = False) -> Tensor:\n    return Tensor(np.zeros(shape, dtype=np.float32), requires_grad=requires_grad)\n\n\ndef ones(*shape: int, requires_grad: bool = False) -> Tensor:\n    return Tensor(np.ones(shape, dtype=np.float32), requires_grad=requires_grad)\n\n\ndef randn(*shape: int, requires_grad: bool = False) -> Tensor:\n    return Tensor(_RNG.standard_normal(shape).astype(np.float32), requires_grad=requires_grad)\n\n\ndef arange(n: int) -> Tensor:\n    return Tensor(np.arange(n, dtype=np.float32))\n\n\ndef stack(items: Iterable[Tensor], axis: int = 0) -> Tensor:\n    items = list(items)\n    out = Tensor(\n        np.stack([t.data for t in items], axis=axis),\n        requires_grad=any(t.requires_grad for t in items),\n        _children=items,\n        _op="stack",\n    )\n\n    def _backward() -> None:\n        grads = np.split(out.grad, len(items), axis=axis)\n        for t, g in zip(items, grads):\n            t._accum(np.squeeze(g, axis=axis))\n\n    out._backward = _backward\n    return out\n\n\ndef cat(items: Sequence[Tensor], axis: int = -1) -> Tensor:\n    items = list(items)\n    sizes = [t.shape[axis] for t in items]\n    out = Tensor(\n        np.concatenate([t.data for t in items], axis=axis),\n        requires_grad=any(t.requires_grad for t in items),\n        _children=items,\n        _op="cat",\n    )\n\n    def _backward() -> None:\n        idx = np.cumsum(sizes)[:-1]\n        for t, g in zip(items, np.split(out.grad, idx, axis=axis)):\n            t._accum(g)\n\n    out._backward = _backward\n    return out\n'

_SOURCES['ultranet.tokenizer'] = '"""BPE-токенизатор (byte pair encoding) — как в GPT-2, но компактный.\n\nРаботает на уровне байтов, поэтому кодирует любой UTF-8 текст без <unk>.\n"""\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom collections import Counter\nfrom typing import Dict, List, Optional, Tuple\n\n\n_CHUNK_RE = re.compile(r"\\s*\\S+|\\s+")\n_MAX_CHUNK = 64\n\n\ndef _split_chunks(text: str):\n    """Резать по границам слов, длинные куски дробить.\n\n    Слияния BPE почти никогда не пересекают пробел, поэтому счёт по\n    словам даёт тот же результат, но кэшируется.\n    """\n    for m in _CHUNK_RE.finditer(text):\n        chunk = m.group()\n        if len(chunk) <= _MAX_CHUNK:\n            yield chunk\n        else:\n            for i in range(0, len(chunk), _MAX_CHUNK):\n                yield chunk[i:i + _MAX_CHUNK]\n\n\nclass BPETokenizer:\n    """Обучаемый BPE: словарь = 256 байт + выученные слияния.\n\n    >>> tok = BPETokenizer.train(text, vocab_size=512)\n    >>> tok.decode(tok.encode("привет")) == "привет"\n    True\n    """\n\n    #: потолок кэша, чтобы он не рос бесконечно на больших корпусах\n    _CACHE_MAX = 200_000\n\n    def __init__(self, merges: Optional[Dict[Tuple[int, int], int]] = None,\n                 special: Optional[Dict[str, int]] = None) -> None:\n        self.merges: Dict[Tuple[int, int], int] = merges or {}\n        self.special = special or {}\n        #: кэш «кусок текста -> токены»: одни и те же слова встречаются\n        #: миллионы раз, пересчитывать их каждый раз незачем\n        self._cache: Dict[str, List[int]] = {}\n        self._build_vocab()\n\n    def _build_vocab(self) -> None:\n        self.vocab: Dict[int, bytes] = {i: bytes([i]) for i in range(256)}\n        for (a, b), idx in sorted(self.merges.items(), key=lambda kv: kv[1]):\n            self.vocab[idx] = self.vocab[a] + self.vocab[b]\n        for tokstr, idx in self.special.items():\n            self.vocab[idx] = tokstr.encode("utf-8")\n\n    @property\n    def vocab_size(self) -> int:\n        return len(self.vocab)\n\n    # ------------------------------------------------------------------ обучение\n    @staticmethod\n    def _pair_counts(ids: List[int]) -> Counter:\n        return Counter(zip(ids, ids[1:]))\n\n    @staticmethod\n    def _merge(ids: List[int], pair: Tuple[int, int], new_id: int) -> List[int]:\n        out, i, n = [], 0, len(ids)\n        a, b = pair\n        while i < n:\n            if i < n - 1 and ids[i] == a and ids[i + 1] == b:\n                out.append(new_id)\n                i += 2\n            else:\n                out.append(ids[i])\n                i += 1\n        return out\n\n    @classmethod\n    def train(cls, text: str, vocab_size: int = 512, verbose: bool = False) -> "BPETokenizer":\n        """Выучить слияния так, чтобы итоговый словарь был не больше vocab_size."""\n        assert vocab_size >= 256, "словарь не может быть меньше 256 байт"\n        # Обучение идёт по тем же кускам, что и encode. Иначе словарь\n        # копит слияния через пробел, которые encode применить не может,\n        # и реальное сжатие оказывается хуже измеренного при обучении.\n        chunks = [list(c.encode("utf-8")) for c in _split_chunks(text)]\n        merges: Dict[Tuple[int, int], int] = {}\n        for new_id in range(256, vocab_size):\n            counts: Counter = Counter()\n            for ids in chunks:\n                counts.update(zip(ids, ids[1:]))\n            if not counts:\n                break\n            pair, freq = counts.most_common(1)[0]\n            if freq < 2:\n                break\n            chunks = [cls._merge(ids, pair, new_id) if len(ids) >= 2 else ids\n                      for ids in chunks]\n            merges[pair] = new_id\n            if verbose and new_id % 50 == 0:\n                total = sum(len(c) for c in chunks)\n                print(f"  слияние {new_id}: {pair} x{freq} -> длина {total}")\n        return cls(merges)\n\n    # -------------------------------------------------------------- кодирование\n    def encode(self, text: str) -> List[int]:\n        """Кодирование по выученным слияниям.\n\n        Наивная реализация пересчитывала пары по ВСЕМУ тексту на каждое\n        слияние: O(число_слияний × длина). На 8 КБ это 237 проходов и\n        ~27k символов/с — токенизация TinyStories заняла бы 19 часов.\n\n        Здесь текст режется на куски по границам пробелов, слияния\n        применяются внутри куска, а результат кэшируется: одинаковые\n        слова встречаются миллионы раз и считаются один раз.\n        """\n        if not self.merges:\n            return list(text.encode("utf-8"))\n        out: List[int] = []\n        for chunk in _split_chunks(text):\n            cached = self._cache.get(chunk)\n            if cached is None:\n                cached = self._encode_chunk(chunk)\n                if len(self._cache) < self._CACHE_MAX:\n                    self._cache[chunk] = cached\n            out.extend(cached)\n        return out\n\n    def _encode_chunk(self, chunk: str) -> List[int]:\n        """Слияния внутри одного короткого куска, по возрастанию ранга."""\n        ids = list(chunk.encode("utf-8"))\n        if len(ids) < 2:\n            return ids\n        merges = self.merges\n        while True:\n            best_rank = None\n            best_pos = -1\n            for i in range(len(ids) - 1):\n                rank = merges.get((ids[i], ids[i + 1]))\n                if rank is not None and (best_rank is None or rank < best_rank):\n                    best_rank, best_pos = rank, i\n            if best_rank is None:\n                return ids\n            ids[best_pos:best_pos + 2] = [best_rank]\n\n    def decode(self, ids) -> str:\n        data = b"".join(self.vocab[int(i)] for i in ids)\n        return data.decode("utf-8", errors="replace")\n\n    def compression_ratio(self, text: str) -> float:\n        """Во сколько раз короче последовательность по сравнению с байтами."""\n        return len(text.encode("utf-8")) / max(len(self.encode(text)), 1)\n\n    # ------------------------------------------------------------- сериализация\n    def save(self, path: str) -> None:\n        payload = {\n            "merges": [[list(k), v] for k, v in self.merges.items()],\n            "special": self.special,\n        }\n        with open(path, "w", encoding="utf-8") as f:\n            json.dump(payload, f, ensure_ascii=False)\n\n    @classmethod\n    def load(cls, path: str) -> "BPETokenizer":\n        with open(path, encoding="utf-8") as f:\n            payload = json.load(f)\n        merges = {tuple(k): v for k, v in payload["merges"]}\n        return cls(merges, payload.get("special", {}))\n'

_SOURCES['ultranet.torch_port'] = '"""Порт GPT на PyTorch: тот же счёт, те же веса, те же сэмплы.\n\nNumPy-движок остаётся референсом. Эта версия нужна только чтобы обучать\nна GPU, и она обязана совпадать с референсом численно — иначе обучится\nне та модель, которую мы проверяли.\n\nПять мест, где совпадение легко потерять (все учтены ниже):\n\n1. Linear хранит вес как (in, out), у torch — (out, in). При переносе\n   нужен транспонс, иначе матрица перемножится наоборот.\n2. RMSNorm в референсе делит на sqrt(mean(x^2) + eps), а torch-версии\n   часто пишут sqrt(mean(x^2)) + eps или rsqrt. Это разные числа.\n3. RoPE в референсе чередует соседние элементы (0,1), (2,3)...,\n   а в HF-моделях половинки (i, i+hd/2). Порядок менять нельзя.\n4. Causal-маска заполняется -1e9, а не -inf: -inf даёт NaN в softmax\n   на полностью замаскированных строках.\n5. GELU — приближение tanh, а не точная erf-версия.\n\nИспользование:\n    from ultranet.torch_port import TorchGPT, convert_weights\n    tm = TorchGPT(cfg)\n    convert_weights(numpy_model, tm)      # веса référence -> torch\n"""\nfrom __future__ import annotations\n\nimport math\nfrom typing import Optional\n\nimport numpy as np\n\ntry:\n    import torch\n    import torch.nn as tnn\n    import torch.nn.functional as TF\nexcept ImportError as e:  # pragma: no cover\n    raise ImportError("нужен torch: pip install torch") from e\n\n\n# ═════════════════════════════════════════════════════════════ слои\nclass RMSNorm(tnn.Module):\n    """Точно как референс: x / sqrt(mean(x^2) + eps) * gamma."""\n\n    def __init__(self, dim: int, eps: float = 1e-6) -> None:\n        super().__init__()\n        self.eps = eps\n        self.gamma = tnn.Parameter(torch.ones(dim))\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        rms = torch.sqrt(x.pow(2).mean(-1, keepdim=True) + self.eps)\n        return x / rms * self.gamma\n\n\nclass LayerNorm(tnn.Module):\n    def __init__(self, dim: int, eps: float = 1e-5) -> None:\n        super().__init__()\n        self.eps = eps\n        self.gamma = tnn.Parameter(torch.ones(dim))\n        self.beta = tnn.Parameter(torch.zeros(dim))\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        mu = x.mean(-1, keepdim=True)\n        var = (x - mu).pow(2).mean(-1, keepdim=True)\n        return (x - mu) / torch.sqrt(var + self.eps) * self.gamma + self.beta\n\n\ndef gelu_tanh(x: torch.Tensor) -> torch.Tensor:\n    """Приближение tanh-GELU — как в референсе (не erf!)."""\n    c = math.sqrt(2.0 / math.pi)\n    return 0.5 * x * (1.0 + torch.tanh(c * (x + 0.044715 * x * x * x)))\n\n\nclass RotaryEmbedding(tnn.Module):\n    """RoPE с чередованием соседних элементов — как в референсе."""\n\n    def __init__(self, head_dim: int, max_seq: int = 4096, base: float = 10000.0) -> None:\n        super().__init__()\n        inv = 1.0 / (base ** (np.arange(0, head_dim, 2, dtype=np.float32) / head_dim))\n        t = np.arange(max_seq, dtype=np.float32)\n        freqs = np.outer(t, inv)\n        self.register_buffer("cos", torch.tensor(np.cos(freqs), dtype=torch.float32))\n        self.register_buffer("sin", torch.tensor(np.sin(freqs), dtype=torch.float32))\n\n    def forward(self, x: torch.Tensor, offset: int = 0) -> torch.Tensor:\n        t = x.shape[2]\n        cos = self.cos[offset:offset + t][None, None]\n        sin = self.sin[offset:offset + t][None, None]\n        x1, x2 = x[..., 0::2], x[..., 1::2]\n        r1 = x1 * cos - x2 * sin\n        r2 = x1 * sin + x2 * cos\n        return torch.stack((r1, r2), dim=-1).flatten(-2)\n\n\nclass MultiHeadAttention(tnn.Module):\n    def __init__(self, dim: int, n_heads: int, dropout: float = 0.0, causal: bool = True,\n                 rope: bool = False, max_seq: int = 4096) -> None:\n        super().__init__()\n        self.dim, self.n_heads, self.head_dim = dim, n_heads, dim // n_heads\n        self.causal = causal\n        self.qkv = tnn.Linear(dim, 3 * dim, bias=False)\n        self.proj = tnn.Linear(dim, dim, bias=True)\n        self.drop_p = dropout\n        self.rope = RotaryEmbedding(self.head_dim, max_seq) if rope else None\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        b, t, c = x.shape\n        qkv = self.qkv(x).reshape(b, t, 3, self.n_heads, self.head_dim).permute(2, 0, 3, 1, 4)\n        q, k, v = qkv[0], qkv[1], qkv[2]\n        if self.rope is not None:\n            q, k = self.rope(q), self.rope(k)\n\n        att = (q @ k.transpose(-1, -2)) * (1.0 / math.sqrt(self.head_dim))\n        if self.causal:\n            mask = torch.triu(torch.ones(t, t, dtype=torch.bool, device=x.device), 1)\n            # -1e9, а не -inf: -inf даёт NaN на полностью замаскированных строках\n            att = att.masked_fill(mask, -1e9)\n        att = torch.softmax(att, dim=-1)\n        att = TF.dropout(att, self.drop_p, self.training)\n        y = (att @ v).transpose(1, 2).reshape(b, t, c)\n        return TF.dropout(self.proj(y), self.drop_p, self.training)\n\n\nclass SwiGLU(tnn.Module):\n    def __init__(self, dim: int, hidden: Optional[int] = None, dropout: float = 0.0) -> None:\n        super().__init__()\n        hidden = hidden or int(8 * dim / 3 // 32 * 32) or 4 * dim\n        self.w_gate = tnn.Linear(dim, hidden, bias=False)\n        self.w_up = tnn.Linear(dim, hidden, bias=False)\n        self.w_down = tnn.Linear(hidden, dim, bias=False)\n        self.drop_p = dropout\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        h = TF.silu(self.w_gate(x)) * self.w_up(x)\n        return TF.dropout(self.w_down(h), self.drop_p, self.training)\n\n\nclass GELUMLP(tnn.Module):\n    def __init__(self, dim: int, ratio: int = 4, dropout: float = 0.0) -> None:\n        super().__init__()\n        self.fc1 = tnn.Linear(dim, ratio * dim, bias=True)\n        self.fc2 = tnn.Linear(ratio * dim, dim, bias=True)\n        self.drop_p = dropout\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        return TF.dropout(self.fc2(gelu_tanh(self.fc1(x))), self.drop_p, self.training)\n\n\nclass TransformerBlock(tnn.Module):\n    def __init__(self, dim: int, n_heads: int, dropout: float, causal: bool,\n                 rope: bool, norm: str, swiglu: bool, max_seq: int) -> None:\n        super().__init__()\n        mk = (lambda: RMSNorm(dim)) if norm == "rms" else (lambda: LayerNorm(dim))\n        self.ln1 = mk()\n        self.attn = MultiHeadAttention(dim, n_heads, dropout, causal, rope, max_seq)\n        self.ln2 = mk()\n        self.mlp = SwiGLU(dim, dropout=dropout) if swiglu else GELUMLP(dim, 4, dropout)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        x = x + self.attn(self.ln1(x))\n        return x + self.mlp(self.ln2(x))\n\n\nclass TorchGPT(tnn.Module):\n    """GPT с той же арифметикой, что у NumPy-референса."""\n\n    def __init__(self, cfg) -> None:\n        super().__init__()\n        self.cfg = cfg\n        self.tok_emb = tnn.Embedding(cfg.vocab_size, cfg.n_embd)\n        self.pos_emb = None if cfg.rope else tnn.Embedding(cfg.block_size, cfg.n_embd)\n        self.drop_p = cfg.dropout\n        self.blocks = tnn.ModuleList([\n            TransformerBlock(cfg.n_embd, cfg.n_head, cfg.dropout, True,\n                             cfg.rope, cfg.norm, cfg.swiglu, cfg.block_size * 4)\n            for _ in range(cfg.n_layer)])\n        self.ln_f = RMSNorm(cfg.n_embd) if cfg.norm == "rms" else LayerNorm(cfg.n_embd)\n        self.head = None if cfg.tie_weights else tnn.Linear(cfg.n_embd, cfg.vocab_size, bias=False)\n        self._init_like_reference()\n\n    def _init_like_reference(self) -> None:\n        """Инициализация ровно как в NumPy-референсе.\n\n        Умолчания torch тут не подходят: Embedding он инициализирует\n        как N(0, 1), а референс — N(0, 0.02). При tie_weights эта же\n        матрица работает выходной головой, поэтому логиты на старте\n        получаются в ~50 раз крупнее нужного, и loss стартует с ~240\n        вместо ln(vocab) ≈ 8.3. Такой старт либо расходится, либо\n        тратит первые тысячи шагов на возврат к нормальному масштабу.\n\n        Ошибка не видна при convert_weights (там веса приходят готовыми)\n        и проявляется только при обучении с нуля.\n        """\n        cfg = self.cfg\n        tnn.init.normal_(self.tok_emb.weight, mean=0.0, std=0.02)\n        if self.pos_emb is not None:\n            tnn.init.normal_(self.pos_emb.weight, mean=0.0, std=0.02)\n\n        for m in self.modules():\n            if isinstance(m, tnn.Linear):\n                # kaiming с gain=2.0, как kaiming() в ultranet.nn\n                fan_in = m.weight.shape[1]\n                tnn.init.normal_(m.weight, mean=0.0, std=math.sqrt(2.0 / fan_in))\n                if m.bias is not None:\n                    tnn.init.zeros_(m.bias)\n\n        # масштабированная инициализация остаточных проекций (GPT-2 § 2.3)\n        scale = 1.0 / math.sqrt(2 * cfg.n_layer)\n        for blk in self.blocks:\n            blk.attn.proj.weight.data *= scale\n        if self.head is not None:\n            tnn.init.normal_(self.head.weight, mean=0.0, std=0.02)\n\n    def forward(self, idx: torch.Tensor, targets: Optional[torch.Tensor] = None):\n        b, t = idx.shape\n        x = self.tok_emb(idx)\n        if self.pos_emb is not None:\n            pos = torch.arange(t, device=idx.device)\n            x = x + self.pos_emb(pos)[None]\n        x = TF.dropout(x, self.drop_p, self.training)\n        for blk in self.blocks:\n            x = blk(x)\n        x = self.ln_f(x)\n        logits = x @ self.tok_emb.weight.T if self.head is None else self.head(x)\n        if targets is None:\n            return logits\n        loss = TF.cross_entropy(logits.reshape(-1, logits.size(-1)), targets.reshape(-1))\n        return logits, loss\n\n\n# ═══════════════════════════════════════════════════ перенос весов\ndef _T(w: np.ndarray) -> torch.Tensor:\n    """(in, out) референса -> (out, in) torch."""\n    return torch.tensor(np.ascontiguousarray(w.T), dtype=torch.float32)\n\n\ndef _V(w: np.ndarray) -> torch.Tensor:\n    return torch.tensor(np.ascontiguousarray(w), dtype=torch.float32)\n\n\n@torch.no_grad()\ndef convert_weights(np_model, t_model: TorchGPT) -> TorchGPT:\n    """Перенести веса из NumPy-модели в torch-модель — один в один."""\n    t_model.tok_emb.weight.copy_(_V(np_model.tok_emb.weight.data))\n    if np_model.pos_emb is not None and t_model.pos_emb is not None:\n        t_model.pos_emb.weight.copy_(_V(np_model.pos_emb.weight.data))\n\n    for nb, tb in zip(np_model.blocks, t_model.blocks):\n        _copy_norm(nb.ln1, tb.ln1)\n        _copy_norm(nb.ln2, tb.ln2)\n        tb.attn.qkv.weight.copy_(_T(nb.attn.qkv.weight.data))\n        tb.attn.proj.weight.copy_(_T(nb.attn.proj.weight.data))\n        if nb.attn.proj.bias is not None:\n            tb.attn.proj.bias.copy_(_V(nb.attn.proj.bias.data))\n        if isinstance(tb.mlp, SwiGLU):\n            tb.mlp.w_gate.weight.copy_(_T(nb.mlp.w_gate.weight.data))\n            tb.mlp.w_up.weight.copy_(_T(nb.mlp.w_up.weight.data))\n            tb.mlp.w_down.weight.copy_(_T(nb.mlp.w_down.weight.data))\n        else:\n            lin = [m for m in nb.mlp.layers if hasattr(m, "weight")]\n            tb.mlp.fc1.weight.copy_(_T(lin[0].weight.data))\n            tb.mlp.fc1.bias.copy_(_V(lin[0].bias.data))\n            tb.mlp.fc2.weight.copy_(_T(lin[1].weight.data))\n            tb.mlp.fc2.bias.copy_(_V(lin[1].bias.data))\n\n    _copy_norm(np_model.ln_f, t_model.ln_f)\n    if np_model.head is not None and t_model.head is not None:\n        t_model.head.weight.copy_(_T(np_model.head.weight.data))\n    return t_model\n\n\n@torch.no_grad()\ndef _copy_norm(n_norm, t_norm) -> None:\n    if hasattr(n_norm, "gamma"):\n        t_norm.gamma.copy_(_V(n_norm.gamma.data))\n    if hasattr(n_norm, "beta") and hasattr(t_norm, "beta"):\n        t_norm.beta.copy_(_V(n_norm.beta.data))\n\n\ndef max_abs_diff(a: np.ndarray, b: np.ndarray) -> float:\n    return float(np.abs(np.asarray(a, dtype=np.float64) - np.asarray(b, dtype=np.float64)).max())\n'

_SOURCES['ultranet.trainer'] = '"""Тренер: цикл обучения, валидация, ранняя остановка, EMA, чекпоинты."""\nfrom __future__ import annotations\n\nimport time\nfrom typing import Callable, Dict, List, Optional\n\nimport numpy as np\n\nfrom .data import DataLoader\nfrom .functional import accuracy, cross_entropy\nfrom .nn import Module\nfrom .optim import EMA, Optimizer\nfrom .checkpoint import load_checkpoint, save_checkpoint\nfrom .tensor import Tensor, no_grad\n\n\ndef _fmt_time(sec: float) -> str:\n    return f"{sec:.1f}s" if sec < 60 else f"{int(sec // 60)}m{int(sec % 60):02d}s"\n\n\ndef _bar(frac: float, width: int = 20) -> str:\n    filled = int(frac * width)\n    return "█" * filled + "░" * (width - filled)\n\n\nclass Trainer:\n    """Универсальный цикл обучения.\n\n    Возможности: валидация, ранняя остановка с откатом к лучшим весам,\n    накопление градиентов, EMA-веса, чекпоинты, коллбэки, прогресс-бар.\n    """\n\n    def __init__(self, model: Module, optimizer: Optimizer,\n                 loss_fn: Callable = cross_entropy,\n                 scheduler=None, grad_clip: Optional[float] = None,\n                 metric: Optional[Callable] = accuracy, verbose: bool = True,\n                 accum_steps: int = 1, ema_decay: Optional[float] = None,\n                 checkpoint_path: Optional[str] = None,\n                 callbacks: Optional[List[Callable]] = None) -> None:\n        self.model, self.opt = model, optimizer\n        self.loss_fn, self.scheduler = loss_fn, scheduler\n        self.grad_clip, self.metric, self.verbose = grad_clip, metric, verbose\n        self.accum_steps = max(1, accum_steps)\n        self.checkpoint_path = checkpoint_path\n        self.callbacks = callbacks or []\n        self.ema = EMA(model.parameters(), ema_decay) if ema_decay else None\n        self.history: Dict[str, List[float]] = {\n            "loss": [], "val_loss": [], "metric": [], "val_metric": [], "lr": [], "grad_norm": []\n        }\n        self.best_score = np.inf\n        self._stop = False\n\n    # ------------------------------------------------------------------ шаги\n    def _forward(self, xb: np.ndarray, yb: np.ndarray):\n        inp = xb if np.issubdtype(np.asarray(xb).dtype, np.integer) else Tensor(xb)\n        out = self.model(inp)\n        return out, self.loss_fn(out, yb)\n\n    def _train_epoch(self, loader: DataLoader, epoch: int, epochs: int):\n        self.model.train()\n        losses, metrics, gnorms = [], [], []\n        n_batches = len(loader)\n        t0 = time.time()\n        self.opt.zero_grad()\n\n        for i, (xb, yb) in enumerate(loader, 1):\n            out, loss = self._forward(xb, yb)\n            (loss * (1.0 / self.accum_steps)).backward()\n\n            if i % self.accum_steps == 0 or i == n_batches:\n                gn = self.opt.clip_grad_norm(self.grad_clip) if self.grad_clip else 0.0\n                gnorms.append(gn)\n                self.opt.step()\n                self.opt.zero_grad()\n                if self.scheduler is not None:\n                    self.scheduler.step()\n                if self.ema is not None:\n                    self.ema.update()\n\n            losses.append(loss.item())\n            if self.metric:\n                metrics.append(self.metric(out, yb))\n\n            if self.verbose and (i % max(1, n_batches // 10) == 0 or i == n_batches):\n                print(f"\\r  эпоха {epoch}/{epochs} {_bar(i / n_batches)} "\n                      f"{i}/{n_batches} loss={np.mean(losses[-50:]):.4f}", end="", flush=True)\n\n        if self.verbose:\n            print("\\r" + " " * 80, end="\\r")\n        return float(np.mean(losses)), float(np.mean(metrics)) if metrics else 0.0, \\\n            float(np.mean(gnorms)) if gnorms else 0.0, time.time() - t0\n\n    # ------------------------------------------------------------------- цикл\n    def fit(self, train_loader: DataLoader, val_loader: Optional[DataLoader] = None,\n            epochs: int = 10, patience: Optional[int] = None,\n            monitor: str = "val_loss") -> Dict[str, List[float]]:\n        bad, best_state = 0, None\n        self.best_score = np.inf\n\n        for ep in range(1, epochs + 1):\n            loss, metric, gnorm, dt = self._train_epoch(train_loader, ep, epochs)\n            self.history["loss"].append(loss)\n            self.history["metric"].append(metric)\n            self.history["lr"].append(self.opt.lr)\n            self.history["grad_norm"].append(gnorm)\n\n            msg = f"эпоха {ep:3d}/{epochs} | loss {loss:.4f} | metric {metric:.4f}"\n            if val_loader is not None:\n                vl, vm = self.evaluate(val_loader, use_ema=self.ema is not None)\n                self.history["val_loss"].append(vl)\n                self.history["val_metric"].append(vm)\n                msg += f" | val_loss {vl:.4f} | val_metric {vm:.4f}"\n                score = vl if monitor == "val_loss" else -vm\n            else:\n                score = loss\n            msg += f" | lr {self.opt.lr:.2e} | {_fmt_time(dt)}"\n            if self.verbose:\n                print(msg)\n\n            improved = score < self.best_score - 1e-6\n            if improved:\n                self.best_score, bad = score, 0\n                best_state = self.model.state_dict()\n                if self.checkpoint_path:\n                    save_checkpoint(self.checkpoint_path, self.model, self.opt,\n                                    epoch=ep, step=self.opt.t, history=self.history,\n                                    best_score=self.best_score)\n            else:\n                bad += 1\n\n            for cb in self.callbacks:\n                cb(self, ep)\n            if self._stop:\n                if self.verbose:\n                    print("остановлено коллбэком")\n                break\n            if patience is not None and bad >= patience:\n                if self.verbose:\n                    print(f"ранняя остановка на эпохе {ep} (лучший {monitor}={self.best_score:.4f})")\n                if best_state:\n                    self.model.load_state_dict(best_state)\n                break\n\n        return self.history\n\n    def resume(self, path: str) -> int:\n        """Продолжить обучение из чекпоинта; возвращает номер эпохи."""\n        ck = load_checkpoint(path, self.model, self.opt)\n        if ck.get("history"):\n            self.history = ck["history"]\n        self.best_score = ck.get("extra", {}).get("best_score", np.inf)\n        return int(ck.get("epoch", 0))\n\n    def stop(self) -> None:\n        """Прервать обучение из коллбэка."""\n        self._stop = True\n\n    # -------------------------------------------------------------- инференс\n    @no_grad()\n    def evaluate(self, loader: DataLoader, use_ema: bool = False):\n        if use_ema and self.ema is not None:\n            self.ema.apply()\n        self.model.eval()\n        losses, metrics = [], []\n        for xb, yb in loader:\n            out, loss = self._forward(xb, yb)\n            losses.append(loss.item())\n            if self.metric:\n                metrics.append(self.metric(out, yb))\n        self.model.train()\n        if use_ema and self.ema is not None:\n            self.ema.restore()\n        return float(np.mean(losses)), float(np.mean(metrics)) if metrics else 0.0\n\n    @no_grad()\n    def predict(self, x: np.ndarray) -> np.ndarray:\n        self.model.eval()\n        inp = x if np.issubdtype(np.asarray(x).dtype, np.integer) else Tensor(x)\n        out = self.model(inp).data\n        self.model.train()\n        return out\n\n    def plot_history(self, width: int = 56, height: int = 12) -> str:\n        """ASCII-график кривых обучения (работает без matplotlib)."""\n        tr, va = self.history["loss"], self.history["val_loss"]\n        if not tr:\n            return "(история пуста)"\n        series = [("train", tr, "*"), ("val", va, "o")] if va else [("train", tr, "*")]\n        lo = min(min(s) for _, s, _ in series)\n        hi = max(max(s) for _, s, _ in series)\n        rng = max(hi - lo, 1e-9)\n        grid = [[" "] * width for _ in range(height)]\n        for _, s, ch in series:\n            for i, v in enumerate(s):\n                col = int(i / max(len(s) - 1, 1) * (width - 1))\n                row = height - 1 - int((v - lo) / rng * (height - 1))\n                grid[row][col] = ch\n        lines = [f"{hi:7.4f} ┤" + "".join(grid[0])]\n        lines += ["        │" + "".join(r) for r in grid[1:-1]]\n        lines.append(f"{lo:7.4f} ┤" + "".join(grid[-1]))\n        lines.append("        └" + "─" * width)\n        legend = "  ".join(f"{ch} {name}" for name, _, ch in series)\n        lines.append(f"         эпохи 1..{len(tr)}    {legend}")\n        return "\\n".join(lines)\n'



# ═════════════════════════════════════════════════════════════════════
# Регистрация пакета в sys.modules
# ═════════════════════════════════════════════════════════════════════
class _BundleLoader:
    """Загрузчик, отдающий модули из _SOURCES.

    Заранее исполнять модули в угаданном порядке нельзя: между ними
    взаимные зависимости (например ultranet.__main__ импортирует
    ultranet.cli). Поэтому модуль исполняется в момент первого импорта —
    порядок разрешает сам Python.
    """

    PACKAGES = {"ultranet", "ultranet.proteus"}

    def find_module(self, fullname, path=None):      # старый протокол
        return self if fullname in _SOURCES else None

    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _SOURCES:
            return None
        return ModuleSpec(fullname, self,
                          is_package=fullname in self.PACKAGES)

    def create_module(self, spec):
        return None                                   # обычный модуль

    def exec_module(self, module):
        name = module.__name__
        module.__file__ = f"<bundled {name}>"
        if name in self.PACKAGES:
            module.__path__ = []
            module.__package__ = name
        else:
            module.__package__ = name.rsplit(".", 1)[0]
        exec(compile(_SOURCES[name], module.__file__, "exec"), module.__dict__)

    def load_module(self, fullname):                  # старый протокол
        if fullname in sys.modules:
            return sys.modules[fullname]
        mod = types.ModuleType(fullname)
        mod.__loader__ = self
        sys.modules[fullname] = mod
        try:
            self.exec_module(mod)
        except Exception:
            sys.modules.pop(fullname, None)
            raise
        return mod


sys.meta_path.insert(0, _BundleLoader())


